INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：红 hóng 指像火或太阳一样的颜色。"}, {"text": "烘", "is_correct": false, "explanation": "hōng（第一声）与 hóng（第二声）声调不同，意思是烘烤。"}, {"text": "轰", "is_correct": false, "explanation": "hōng（第一声）与 hóng（第二声）声调不同，意思是轰鸣。"}, {"text": "哄", "is_correct": false, "explanation": "hòng（第四声）与 hóng（第二声）声调不同，意思是起哄。"}, {"text": "横", "is_correct": false, "explanation": "héng 与 hóng 韵母不同（e 与 o），意思是横向。"}], "explanations": {"红": "正确：红 hóng 指像火或太阳一样的颜色。", "烘": "hōng（第一声）与 hóng（第二声）声调不同，意思是烘烤。", "轰": "hōng（第一声）与 hóng（第二声）声调不同，意思是轰鸣。", "哄": "hòng（第四声）与 hóng（第二声）声调不同，意思是起哄。", "横": "héng 与 hóng 韵母不同（e 与 o），意思是横向。"}, "sentence_index": null, "correct_answer": "红"}, "level_3": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：傍晚的太阳是红色的，与“又大又……”相符。"}, {"text": "冷", "is_correct": false, "explanation": "语义：太阳发出的是热和光，傍晚的太阳不会“冷”，与“又大又……”的描述矛盾。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”用于柔软的物体，不说太阳“软”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：太阳不是甜的，“甜”与太阳的性质不符。"}], "explanations": {"红": "正确：傍晚的太阳是红色的，与“又大又……”相符。", "冷": "语义：太阳发出的是热和光，傍晚的太阳不会“冷”，与“又大又……”的描述矛盾。", "软": "搭配：“软”用于柔软的物体，不说太阳“软”。", "甜": "语义：太阳不是甜的，“甜”与太阳的性质不符。"}, "sentence_index": 0, "correct_answer": "红"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节目的收视很红，每周都有很多人看。", "explanation": "这里的“红”指受欢迎（另一义项），不表示颜色，用于收视不对，应该用〈高〉。"}, {"text": "我表妹的葬礼办得很红，要请很多客人。", "explanation": "这里的“红”指喜庆（红事即喜事），是另一个义项，用于葬礼不合适，葬礼应说〈白事〉。"}, {"text": "这个孩子的身高很红，一直是班上最高的。", "explanation": "这里的“红”指盈利（红盘）义项，不表示颜色，用于身高不对，应该用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27658, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：红 hóng 指像火或太阳一样的颜色。"}, {"text": "猴", "is_correct": false, "explanation": "hóu 与 hóng 韵尾不同（u 与 ng），意思是猴子。"}, {"text": "航", "is_correct": false, "explanation": "háng 与 hóng 韵母不同（a 与 o），意思是航行。"}, {"text": "恒", "is_correct": false, "explanation": "héng 与 hóng 韵母不同（e 与 o），意思是恒久。"}], "explanations": {"红": "正确：红 hóng 指像火或太阳一样的颜色。", "猴": "hóu 与 hóng 韵尾不同（u 与 ng），意思是猴子。", "航": "háng 与 hóng 韵母不同（a 与 o），意思是航行。", "恒": "héng 与 hóng 韵母不同（e 与 o），意思是恒久。"}, "sentence_index": null, "correct_answer": "红"}, "level_3": {"options": [{"text": "红", "is_correct": true, "explanation": "正确：云彩在日落时泛红，与后半句“明天会是好天气”相符。"}, {"text": "黑", "is_correct": false, "explanation": "语义：乌云通常意味着下雨，与后半句“明天会是好天气”矛盾。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”一般不用来形容云，这里不搭配。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”用于味道，不能用来形容云。"}], "explanations": {"红": "正确：云彩在日落时泛红，与后半句“明天会是好天气”相符。", "黑": "语义：乌云通常意味着下雨，与后半句“明天会是好天气”矛盾。", "脏": "搭配：“脏”一般不用来形容云，这里不搭配。", "咸": "搭配：“咸”用于味道，不能用来形容云。"}, "sentence_index": 6, "correct_answer": "红"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老一辈的人常讲这段红利的故事。", "explanation": "这里的“红”指盈利（红利义项），不表示颜色，用于故事不合适，应该说〈传说〉。"}, {"text": "这位演员的价格很红，一场戏要很多钱。", "explanation": "这里的“红”指受欢迎（红人义项），不表示颜色，用于价格不对，应该用〈高〉。"}, {"text": "这家公司今年的红事很多，股东都很高兴。", "explanation": "这里的“红事”指喜事义项（喜庆），不表示颜色，应该用〈好事〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕阳落山了，天边红像火一样。", "corrected_sentence": "夕阳落山了，天边红得像火一样。", "error_description": "应为“红得像火一样”。“红”后接表示状态的补语“像火一样”时要用“得”连接，“红像……”缺少“得”，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "篝火烧红红的，火星四处飞。", "corrected_sentence": "篝火烧得红红的，火星四处飞。", "error_description": "应为“烧得红红的”。“红红的”作结果补语时要用“得”连接，“烧红红的”少了“得”，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
