INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蠕虫是一种长得像细细的绳子的小动物，它会在土里爬来爬去。", "primary_collocate": null, "pronunciation": "rú chóng", "ipa": "ɻu˧˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "地上有一条蠕虫，像一根细绳子。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫在土里爬来爬去。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩在花园里发现了一条蠕虫。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫没有脚，走得很慢。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，很多蠕虫从土里出来。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的孩子不怕蠕虫，还把它放在手上。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蠕虫很小，只有一厘米长。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡看见蠕虫，马上跑过去吃。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一条红色的蠕虫。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蠕虫喜欢住在湿湿的土里。", "target_word": "蠕虫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠕蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像细绳子、在土里爬行的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蠕虫", "is_correct": true, "explanation": "正确：蠕虫细长，与“像一根细绳子”的比喻相符。"}, {"text": "龙", "is_correct": false, "explanation": "语义：龙体型庞大，不会是像细绳子一样的东西，与“像一根细绳子”矛盾。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼生活在海里，不会出现在地上，与“地上有一条”的情境矛盾。"}, {"text": "巨蟒", "is_correct": false, "explanation": "体貌：巨蟒身体粗大，与“像一根细绳子”的细长形象矛盾。"}], "explanations": {"蠕虫": "正确：蠕虫细长，与“像一根细绳子”的比喻相符。", "龙": "语义：龙体型庞大，不会是像细绳子一样的东西，与“像一根细绳子”矛盾。", "鲨鱼": "语义：鲨鱼生活在海里，不会出现在地上，与“地上有一条”的情境矛盾。", "巨蟒": "体貌：巨蟒身体粗大，与“像一根细绳子”的细长形象矛盾。"}, "sentence_index": 0, "correct_answer": "蠕虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在草地上捡到一朵蠕虫。", "explanation": "这里应该用〈条〉。“朵”用于花，蠕虫是细长的，不能用“朵”来数。"}, {"text": "老师拿出一头蠕虫给我们看。", "explanation": "这里应该用〈条〉。“头”多用于牛、猪等大牲畜，不用于蠕虫。"}, {"text": "池塘边有一匹蠕虫在爬。", "explanation": "这里应该用〈条〉。“匹”专用于马、骡等动物，蠕虫不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蠕虫", "is_correct": true, "explanation": "正确：蠕虫很小，只有一厘米长，符合这个描述。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不可能只有一厘米长，与后半句“只有一厘米长”矛盾。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路不会只有一厘米长，与“很小，只有一厘米长”的描述矛盾。"}, {"text": "鲸鱼", "is_correct": false, "explanation": "体貌：鲸鱼体型巨大，不可能“很小，只有一厘米长”。"}], "explanations": {"蠕虫": "正确：蠕虫很小，只有一厘米长，符合这个描述。", "河": "语义：河不可能只有一厘米长，与后半句“只有一厘米长”矛盾。", "公路": "语义：公路不会只有一厘米长，与“很小，只有一厘米长”的描述矛盾。", "鲸鱼": "体貌：鲸鱼体型巨大，不可能“很小，只有一厘米长”。"}, "sentence_index": 6, "correct_answer": "蠕虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈从冰箱里拿出一块蠕虫。", "explanation": "这里应该用〈条〉。“块”用于成块的东西，蠕虫不能用“块”。"}, {"text": "书桌上放着一张蠕虫。", "explanation": "这里应该用〈条〉。“张”用于纸、桌子等扁平的东西，蠕虫不能用。"}, {"text": "院子里有一座蠕虫。", "explanation": "这里应该用〈条〉。“座”用于山、桥等大型固定的东西，蠕虫不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在花园里挖到一张蠕虫。", "corrected_sentence": "我在花园里挖到一条蠕虫。", "error_description": "应为“一条蠕虫”。蠕虫细长，量词用“条”；“张”用于纸、桌子等扁平的东西，不能用于蠕虫。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土里有一本蠕虫在爬。", "corrected_sentence": "土里有一条蠕虫在爬。", "error_description": "错误形式「一本蠕虫」，正确形式「一条蠕虫」。「本」用于书册等，蠕虫细长，应用量词「条」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ec2025-f6a1-4b85-885b-02387ed6403f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
