INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西带到某人或某地，并交给对方。", "primary_collocate": null, "pronunciation": "sòng dào", "ipa": "soŋ˥˩ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我把信送到他家了。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员明天会送到你家。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭已经送到房间里了。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这本书送到老师办公室。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的包裹下午三点前能送到。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把花送到了妈妈手里。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我把药送到他家。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶每天早上都会送到门口。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件今天要送到公司。", "target_word": "送到", "complexity_tier": "T3", "furigana": "zhè fèn wénjiàn jīntiān yào sòng dào gōngsī", "sentence_source": "generated"}, {"text": "我想把礼物送到她的手上。", "target_word": "送到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送到了", "label": "体标"}, {"form": "送到过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把东西带到某人或某地并交给对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送到", "is_correct": true, "explanation": "送到表示把信送达他家，与句中“他家了”的结果一致。"}, {"text": "撕掉", "is_correct": false, "explanation": "搭配：“撕掉”不能接表示地点的“他家”，与“送”的方向不合。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是销毁，与把信送去的意思相反。"}, {"text": "带走", "is_correct": false, "explanation": "配价：“带走”后面不能直接接处所“他家”，应说“带到他家”。"}], "explanations": {"送到": "送到表示把信送达他家，与句中“他家了”的结果一致。", "撕掉": "搭配：“撕掉”不能接表示地点的“他家”，与“送”的方向不合。", "烧毁": "语义：烧毁是销毁，与把信送去的意思相反。", "带走": "配价：“带走”后面不能直接接处所“他家”，应说“带到他家”。"}, "sentence_index": 0, "correct_answer": "送到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于送到了录取通知书。", "explanation": "这里应该用〈拿到〉。送到是把东西送给别人，自己收到录取通知书要用“拿到”。"}, {"text": "我们下个月送到新家。", "explanation": "这里应该用〈搬到〉。送到是把东西送去，人自己迁居要用“搬到”。"}, {"text": "他的梦想送到了远方。", "explanation": "这里应该用〈寄托〉。送到是把具体的东西递给人或送去某处，梦想要用“寄托”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送到", "is_correct": true, "explanation": "送到表示把药送达他家，与“朋友生病了”的语境一致。"}, {"text": "吃掉", "is_correct": false, "explanation": "配价：“吃掉”后面不接表示处所的“到他家”，句子不成立。"}, {"text": "喝完", "is_correct": false, "explanation": "配价：“喝完”不接处所宾语，与“到他家”搭配不成立。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与“朋友生病了，我去送药”的意思相反。"}], "explanations": {"送到": "送到表示把药送达他家，与“朋友生病了”的语境一致。", "吃掉": "配价：“吃掉”后面不接表示处所的“到他家”，句子不成立。", "喝完": "配价：“喝完”不接处所宾语，与“到他家”搭配不成立。", "扔掉": "语义：扔掉是丢弃，与“朋友生病了，我去送药”的意思相反。"}, "sentence_index": 6, "correct_answer": "送到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车下午三点送到北京站。", "explanation": "这里应该用〈到达〉。送到需要有人或物把东西带去，火车是“到”，不是“送”。"}, {"text": "会议送到下周。", "explanation": "这里应该用〈延期〉。送到是把东西送达某处，会议不能“送到”某个时间。"}, {"text": "我在台上送到了观众的掌声。", "explanation": "这里应该用〈收到〉。送到是把东西送去给人，观众的掌声是接收的，要用“收到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天把信送到了他家。", "corrected_sentence": "我明天把信送到他家。", "error_description": "错误：“明天”指将来，句中多加了“了”。“了”表示已经完成，不能与将来的时间词连用，应去掉“了”，说“明天把信送到他家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "牛奶今天早上已经把送到门口了。", "corrected_sentence": "牛奶今天早上已经送到门口了。", "error_description": "错误：“把”字用错。“把”后面必须接宾语，这里“把”后直接接动词“送到”，应去掉“把”，说“牛奶今天早上已经送到门口了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
