INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水走的路。", "primary_collocate": null, "pronunciation": "qú dào", "ipa": "tɕʰy˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "农民在田边挖了一条渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条渠道把河水送到田里。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，渠道里的水很多。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，村里人开始清理渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渠道很窄，小船过不去。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在渠道旁边玩水。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渠道里的水慢慢流进了小河。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧渠道已经没有水了。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用石头修好了一条渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门前有一条小渠道。", "target_word": "渠道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "人工挖成的、供水流通的沟渠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c3c7e7-2c15-49bf-94ba-c23cadb6bf83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绳子", "is_correct": false, "explanation": "语义：“挖”的对象是土地或地下的东西，“绳子”不能被挖，“挖了一条绳子”不通。"}, {"text": "渠道", "is_correct": true, "explanation": "“渠道”指人工挖成的输水沟，“农民在田边挖了一条渠道”语义通顺，在这里正确。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“鱼”是动物，不能用“挖”，“挖了一条鱼”与田边挖沟的语境不合。"}, {"text": "裤子", "is_correct": false, "explanation": "搭配：“挖”不能带“裤子”作宾语，“挖了一条裤子”不通。"}], "explanations": {"绳子": "语义：“挖”的对象是土地或地下的东西，“绳子”不能被挖，“挖了一条绳子”不通。", "渠道": "“渠道”指人工挖成的输水沟，“农民在田边挖了一条渠道”语义通顺，在这里正确。", "鱼": "语义：“鱼”是动物，不能用“挖”，“挖了一条鱼”与田边挖沟的语境不合。", "裤子": "搭配：“挖”不能带“裤子”作宾语，“挖了一条裤子”不通。"}, "sentence_index": 0, "correct_answer": "渠道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门前有一只渠道。", "explanation": "这里应该用〈条〉。渠道细长，用“条”；“只”多用于动物或成对的东西。"}, {"text": "火车沿着一条渠道开进了城。", "explanation": "这里应该用〈铁路〉。渠道是输水的沟，火车行驶的路要说铁路，不能用渠道。"}, {"text": "火车穿过了一条长渠道。", "explanation": "这里应该用〈隧道〉。火车穿过的地下通道要说隧道；渠道是用来输水的沟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07534fce-0a8c-4ea5-a3a0-5bc569f97ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不装水，也不会有水流进小河，“桌子里的水慢慢流进了小河”不通。"}, {"text": "渠道", "is_correct": true, "explanation": "“渠道”是输水的沟，“渠道里的水慢慢流进了小河”语义通顺，在这里正确。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是放衣物的家具，不能让水流进小河，与语境不合。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”装书本，不装流动的水，“书包里的水”与语境不合。"}], "explanations": {"桌子": "语义：桌子不装水，也不会有水流进小河，“桌子里的水慢慢流进了小河”不通。", "渠道": "“渠道”是输水的沟，“渠道里的水慢慢流进了小河”语义通顺，在这里正确。", "衣柜": "语义：衣柜是放衣物的家具，不能让水流进小河，与语境不合。", "书包": "搭配：“书包”装书本，不装流动的水，“书包里的水”与语境不合。"}, "sentence_index": 6, "correct_answer": "渠道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门前有一张渠道。", "explanation": "这里应该用〈条〉。渠道细长，用“条”；“张”用于纸、桌子等平面的东西。"}, {"text": "飞机在一条渠道上慢慢滑行，准备起飞。", "explanation": "这里应该用〈跑道〉。渠道是输水的沟，飞机滑行、起飞的路面要说跑道。"}, {"text": "厂房门口有一条渠道，每天很多货车经过。", "explanation": "这里应该用〈马路〉。渠道是输水的沟，不能让货车通行；货车经过的路要说马路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07534fce-0a8c-4ea5-a3a0-5bc569f97ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把渠道把河水引到了菜园。", "corrected_sentence": "这条渠道把河水引到了菜园。", "error_description": "错误在“渠道”的量词：“渠道”用量词“条”，“把”是用于有柄物件的量词，不能用来修饰“渠道”，应说“这条渠道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07534fce-0a8c-4ea5-a3a0-5bc569f97ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们用石头修了一只渠道。", "corrected_sentence": "村民们用石头修了一条渠道。", "error_description": "量词错误：“渠道”用量词“条”，不用“只”。错误：一只渠道；正确：一条渠道。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07534fce-0a8c-4ea5-a3a0-5bc569f97ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
