INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27678, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合适，让人感觉刚刚好。", "primary_collocate": null, "pronunciation": "shì yí", "ipa": "ʂɻ̩⁵¹ i³⁵", "syllable_count": 2, "sentences": [{"text": "今天的温度很适宜，不冷也不热。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的湿度非常适宜。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的大小适宜，穿着很舒服。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音大小适宜，大家都听得清。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤的咸淡适宜，我很喜欢。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温适宜的时候，泡茶最好喝。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的天气适宜出去走走。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的光线适宜看书。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套的厚薄适宜，既保暖又不闷热。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的大小适宜一家三口住。", "target_word": "适宜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适宜", "label": "否定形式"}, {"form": "适宜于", "label": "复合"}], "register": "书面", "sense_fingerprint": "适宜：程度刚好，让人感觉舒服合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1179397-e906-4d1c-9821-be884b88404e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确答案。适宜（shì yí）指温度、大小等程度刚好，让人感觉舒服合适。"}, {"text": "示意", "is_correct": false, "explanation": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是用动作或表情表达意思。"}, {"text": "试衣", "is_correct": false, "explanation": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是穿上衣服看合不合身。"}, {"text": "四姨", "is_correct": false, "explanation": "sìyí（第四声）与 shìyí 声母不同（s 与 sh），意思是母亲的姐妹。"}, {"text": "制衣", "is_correct": false, "explanation": "zhìyī 声母与 shìyí 不同（zh 与 sh），第二个音节声调也变了，意思是制作衣服。"}], "explanations": {"适宜": "正确答案。适宜（shì yí）指温度、大小等程度刚好，让人感觉舒服合适。", "示意": "shìyì（第四声）与 shìyí 只差第二个音节的声调，意思是用动作或表情表达意思。", "试衣": "shìyī（第一声）与 shìyí 只差第二个音节的声调，意思是穿上衣服看合不合身。", "四姨": "sìyí（第四声）与 shìyí 声母不同（s 与 sh），意思是母亲的姐妹。", "制衣": "zhìyī 声母与 shìyí 不同（zh 与 sh），第二个音节声调也变了，意思是制作衣服。"}, "sentence_index": null, "correct_answer": "适宜"}, "level_3": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确：“适宜”作谓语，说温度刚好，与“不冷也不热”的语境一致。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”说温度很高，与“不冷也不热”矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度低，与“不冷也不热”矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "搭配：“完整”说事物齐全，不用来形容温度。"}], "explanations": {"适宜": "正确：“适宜”作谓语，说温度刚好，与“不冷也不热”的语境一致。", "烫": "语义：“烫”说温度很高，与“不冷也不热”矛盾。", "冷": "语义：“冷”说温度低，与“不冷也不热”矛盾。", "完整": "搭配：“完整”说事物齐全，不用来形容温度。"}, "sentence_index": 0, "correct_answer": "适宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很适宜，考了全班第一。", "explanation": "这里应该用〈优秀〉。适宜指条件、程度相合，说成绩好要用优秀。"}, {"text": "这个小孩很适宜，爱跑爱跳。", "explanation": "这里应该用〈活泼〉。说人性格开朗、好动要用活泼，适宜不用来形容人的性格。"}, {"text": "他和同事相处得很适宜，从不闹矛盾。", "explanation": "这里应该用〈融洽〉。说人与人相处和睦要用融洽，适宜不用来描写人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27678, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确答案。适宜（shì yí）指温度、大小等程度刚好，让人感觉舒服合适。"}, {"text": "视野", "is_correct": false, "explanation": "shìyě（第三声）与 shìyí 只差第二个音节的声调，意思是眼睛能看到的范围。"}, {"text": "石椅", "is_correct": false, "explanation": "shíyǐ 与 shìyí 两个音节的声调都不同，意思是石头做的椅子。"}, {"text": "十一", "is_correct": false, "explanation": "shíyī 与 shìyí 两个音节的声调都不同，意思是数字“十一”。"}, {"text": "司仪", "is_correct": false, "explanation": "sīyí（第一声）与 shìyí 声母不同（s 与 sh），声调也不同，意思是主持仪式的人。"}], "explanations": {"适宜": "正确答案。适宜（shì yí）指温度、大小等程度刚好，让人感觉舒服合适。", "视野": "shìyě（第三声）与 shìyí 只差第二个音节的声调，意思是眼睛能看到的范围。", "石椅": "shíyǐ 与 shìyí 两个音节的声调都不同，意思是石头做的椅子。", "十一": "shíyī 与 shìyí 两个音节的声调都不同，意思是数字“十一”。", "司仪": "sīyí（第一声）与 shìyí 声母不同（s 与 sh），声调也不同，意思是主持仪式的人。"}, "sentence_index": null, "correct_answer": "适宜"}, "level_3": {"options": [{"text": "适宜", "is_correct": true, "explanation": "正确：“适宜”作谓语，说天气合适外出，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”说天气冷，与“出去走走”的语境矛盾。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”说天气湿热，不适合出去走走，与句意相反。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容事物的体形，不用来形容天气。"}], "explanations": {"适宜": "正确：“适宜”作谓语，说天气合适外出，符合句意。", "寒冷": "语义：“寒冷”说天气冷，与“出去走走”的语境矛盾。", "闷热": "语义：“闷热”说天气湿热，不适合出去走走，与句意相反。", "高大": "搭配：“高大”形容事物的体形，不用来形容天气。"}, "sentence_index": 6, "correct_answer": "适宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打字打得很适宜，又快又准。", "explanation": "这里应该用〈熟练〉。说打字、操作等动作纯熟要用熟练，适宜指程度刚好、让人舒服，不用来形容技术水平。"}, {"text": "他很适宜，学东西很快。", "explanation": "这里应该用〈聪明〉。说人头脑灵活、学得快要用聪明，适宜不用来形容人的智力。"}, {"text": "他的脾气很适宜，同事都喜欢他。", "explanation": "这里应该用〈温和〉。适宜指条件、程度相合，形容人的脾气要用温和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的温度很适宜着，人待着很舒服。", "corrected_sentence": "这个房间的温度很适宜，人待着很舒服。", "error_description": "错误：“适宜”后面多加了“着”。正确：“这个房间的温度很适宜，人待着很舒服。”“着”表示动作或状态的持续，形容词“适宜”描述的是状态，后面不能加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子的光线很适宜了看书。", "corrected_sentence": "这间屋子的光线很适宜看书。", "error_description": "错误：“适宜”后面多加了“了”。正确：“这间屋子的光线很适宜看书。”“适宜”是形容词，描述光线的状态，后面不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
