INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文章、图片等整理好，让它们变得更好看。", "primary_collocate": null, "pronunciation": "biān jí", "ipa": "pjɛn˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我想把旅行照片编辑得更好看。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她编辑图片以后，照片好看多了。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在编辑公司网站上的文章。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片太暗，请再编辑一下。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢编辑文章，让页面更漂亮。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑过的图片颜色更亮。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在电脑上编辑班报，要排得好看。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用软件编辑了一张海报。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先编辑好文章，再放到网上。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会编辑照片，所以请我帮忙。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编辑了", "label": "体标"}, {"form": "编辑过", "label": "体标"}, {"form": "編輯", "label": "繁体"}, {"form": "编辑器", "label": "复合"}], "register": "中性", "sense_fingerprint": "整理文章、图片使其更美观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ee36597-8734-49e0-a69e-b3539cfe9228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：编辑照片可以使其更好看，“把照片编辑得更好看”符合该义项。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能把照片翻译。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做食物的动作，不能用来让照片更好看。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”用于布料、衣物，不说把照片缝得好看。"}], "explanations": {"编辑": "正确：编辑照片可以使其更好看，“把照片编辑得更好看”符合该义项。", "翻译": "搭配：“翻译”的对象是语言文字，不能把照片翻译。", "烘焙": "语义：烘焙是做食物的动作，不能用来让照片更好看。", "缝": "搭配：“缝”用于布料、衣物，不说把照片缝得好看。"}, "sentence_index": 0, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书桌编辑了一下，看起来干净多了。", "explanation": "这里应该用〈整理〉。书桌要收拾整理，编辑只用于文字、图片等内容。"}, {"text": "他花了一个小时编辑电脑。", "explanation": "这里应该用〈修理〉。电脑坏了要修理，编辑不能用于机器。"}, {"text": "他用相机编辑了一张照片。", "explanation": "这里应该用〈拍〉。用相机拍下照片要说拍，编辑是对已有图片的加工，不是拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：在电脑上编辑班报并排版，使版面好看，符合该义项。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：班报是纸面文字，在电脑上不能雕刻。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”的对象是有表面的物件，不说擦拭班报。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪动作，电脑上的班报无法煮。"}], "explanations": {"编辑": "正确：在电脑上编辑班报并排版，使版面好看，符合该义项。", "雕刻": "语义：班报是纸面文字，在电脑上不能雕刻。", "擦拭": "搭配：“擦拭”的对象是有表面的物件，不说擦拭班报。", "煮": "语义：煮是烹饪动作，电脑上的班报无法煮。"}, "sentence_index": 6, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天编辑桌子，很辛苦。", "explanation": "这里应该用〈擦〉。擦去桌面灰尘要说擦，编辑只用于文字、图片等内容。"}, {"text": "我每天晚上编辑碗，很累。", "explanation": "这里应该用〈洗〉。碗要洗，不能说编辑。"}, {"text": "爸爸每天编辑衣服，很辛苦。", "explanation": "这里应该用〈晾晒〉。衣服晾干要说晾晒，编辑不能用于衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把照片编辑很自然。", "corrected_sentence": "她把照片编辑得很自然。", "error_description": "补语错误：动词“编辑”后带补语“很自然”时要用“得”连接，应说“编辑得很自然”，不说“编辑很自然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们编辑了过班报。", "corrected_sentence": "我们编辑过班报。", "error_description": "体标错误：“编辑”后用“过”表示经历，不能再加“了”，应说“编辑过班报”，不说“编辑了过班报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "洗", "is_correct": false, "explanation": "与“记得”没有反义关系，“洗”是清洁的动作。"}, {"text": "唱", "is_correct": false, "explanation": "与“记得”没有反义关系，“唱”是发声的动作。"}, {"text": "住", "is_correct": false, "explanation": "与“记得”没有反义关系，“住”指居住或停留。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "洗": "与“记得”没有反义关系，“洗”是清洁的动作。", "唱": "与“记得”没有反义关系，“唱”是发声的动作。", "住": "与“记得”没有反义关系，“住”指居住或停留。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "放", "is_correct": false, "explanation": "与“记得”没有反义关系，“放”是放置的动作。"}, {"text": "用", "is_correct": false, "explanation": "与“记得”没有反义关系，“用”是使用的动作。"}, {"text": "走", "is_correct": false, "explanation": "与“记得”没有反义关系，“走”是移动的动作。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "放": "与“记得”没有反义关系，“放”是放置的动作。", "用": "与“记得”没有反义关系，“用”是使用的动作。", "走": "与“记得”没有反义关系，“走”是移动的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "把看到或听到的事情放在心里，不会忘掉。", "primary_collocate": null, "pronunciation": "jì de", "ipa": "tɕi˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "老师说的话，你要记得。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地址我只看过一次，现在还记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "zhè ge dì zhǐ wǒ zhǐ kàn guo yí cì, xiàn zài hái jì de.", "sentence_source": "generated"}, {"text": "老师讲的那个故事，我一直记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "lǎo shī jiǎng de nà ge gù shi, wǒ yì zhí jì de.", "sentence_source": "generated"}, {"text": "这个电话号码很重要，一定要记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人说的话，我记得很清楚。", "target_word": "记得", "complexity_tier": "T3", "furigana": "nà wèi lǎo rén shuō de huà, wǒ jì de hěn qīng chu.", "sentence_source": "generated"}, {"text": "妈妈的话，我一直记得。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上看到的路牌，他全都记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那本书的内容，他一直记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "nà běn shū de nèi róng, tā yì zhí jì de.", "sentence_source": "generated"}, {"text": "开会时听到的事，大家要记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图他只看过一遍，却都记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "dì tú tā zhǐ kàn guo yí biàn, què dōu jì de.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不记得", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "把见闻放在心里，牢记不忘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确答案：记得，表示把听到或看到的事放在心里，不会忘掉。"}, {"text": "急得", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。"}, {"text": "挤得", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。"}, {"text": "积德", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。"}, {"text": "细的", "is_correct": false, "explanation": "xì（第四声）与 jì（第四声）声母不同（x 与 j），意思是细小，「细的」是形容词性短语。"}], "explanations": {"记得": "正确答案：记得，表示把听到或看到的事放在心里，不会忘掉。", "急得": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。", "挤得": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。", "积德": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。", "细的": "xì（第四声）与 jì（第四声）声母不同（x 与 j），意思是细小，「细的」是形容词性短语。"}, "sentence_index": null, "correct_answer": "记得"}, "level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示把老师的话放在心里，与“你要”的劝勉语气相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物品，不能修理“话”。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“话”不能买。"}, {"text": "体验", "is_correct": false, "explanation": "配价：“体验”的宾语是经历或感受，不能把“老师说的话”作宾语。"}], "explanations": {"记得": "正确：“记得”表示把老师的话放在心里，与“你要”的劝勉语气相合。", "修理": "搭配：“修理”的对象是物品，不能修理“话”。", "购买": "搭配：“购买”的对象是商品，“话”不能买。", "体验": "配价：“体验”的宾语是经历或感受，不能把“老师说的话”作宾语。"}, "sentence_index": 0, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地图上记得一个红点，决定明天去那儿。", "explanation": "这里应该用〈标〉。在地图上做标记用“标”，记得表示回忆，不能指做标记。"}, {"text": "他在门上记得一张纸条。", "explanation": "这里应该用〈贴〉。把纸条贴在门上是固定动作，记得表示回忆，不能指把纸条贴上去。"}, {"text": "他在名单上记得我的名字。", "explanation": "这里应该用〈登记〉。记得表示留在记忆中，不能指把名字写到名单上；登记才是写下来备案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示路牌都留在记忆里，与“看到的”相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：路牌不能唱，“唱”与句中的路牌毫无关联。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球之类的物体，不能用于路牌。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多用于衣物、器皿，不用于路牌。"}], "explanations": {"记得": "正确：“记得”表示路牌都留在记忆里，与“看到的”相合。", "唱": "语义：路牌不能唱，“唱”与句中的路牌毫无关联。", "踢": "搭配：“踢”的对象是球之类的物体，不能用于路牌。", "洗": "搭配：“洗”多用于衣物、器皿，不用于路牌。"}, "sentence_index": 6, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在本子上记得黑板上的公式。", "explanation": "这里应该用〈抄〉。抄是把字写到本子上，记得表示留在记忆中，不能指把公式写下来。"}, {"text": "他一张一张地记得钱，数了半天。", "explanation": "这里应该用〈数〉。数是一张张点算，记得表示记忆中有，不能指点算钱。"}, {"text": "我用摄像机记得这场比赛，回去再看一遍。", "explanation": "这里应该用〈录〉。录指用设备保存影像，记得表示回忆，不能指用摄像机保存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我一直记得着。", "corrected_sentence": "这件事我一直记得。", "error_description": "错误形式：“记得着”；正确形式：“记得”。“记得”是状态动词，表示记在心里，不能再加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条路的每个路口我都记得得。", "corrected_sentence": "那条路的每个路口我都记得。", "error_description": "错误形式：“记得得”；正确形式：“记得”。“记得”后面不能再加一个“得”，多出的“得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
