INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种用数学方法描述事情可能怎么发生的工具。", "primary_collocate": null, "pronunciation": "gài lǜ mó xíng", "ipa": "kaɪ˥˩ ly˥˩ mwo˧˥ ɕiŋ˧˥", "syllable_count": 4, "sentences": [{"text": "概率模型是描述事情可能怎么发生的工具。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型可以算出下雨的可能。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用概率模型研究骰子的点数。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用概率模型猜明天的天气。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型太简单，算得不准。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们学着建立一个简单的概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "概率模型能告诉我们，事情有多大可能发生。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型用到的数学很简单。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店用概率模型预测每天卖多少。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "用数学方法描述事情可能性的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "概率模型用数学方法描述事情可能怎么发生，正是这句定义所说的工具。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛花的器皿，不能描述事情可能性的发生。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：棉被是寝具，与描述事情可能怎么发生的工具无关。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不是描述事情可能怎么发生的工具。"}], "explanations": {"概率模型": "概率模型用数学方法描述事情可能怎么发生，正是这句定义所说的工具。", "花瓶": "语义：花瓶是盛花的器皿，不能描述事情可能性的发生。", "棉被": "语义：棉被是寝具，与描述事情可能怎么发生的工具无关。", "蜂蜜": "语义：蜂蜜是食物，不是描述事情可能怎么发生的工具。"}, "sentence_index": 0, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支球队的概率模型很高。", "explanation": "这里应该用〈胜率〉。概率模型是描述可能性的工具，不能直接表示球队赢的比例。"}, {"text": "概率模型很烫，快喝吧。", "explanation": "这里应该用〈汤〉。“快喝”指喝汤或饮品；概率模型是数学工具，不能喝。"}, {"text": "这个概率模型很好吃。", "explanation": "这里应该用〈菜〉：“很好吃”形容食物；概率模型是数学工具，不能当作食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "学生可以学着建立一个简单的概率模型，搭配正确。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不能被“建立”成模型。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然地理实体，与“建立一个简单的”搭配不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用“建立”来修饰。"}], "explanations": {"概率模型": "学生可以学着建立一个简单的概率模型，搭配正确。", "白菜": "语义：白菜是蔬菜，不能被“建立”成模型。", "河流": "语义：河流是自然地理实体，与“建立一个简单的”搭配不通。", "身材": "体貌：“身材”指人的体形，不能用“建立”来修饰。"}, "sentence_index": 6, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨的概率模型很大。", "explanation": "这里应该用〈可能性〉：“很大”形容可能性；概率模型是数学方法，不能说“下雨的概率模型很大”。"}, {"text": "这首乐曲的概率模型很动听。", "explanation": "这里应该用〈旋律〉：“很动听”形容乐曲；概率模型是数学工具，不能用来形容乐曲。"}, {"text": "概率模型的颜色是红色的。", "explanation": "这里“概率模型”是数学方法，没有颜色；颜色用于〈图表〉这类有形的东西，不能用来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用一条概率模型预测天气。", "corrected_sentence": "我们用一个概率模型预测天气。", "error_description": "量词错误：模型应用“个”，“条”用于细长的东西。应为“用一个概率模型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他建概率模型得很快。", "corrected_sentence": "他建概率模型建得很快。", "error_description": "重复动词漏写：“建……得”结构中补语前需要重复动词“建”，应为“建概率模型建得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。"}, {"text": "赞美", "is_correct": false, "explanation": "“赞美”指称赞对方，与“误解”不构成反义关系。"}, {"text": "拒绝", "is_correct": false, "explanation": "“拒绝”指不接受，与“误解”没有反义关系。"}, {"text": "帮助", "is_correct": false, "explanation": "“帮助”指给予支持，与“误解”不构成反义关系。"}], "correct_answer": "理解", "explanations": {"理解": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。", "赞美": "“赞美”指称赞对方，与“误解”不构成反义关系。", "拒绝": "“拒绝”指不接受，与“误解”没有反义关系。", "帮助": "“帮助”指给予支持，与“误解”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。"}, {"text": "尊重", "is_correct": false, "explanation": "“尊重”指重视对方，与“误解”不构成反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "“同意”指赞成对方的看法，与“误解”没有反义关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”指热情接纳，与“误解”不构成反义关系。"}], "correct_answer": "理解", "explanations": {"理解": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。", "尊重": "“尊重”指重视对方，与“误解”不构成反义关系。", "同意": "“同意”指赞成对方的看法，与“误解”没有反义关系。", "欢迎": "“欢迎”指热情接纳，与“误解”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以为别人做错了事情，其实是自己想错了。", "primary_collocate": null, "pronunciation": "wù jiě", "ipa": "wu˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "对不起，我误解你了，以为是你拿的。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我误解了他，其实他是想帮我。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她误解了朋友的好意，生了半天气。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别误解我，我不是在批评你。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他误解了妈妈的话，哭了一晚上。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一直误解你，现在才知道你的想法。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常误解别人，所以朋友很少。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师误解了小明，以为他没写作业。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他误解过我，后来向我道歉了。", "target_word": "误解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你误解他了，他不是故意迟到的。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "误解了", "label": "体标"}, {"form": "误解过", "label": "体标"}, {"form": "誤解", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：把别人的做法或用意想错，错怪对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确答案。误解指把别人的做法或用意想错。"}, {"text": "无解", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。"}, {"text": "误写", "is_correct": false, "explanation": "xiě 与 jiě 声母不同（x 与 j），意思是写错。"}, {"text": "无界", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有界限。"}], "explanations": {"误解": "正确答案。误解指把别人的做法或用意想错。", "无解": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。", "误写": "xiě 与 jiě 声母不同（x 与 j），意思是写错。", "无界": "wú（第二声）与 wù（第四声）声调不同，意思是没有界限。"}, "sentence_index": null, "correct_answer": "误解"}, "level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。“我误解你了，以为是你拿的”中，“误解”表示把对方的行为想错。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对对方的感激，与“对不起”的道歉语境不符，且与“以为是你拿的”的怀疑相矛盾。"}, {"text": "谴责", "is_correct": false, "explanation": "语域：“谴责”措辞严厉，多用于书面或正式场合，与口语化的道歉语境不符。"}, {"text": "相信", "is_correct": false, "explanation": "语义：“相信”表示信任对方，与“以为是你拿的”所表达的怀疑相矛盾。"}], "explanations": {"误解": "正确。“我误解你了，以为是你拿的”中，“误解”表示把对方的行为想错。", "感谢": "语义：“感谢”是对对方的感激，与“对不起”的道歉语境不符，且与“以为是你拿的”的怀疑相矛盾。", "谴责": "语域：“谴责”措辞严厉，多用于书面或正式场合，与口语化的道歉语境不符。", "相信": "语义：“相信”表示信任对方，与“以为是你拿的”所表达的怀疑相矛盾。"}, "sentence_index": 0, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条广告误解了很多消费者，大家都不相信它。", "explanation": "这里应该用〈误导〉。误导指使人产生错误认识，主语可以是广告、言论；“误解”指当事人自己把别人的意思想错，不能用来说广告对消费者的影响。"}, {"text": "他误解了那扇门，一头撞了上去。", "explanation": "这里应该用〈误撞〉。误撞指不小心撞上，是动作上的失误；“误解”针对人的言行或事情真相，不能用于门。"}, {"text": "他误解了一块石头，把它搬进了屋里。", "explanation": "这里应该用〈误拿〉。误拿指拿错东西，是行为上的失误；“误解”针对人的言行或事情真相，不能用于具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。“常常误解别人，所以朋友很少”指把别人的做法想错，导致关系变差。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是积极行为，不会导致朋友很少，与后半句的因果关系不合。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”是正面态度，与“所以朋友很少”的因果关系相反。"}, {"text": "宠爱", "is_correct": false, "explanation": "搭配：“宠爱”多用于亲近者或晚辈，不说“宠爱别人”。"}], "explanations": {"误解": "正确。“常常误解别人，所以朋友很少”指把别人的做法想错，导致关系变差。", "帮助": "语义：“帮助”是积极行为，不会导致朋友很少，与后半句的因果关系不合。", "尊重": "语义：“尊重”是正面态度，与“所以朋友很少”的因果关系相反。", "宠爱": "搭配：“宠爱”多用于亲近者或晚辈，不说“宠爱别人”。"}, "sentence_index": 6, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他误解了桌上的杯子，一伸手把它碰倒了。", "explanation": "这里应该用〈误碰〉。误碰指不小心碰到，是动作；“误解”针对人的言行或事情真相，不能用于杯子。"}, {"text": "猎人误解了一只兔子，以为是野猪，一枪把它打伤了。", "explanation": "这里应该用〈误认〉。误认指把对象认错，是辨认上的错误；“误解”针对人的言行或事情真相，不能用于兔子。"}, {"text": "他误解了一只猫，把它赶出了家门。", "explanation": "这里应该用〈认错〉。认错指把人或物辨认错误；“误解”针对言语或事情的理解，不能用于猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把他的话误解了了，对不起。", "corrected_sentence": "我把他的话误解了，对不起。", "error_description": "体标重复：“误解”后的完成标记“了”已经出现，不能再加一个“了”。应写成“误解了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他误解得我的好意，这让我很难过。", "corrected_sentence": "他误解了我的好意，这让我很难过。", "error_description": "补语标记错误：“误解”后直接带宾语，完成义要用“了”，不能用“得”。“得”引出补语，“误解得我的好意”不成句。应写成“误解了我的好意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
