INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去一个地方，用手机或卡片记一下，表示自己来过了。", "primary_collocate": null, "pronunciation": "dǎ kǎ", "ipa": "ta²¹⁴ kʰa²¹⁴", "syllable_count": 2, "sentences": [{"text": "我们到了长城，先拍照打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去网红咖啡店打卡，还发了朋友圈。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想去新开的书店打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次去新的城市，都会用手机打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店太有名了，很多游客都来打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地图上打卡了三个地方。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友推荐的餐厅，我下周一定要去打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢去博物馆打卡，再发照片给朋友看。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里有一张卡，小朋友每到一个地方就打卡。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来这座山的人，都想在山顶打卡拍照。", "target_word": "打卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了卡", "label": "体标"}, {"form": "打过卡", "label": "体标"}, {"form": "打卡机", "label": "复合"}], "register": "口语", "sense_fingerprint": "打卡：去某地并用手机或卡片留下到此一游的记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1855a062-bf45-40b1-b6fc-d75bbeb6ed1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打卡", "is_correct": true, "explanation": "正确。“先拍照打卡”指在景点用手机记录到此一游，与句中的长城游览相符。"}, {"text": "点名", "is_correct": false, "explanation": "语义：“点名”是清点人员，与在长城拍照的情境无关。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指报账，与在景点拍照的情境不合。"}, {"text": "签收", "is_correct": false, "explanation": "搭配：“签收”需接物品或文件作宾语，不能用于在景点拍照。"}], "explanations": {"打卡": "正确。“先拍照打卡”指在景点用手机记录到此一游，与句中的长城游览相符。", "点名": "语义：“点名”是清点人员，与在长城拍照的情境无关。", "报销": "语义：“报销”指报账，与在景点拍照的情境不合。", "签收": "搭配：“签收”需接物品或文件作宾语，不能用于在景点拍照。"}, "sentence_index": 0, "correct_answer": "打卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向朋友打卡自己的考试成绩。", "explanation": "这里应该用〈告知〉。打卡的宾语是地点或活动，不能是成绩这类信息。"}, {"text": "他打卡了一条新闻，又转发给同事。", "explanation": "这里应该用〈浏览〉。打卡表示到某地留下记录，不能用于新闻这类内容。"}, {"text": "他给妈妈打卡了一首歌。", "explanation": "这里应该用〈唱〉。打卡的宾语是地点，不能是歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打卡", "is_correct": true, "explanation": "正确。“朋友推荐的餐厅，我下周一定要去打卡”指去餐厅留下到此一游的记录，与句意相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”指去教室学习，与推荐的餐厅无关。"}, {"text": "体检", "is_correct": false, "explanation": "语义：“体检”指身体检查，与去餐厅的情境不符。"}, {"text": "签字", "is_correct": false, "explanation": "搭配：“签字”需要文件或合同作宾语，不说“去签字”去餐厅。"}], "explanations": {"打卡": "正确。“朋友推荐的餐厅，我下周一定要去打卡”指去餐厅留下到此一游的记录，与句意相符。", "上课": "语义：“上课”指去教室学习，与推荐的餐厅无关。", "体检": "语义：“体检”指身体检查，与去餐厅的情境不符。", "签字": "搭配：“签字”需要文件或合同作宾语，不说“去签字”去餐厅。"}, "sentence_index": 6, "correct_answer": "打卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在餐厅里打卡了一位服务员。", "explanation": "这里应该用〈招呼〉。打卡的宾语是地点，不能是人。"}, {"text": "我们在车站打卡朋友。", "explanation": "这里应该用〈等候〉。打卡用于到达地点留下记录，不能用于人。"}, {"text": "他们去打卡老朋友。", "explanation": "这里应该用〈探访〉。打卡只表示到达某地留下记录，不能用于拜访人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去过很多景点，还打了卡过。", "corrected_sentence": "我们去过很多景点，还打过卡。", "error_description": "错误：表示经历要用“打过卡”，不能写成“打了卡过”。正确说法：“我们去过很多景点，还打过卡。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我想和妈妈去那家花店打了卡。", "corrected_sentence": "周末我想和妈妈去那家花店打卡。", "error_description": "错误：“想”表示将来的打算，后面不能接完成体“了”。正确说法：“周末我想和妈妈去那家花店打卡。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
