INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "就是不同意，心里觉得不喜欢。", "primary_collocate": null, "pronunciation": "dǐ chù", "ipa": "ti²¹⁴ tʂʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "他很抵触吃药，每次都不想吃。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抵触去上学，早上不肯起床。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这件事有点抵触，不想参加。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叫他学钢琴，他心里很抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多孩子抵触写作业，觉得没意思。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抵触搬家，因为舍不得朋友。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话太凶，学生都很抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直抵触别人的建议，觉得自己是对的。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不抵触学新东西，只是需要一点时间。", "target_word": "抵触", "complexity_tier": "T3", "furigana": "wǒ bù dǐ chù xué xīn dōng xi, zhǐ shì xū yào yì diǎn shí jiān.", "sentence_source": "generated"}, {"text": "听到要加班，大家心里都有些抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵触了", "label": "体标"}, {"form": "抵触情绪", "label": "复合"}], "register": "中性", "sense_fingerprint": "抵触：心里不喜欢、不愿意接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1855a062-bf45-40b1-b6fc-d75bbeb6ed1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触（dǐchù）：心里不喜欢，不愿意接受。"}, {"text": "低处", "is_correct": false, "explanation": "低处（dīchǔ）与抵触的两个音节声调都不同：低为第一声，处为第三声，意思是低的地方。"}, {"text": "地处", "is_correct": false, "explanation": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。"}, {"text": "递出", "is_correct": false, "explanation": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。"}, {"text": "抵住", "is_correct": false, "explanation": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}], "explanations": {"抵触": "抵触（dǐchù）：心里不喜欢，不愿意接受。", "低处": "低处（dīchǔ）与抵触的两个音节声调都不同：低为第一声，处为第三声，意思是低的地方。", "地处": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。", "递出": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。", "抵住": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}, "sentence_index": null, "correct_answer": "抵触"}, "level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：心里反感、不愿接受，与“每次都不想吃”相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“很喜欢吃药”与后半句“每次都不想吃”的意思相矛盾。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“很习惯吃药”与“每次都不想吃”相矛盾，不符合语境。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说“享受吃药”。"}], "explanations": {"抵触": "抵触：心里反感、不愿接受，与“每次都不想吃”相符。", "喜欢": "语义：“很喜欢吃药”与后半句“每次都不想吃”的意思相矛盾。", "习惯": "语义：“很习惯吃药”与“每次都不想吃”相矛盾，不符合语境。", "享受": "搭配：“享受”多搭配生活、待遇，不说“享受吃药”。"}, "sentence_index": 0, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车队终于抵触了终点站。", "explanation": "这里应该用〈抵达〉。抵达表示到达某地，抵触表示矛盾或抗拒，不能用于地点。"}, {"text": "他用汽车抵触了这笔借款。", "explanation": "这里应该用〈抵押〉。抵押是以财产作担保，抵触没有这个意思。"}, {"text": "他用手抵触了迎面的风雪。", "explanation": "这里应该用〈抵挡〉。抵挡是用身体挡住东西，抵触表示矛盾或抗拒，不表示挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：心里不愿接受、反感，与“学生都很”的语境相符。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“老师说话太凶”之后，“学生都很感激”与语境相矛盾。"}, {"text": "信任", "is_correct": false, "explanation": "语义：说话太凶的老师不会让学生“信任”，与语境相矛盾。"}, {"text": "敬佩", "is_correct": false, "explanation": "配价：“敬佩”需要带宾语，不能单独说“很敬佩”。"}], "explanations": {"抵触": "抵触：心里不愿接受、反感，与“学生都很”的语境相符。", "感激": "语义：“老师说话太凶”之后，“学生都很感激”与语境相矛盾。", "信任": "语义：说话太凶的老师不会让学生“信任”，与语境相矛盾。", "敬佩": "配价：“敬佩”需要带宾语，不能单独说“很敬佩”。"}, "sentence_index": 6, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要抵触洪水的侵袭。", "explanation": "这里应该用〈抵御〉。抵御指挡住外来的侵袭，抵触只表示矛盾或抗拒，不能用于抵挡洪水。"}, {"text": "他想用钱抵触这次损失。", "explanation": "这里应该用〈抵偿〉。抵偿指用钱或物补偿损失，抵触没有补偿的意思。"}, {"text": "工资可以抵触税款。", "explanation": "这里应该用〈抵扣〉。抵扣指互相冲抵后扣除，抵触没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把抵触去医院，一听到就皱眉。", "corrected_sentence": "他很抵触去医院，一听到就皱眉。", "error_description": "错误：“把”字句要求宾语被处置，“把抵触”不成立，应改为直接作谓语。正确说法：“他很抵触去医院，一听到就皱眉。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候抵触过了打针，现在已经不怕了。", "corrected_sentence": "我小时候抵触过打针，现在已经不怕了。", "error_description": "错误：“过”与“了”不能同时用在同一动词后表示经历。正确说法：“我小时候抵触过打针，现在已经不怕了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05846cff-3c11-453f-ad46-1f4aba5d454b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食的动作，与“无”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“无”没有反义关系。"}, {"text": "说", "is_correct": false, "explanation": "说是言语动作，与“无”没有反义关系。"}], "correct_answer": "有", "explanations": {"有": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。", "吃": "吃是进食的动作，与“无”没有反义关系。", "看": "看是视觉动作，与“无”没有反义关系。", "说": "说是言语动作，与“无”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑是移动的动作，与“无”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声的动作，与“无”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写的动作，与“无”没有反义关系。"}], "correct_answer": "有", "explanations": {"有": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。", "跑": "跑是移动的动作，与“无”没有反义关系。", "唱": "唱是发声的动作，与“无”没有反义关系。", "写": "写是书写的动作，与“无”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有", "primary_collocate": null, "pronunciation": "wú", "ipa": "u˧˥", "syllable_count": 1, "sentences": [{"text": "这个房间无窗，白天也要开灯。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一人在家，屋里无其他人。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边无车，行人可以放心过街。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校无游泳池，学生去外面游泳。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇无商店，买东西很不方便。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家无电视，晚上全家人一起看书。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子无空调，夏天特别热。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她包里无手机，所以没法给你打电话。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个湖无鱼，湖水清得能看到底。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天无风，树叶一动也不动。", "target_word": "无", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "無", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "无：没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 他家 (Zipf 3.99), 全家人 (Zipf 3.47), 看书 (Zipf 3.84)']::text[], '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有。"}, {"text": "武", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。"}, {"text": "屋", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。"}, {"text": "乌", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。"}, {"text": "务", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}], "explanations": {"无": "无 wú，意思是没有。", "武": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。", "屋": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。", "乌": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。", "务": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无窗”表示没有窗户，与“白天也要开灯”构成因果，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修窗”指修理窗户，与房间没有窗户的意思不合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦窗”指清洁窗户，“这个房间擦窗”与句意不符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔窗”指把窗户摔坏，与句子的意思无关。"}], "explanations": {"无": "无：“无窗”表示没有窗户，与“白天也要开灯”构成因果，句意通顺。", "修": "语义：“修窗”指修理窗户，与房间没有窗户的意思不合。", "擦": "搭配：“擦窗”指清洁窗户，“这个房间擦窗”与句意不符。", "摔": "语义：“摔窗”指把窗户摔坏，与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "无论天气怎么样，我们都去操场跑步。", "explanation": "这里的“无论”是连词，“无”并不表示“没有”，应用〈不管〉。"}, {"text": "他无非是想引起大家的注意。", "explanation": "这里的“无非”是副词，表示“只不过”，“无”并不表示“没有”，应用〈只是〉。"}, {"text": "我们去无锡参观，那里的园林很有名。", "explanation": "这里的“无”属于地名“无锡”的一部分，与“没有”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。"}, {"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。"}, {"text": "雾", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。"}, {"text": "悟", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。"}], "explanations": {"无": "无 wú，意思是没有。", "五": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。", "午": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。", "舞": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。", "雾": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。", "悟": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无空调”表示没有空调，与“夏天特别热”因果相连，句意通顺。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装空调”指安装空调，与“夏天特别热”的因果不通，句意矛盾。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”一般带车、门等物体，不能与“空调”搭配作宾语。"}, {"text": "掉", "is_correct": false, "explanation": "配价：“掉”一般不带“空调”这样的宾语，不能说“掉空调”。"}], "explanations": {"无": "无：“无空调”表示没有空调，与“夏天特别热”因果相连，句意通顺。", "装": "语义：“装空调”指安装空调，与“夏天特别热”的因果不通，句意矛盾。", "推": "搭配：“推”一般带车、门等物体，不能与“空调”搭配作宾语。", "掉": "配价：“掉”一般不带“空调”这样的宾语，不能说“掉空调”。"}, "sentence_index": 6, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论大人还是小孩，都喜欢这个游戏。", "explanation": "这里的“无论”是连词，“无”并不表示“没有”，应用〈不论〉。"}, {"text": "这件事无非是个误会，大家别太在意。", "explanation": "这里的“无非”是副词，表示“只不过”，“无”并不表示“没有”，应用〈只是〉。"}, {"text": "我的表哥住在无锡，他常来看我。", "explanation": "这里的“无”属于地名“无锡”的一部分，与“没有”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个路口无过红绿灯，司机要特别小心。", "corrected_sentence": "这个路口无红绿灯，司机要特别小心。", "error_description": "“无”后面不能加“过”。表示没有某物时直接说“无红绿灯”，不用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛无了汽车，人们都骑自行车。", "corrected_sentence": "这座岛无汽车，人们都骑自行车。", "error_description": "“无”后面不能加“了”。表示没有某物时直接说“无汽车”，不用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "正确：“合成”与“分解”构成反义，表示把若干部分组合成一个整体。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”表示使某种状态不变，与“分解”的意义没有反义关系。"}, {"text": "进行", "is_correct": false, "explanation": "语义：“进行”表示持续做某事，与“分解”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”表示仔细看，与“分解”没有反义关系。"}], "correct_answer": "合成", "explanations": {"合成": "正确：“合成”与“分解”构成反义，表示把若干部分组合成一个整体。", "保持": "语义：“保持”表示使某种状态不变，与“分解”的意义没有反义关系。", "进行": "语义：“进行”表示持续做某事，与“分解”没有反义关系。", "观察": "语义：“观察”表示仔细看，与“分解”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
