INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西分成几个部分。", "primary_collocate": null, "pronunciation": "fēn jiě", "ipa": "fən˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们可以把这篇文章分解成四个段落。", "target_word": "分解", "complexity_tier": "T3", "furigana": "wǒ men kě yǐ bǎ zhè piān wén zhāng fēn jiě chéng sì gè duàn luò", "sentence_source": "generated"}, {"text": "我们把大任务分解成几个小任务。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划可以分解成几个步骤。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge jì huà kě yǐ fēn jiě chéng jǐ gè bù zhòu", "sentence_source": "generated"}, {"text": "老师把这个句子分解成三个部分。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目可以分解成三个阶段。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge xiàng mù kě yǐ fēn jiě chéng sān gè jiē duàn", "sentence_source": "generated"}, {"text": "这个问题太大，要先分解一下。", "target_word": "分解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把旧机器分解了，再一件一件检查。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把复杂的动作分解给我们看。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以分解成几个部分。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè tái jī qì kě yǐ fēn jiě chéng jǐ gè bù fen", "sentence_source": "generated"}, {"text": "这个汉字可以分解成两个部分。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge hàn zì kě yǐ fēn jiě chéng liǎng gè bù fen", "sentence_source": "generated"}], "morphological_forms": [{"form": "分解了", "label": "体标"}, {"form": "分解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：把整体拆分成几个部分，常用“把A分解成B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分解", "is_correct": true, "explanation": "正确答案：fēn jiě，表示把整体分成几个部分。"}, {"text": "分界", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是划分界线。"}, {"text": "分接", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，意思是分开或接通，多用于分接口等。"}, {"text": "分家", "is_correct": false, "explanation": "分家 fēn jiā 与 分解 fēn jiě 第二个音节声调不同（jiā 与 jiě），意思是家人分开、各过各的。"}], "explanations": {"分解": "正确答案：fēn jiě，表示把整体分成几个部分。", "分界": "jiě（第三声）与 jiè（第四声）声调不同，意思是划分界线。", "分接": "jiě（第三声）与 jiē（第一声）声调不同，意思是分开或接通，多用于分接口等。", "分家": "分家 fēn jiā 与 分解 fēn jiě 第二个音节声调不同（jiā 与 jiě），意思是家人分开、各过各的。"}, "sentence_index": null, "correct_answer": "分解"}, "level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "正确：“分解”表示把整篇文章拆成若干部分，与“分成四个段落”相合。"}, {"text": "分配", "is_correct": false, "explanation": "搭配：“分配”用于任务、资源等，不能用来指把文章划分为段落。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，“翻译成四个段落”说不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，不能用来指划分文章的段落。"}], "explanations": {"分解": "正确：“分解”表示把整篇文章拆成若干部分，与“分成四个段落”相合。", "分配": "搭配：“分配”用于任务、资源等，不能用来指把文章划分为段落。", "翻译": "语义：“翻译”指转换语言，“翻译成四个段落”说不通。", "烧": "语义：“烧”指燃烧，不能用来指划分文章的段落。"}, "sentence_index": 0, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和女朋友分解了。", "explanation": "这里应该用〈分手〉。“分解”指把事物拆成部分，不能用于人与人关系的结束。"}, {"text": "我们分解了三年没见面。", "explanation": "这里应该用〈分开〉。“分解”强调把整体拆成部分，不能用于人与人长期分离。"}, {"text": "我们分解了快乐。", "explanation": "这里应该用〈分享〉。“分解”指把具体的整体拆开，不能用于抽象的快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱地看，与“一件一件检查”的拆解工作不符。"}, {"text": "信任", "is_correct": false, "explanation": "搭配：“信任”的对象通常是人，不能用于“旧机器”。"}, {"text": "分解", "is_correct": true, "explanation": "正确：“分解”表示把机器拆成部件，与“一件一件检查”相合。"}, {"text": "迷恋", "is_correct": false, "explanation": "语义：“迷恋”指深深喜爱，与“拆开检查旧机器”的动作不符。"}], "explanations": {"欣赏": "语义：“欣赏”指喜爱地看，与“一件一件检查”的拆解工作不符。", "信任": "搭配：“信任”的对象通常是人，不能用于“旧机器”。", "分解": "正确：“分解”表示把机器拆成部件，与“一件一件检查”相合。", "迷恋": "语义：“迷恋”指深深喜爱，与“拆开检查旧机器”的动作不符。"}, "sentence_index": 6, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爱情很快就分解了。", "explanation": "这里应该用〈破裂〉。“分解”指把具体事物拆成部分，不能用于感情关系的破裂。"}, {"text": "这场比赛把我分解得很累。", "explanation": "这个词不这么用。“分解”指把事物拆成部分，不能表示使人感到疲惫。"}, {"text": "我们分解了一个晚上的海浪。", "explanation": "这里应该用〈看〉。海浪是流动的整体，不能“分解”；“分解”的宾语应是可以拆分成部分的具体事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们可以把计划分解几个步骤。", "corrected_sentence": "我们可以把计划分解成几个步骤。", "error_description": "错误：“分解”要接“成”引出分成的结果，应说“分解成几个步骤”，不能省略“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把机器分解了成几个部分。", "corrected_sentence": "工程师把机器分解成几个部分。", "error_description": "错误：“分解”后接“成”引出结果，两者之间不能加“了”。应说“工程师把机器分解成几个部分。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
