INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "责任就是你应该做的事情，或者做错了事情要承担的后果。", "primary_collocate": null, "pronunciation": "zé rèn", "ipa": "tsɤ³⁵ ʐən⁵¹", "syllable_count": 2, "sentences": [{"text": "照顾孩子是父母的责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事我也有责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次错误的责任在我。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师有责任帮助学生。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "保护环境是每个人的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想承担这个责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司应该负起自己的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为班长，他的责任很大。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这不是你一个人的责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子长大了，也要有自己的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "责任心", "label": "复合"}, {"form": "责任感", "label": "复合"}], "register": "中性", "sense_fingerprint": "应尽的义务；出错后要承担的后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e621cd-3813-46e8-abfa-9d13f45d7637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：食物是可以吃的东西，照顾孩子不是父母的食物。"}, {"text": "面貌", "is_correct": false, "explanation": "体貌：“面貌”指外表形象，照顾孩子不属于父母的外表。"}, {"text": "责任", "is_correct": true, "explanation": "正确：照顾孩子是父母应尽的义务，与句意相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是用来演奏的器具，与照顾孩子无关。"}], "explanations": {"食物": "语义：食物是可以吃的东西，照顾孩子不是父母的食物。", "面貌": "体貌：“面貌”指外表形象，照顾孩子不属于父母的外表。", "责任": "正确：照顾孩子是父母应尽的义务，与句意相符。", "乐器": "语义：“乐器”是用来演奏的器具，与照顾孩子无关。"}, "sentence_index": 0, "correct_answer": "责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犯了一个责任。", "explanation": "这里应该用〈过失〉。犯错要说犯过失或错误，“责任”是应尽的义务，不能说犯责任。"}, {"text": "学校举办了一个责任。", "explanation": "这里应该用〈活动〉。举办的是活动、比赛，“责任”不能被举办。"}, {"text": "我们参加了一次责任。", "explanation": "这里应该用〈考试〉。参加的是考试、比赛等活动，“责任”不能被参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "配价：“负起”要求的宾语是责任、义务一类，不能是“名字”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不与“负起”搭配，说“负起自己的颜色”不通。"}, {"text": "责任", "is_correct": true, "explanation": "责任：“负起责任”是固定搭配，表示承担应尽的义务。"}, {"text": "利益", "is_correct": false, "explanation": "搭配：“利益”一般说维护或争取，不与“负起”搭配。"}], "explanations": {"名字": "配价：“负起”要求的宾语是责任、义务一类，不能是“名字”。", "颜色": "搭配：“颜色”不与“负起”搭配，说“负起自己的颜色”不通。", "责任": "责任：“负起责任”是固定搭配，表示承担应尽的义务。", "利益": "搭配：“利益”一般说维护或争取，不与“负起”搭配。"}, "sentence_index": 6, "correct_answer": "责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他洗了一个责任。", "explanation": "这里应该用〈衣服〉。洗的是衣物，“责任”是抽象的义务，不能被洗。"}, {"text": "他发表了一个责任。", "explanation": "这里应该用〈文章〉。发表的是文章、言论，“责任”不能被发表。"}, {"text": "他修理了一个责任。", "explanation": "这里应该用〈自行车〉。修理的是器物，“责任”是抽象的义务，不能被修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些责任们都要由他负责。", "corrected_sentence": "这些责任都要由他负责。", "error_description": "错误形式：“责任们”；正确形式：“责任”。“们”只用于指人，不能加在抽象名词“责任”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他接受了一只新的责任。", "corrected_sentence": "他接受了一份新的责任。", "error_description": "错误形式：“一只责任”；正确形式：“一份责任”。“只”是用于动物的量词，“责任”要用“份”或“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起做一件事，每人做一部分。", "primary_collocate": null, "pronunciation": "fēn dān", "ipa": "fən˥ tan˥", "syllable_count": 2, "sentences": [{"text": "打扫教室时，每个同学分担一部分。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个项目由三个人分担。", "target_word": "分担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们分担了做饭和洗碗的工作。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家的活儿，大家一起分担吧。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次演出的准备工作，我们平均分担。", "target_word": "分担", "complexity_tier": "T3", "furigana": "zhè cì yǎnchū de zhǔnbèi gōngzuò, wǒmen píngjūn fēndān", "sentence_source": "generated"}, {"text": "老师让每个小组分担一项任务。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们分担着照顾老人的工作。", "target_word": "分担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的家务，我和姐姐一起分担。", "target_word": "分担", "complexity_tier": "T3", "furigana": "zhōumò de jiāwù, wǒ hé jiějie yìqǐ fēndān", "sentence_source": "generated"}, {"text": "这么多活儿，一个人做不完，要大家分担。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，队员们分担了不同的准备工作。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分担了", "label": "体标"}, {"form": "分担过", "label": "体标"}, {"form": "分担着", "label": "体标"}, {"form": "分擔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事由多人分工，每人负责其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：每个同学分工负责其中一部分，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语一般是食物，不能说“吃一部分”的分工。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与打扫教室的分工无关。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”不能表示分担工作，与语境不合。"}], "explanations": {"分担": "正确：每个同学分工负责其中一部分，符合语境。", "吃": "搭配：“吃”的宾语一般是食物，不能说“吃一部分”的分工。", "唱": "语义：“唱”与打扫教室的分工无关。", "跳": "语义：“跳”不能表示分担工作，与语境不合。"}, "sentence_index": 0, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们分担了这场比赛。", "explanation": "这里应该用〈参加〉。分担指多人分工做一件事，参加比赛不能说分担。"}, {"text": "大家一起分担这块蛋糕。", "explanation": "这里应该用〈分享〉。分担用于工作、责任、费用，分享食物要用〈分享〉。"}, {"text": "我们分担了那座公园。", "explanation": "这里应该用〈游览〉。分担的宾语是工作或费用，不能是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：“分担着照顾老人的工作”指多人分工，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与分工承担的语境相反，不符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不能用来描述承担工作，与句意不合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与承担工作无关，“哭着照顾老人的工作”只说边哭边做，不表示分工承担。"}], "explanations": {"分担": "正确：“分担着照顾老人的工作”指多人分工，符合语境。", "拒绝": "语义：“拒绝”与分工承担的语境相反，不符合句意。", "忘记": "语义：“忘记”不能用来描述承担工作，与句意不合。", "哭": "语义：“哭”与承担工作无关，“哭着照顾老人的工作”只说边哭边做，不表示分工承担。"}, "sentence_index": 6, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们分担了那座博物馆。", "explanation": "这里应该用〈参观〉。分担的宾语是工作或责任，不能指参观的地点。"}, {"text": "我们分担了这本书。", "explanation": "这里应该用〈阅读〉。分担不能用于书籍，读书要用〈阅读〉。"}, {"text": "队员们分担了那位教练。", "explanation": "这里应该用〈陪伴〉。分担的宾语不能是人，陪伴教练要用〈陪伴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分担了打扫房间的一只工作。", "corrected_sentence": "我们分担了打扫房间的一项工作。", "error_description": "错误在于量词“只”。“只”多用于动物或成对器物中的一个，不能修饰“工作”；“工作”可用“项”或“件”，应说“一项工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们平分分担了这些任务。", "corrected_sentence": "他们平均分担了这些任务。", "error_description": "错误形式“平分分担”，正确形式“平均分担”。“平分”与“分担”意思重复，表示按份额均等承担应用“平均”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
