INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "玩电子游戏或某种游戏的人。", "primary_collocate": null, "pronunciation": "wán jiā", "ipa": "wan˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这个游戏有一千万玩家。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新玩家可以先玩简单的关卡。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位玩家的游戏水平很高。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩家们都在等新游戏上线。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩家每天玩游戏五个小时。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏公司想听听玩家的意见。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩家在游戏里可以选自己的角色。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，玩家都很紧张。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多玩家喜欢和朋友一起玩。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一位玩家赢了这次比赛。", "target_word": "玩家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "玩家们", "label": "复数"}, {"form": "新玩家", "label": "复合"}], "register": "口语", "sense_fingerprint": "玩游戏的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b67ea2c-4f99-4305-8a7b-096353e3f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玩家", "is_correct": true, "explanation": "玩家：玩电子游戏或某种游戏的人。"}, {"text": "万家", "is_correct": false, "explanation": "wàn jiā（第四声）与 wán jiā（第二声）声调不同，意思是成千上万的家庭。"}, {"text": "王家", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（ng 与 n），意思是姓王的家族。"}, {"text": "韩家", "is_correct": false, "explanation": "hán 与 wán 声母不同，意思是姓韩的家族。"}, {"text": "碗架", "is_correct": false, "explanation": "wǎn jià 与 wán jiā 声调都不同，意思是放碗的架子。"}], "explanations": {"玩家": "玩家：玩电子游戏或某种游戏的人。", "万家": "wàn jiā（第四声）与 wán jiā（第二声）声调不同，意思是成千上万的家庭。", "王家": "wáng 与 wán 韵母不同（ng 与 n），意思是姓王的家族。", "韩家": "hán 与 wán 声母不同，意思是姓韩的家族。", "碗架": "wǎn jià 与 wán jiā 声调都不同，意思是放碗的架子。"}, "sentence_index": null, "correct_answer": "玩家"}, "level_3": {"options": [{"text": "玩家", "is_correct": true, "explanation": "玩家：玩游戏的人，与“游戏”和“一千万”的语境相符。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家写作品，游戏里没有作家，这句话说不通。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，与游戏无关。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是驾驶车辆的人，与游戏无关。"}], "explanations": {"玩家": "玩家：玩游戏的人，与“游戏”和“一千万”的语境相符。", "作家": "语义：作家写作品，游戏里没有作家，这句话说不通。", "乘客": "语义：乘客是乘车的人，与游戏无关。", "司机": "语义：司机是驾驶车辆的人，与游戏无关。"}, "sentence_index": 0, "correct_answer": "玩家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛中玩家判罚了他的犯规。", "explanation": "这里应该用〈裁判〉。玩家指玩游戏的人，判罚犯规的人要用裁判。"}, {"text": "我们班的玩家都去体育馆看比赛了，坐在看台上。", "explanation": "这里应该用〈观众〉。玩家指亲自玩游戏的人，看比赛的人要用观众。"}, {"text": "这位玩家写了三本小说。", "explanation": "这里应该用〈作家〉。玩家指玩游戏的人，写小说的人要用作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩家", "is_correct": true, "explanation": "玩家：玩游戏的人，可以在游戏里选择角色。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不会在游戏里选角色，这句话说不通。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：“观众”指看表演或比赛的人，不能在游戏里选角色。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判负责判定比赛，不参与选择角色。"}], "explanations": {"玩家": "玩家：玩游戏的人，可以在游戏里选择角色。", "病人": "语义：病人不会在游戏里选角色，这句话说不通。", "观众": "搭配：“观众”指看表演或比赛的人，不能在游戏里选角色。", "裁判": "语义：裁判负责判定比赛，不参与选择角色。"}, "sentence_index": 6, "correct_answer": "玩家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位玩家带我们参观了博物馆。", "explanation": "这里应该用〈导游〉。玩家指玩游戏的人，带领参观的人要用导游。"}, {"text": "这位玩家是我的妈妈。", "explanation": "这里应该用〈妈妈〉。玩家指玩游戏的人，说家里的母亲要用妈妈。"}, {"text": "这位玩家讲课很清楚。", "explanation": "这里应该用〈老师〉。玩家指玩游戏的人，在课堂上讲课的人要用老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只很厉害的玩家。", "corrected_sentence": "他是一位很厉害的玩家。", "error_description": "“玩家”指人，量词应用“位”，“只”多用于动物和物品，此处用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想在网上认识一个新玩家们。", "corrected_sentence": "我想在网上认识一个新玩家。", "error_description": "“玩家”后加“们”表示复数，但“一个”已表示单数，二者不能同用，应说“一个新玩家”，删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
