INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶意", "is_correct": true, "explanation": "恶意：与“善意”相对，指怀有不好的用意。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸：定期出版的印刷品，与“善意”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞：挡雨用的器具，与“善意”没有反义关系。"}, {"text": "镜子", "is_correct": false, "explanation": "镜子：照人用的器具，与“善意”没有反义关系。"}], "correct_answer": "恶意", "explanations": {"恶意": "恶意：与“善意”相对，指怀有不好的用意。", "报纸": "报纸：定期出版的印刷品，与“善意”没有反义关系。", "雨伞": "雨伞：挡雨用的器具，与“善意”没有反义关系。", "镜子": "镜子：照人用的器具，与“善意”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对别人好的心意。", "primary_collocate": null, "pronunciation": "shàn yì", "ipa": "ʂan˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他的善意让我很感动。", "target_word": "善意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对每个人都很有善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用善意对待身边的人。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份善意我会一直记在心里。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们的善意让老人笑了。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他表示了善意，可是对方没有接受。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然不认识他，但我能看出他的善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢大家的善意，我会好好努力。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把一份善意藏在一张小卡片里。", "target_word": "善意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怀疑我，我对你没有坏心，只有善意。", "target_word": "善意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "善意：对别人怀有的好心意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caac8116-bbb0-40db-b2bd-488d2c40e0ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "善意", "is_correct": true, "explanation": "善意：对别人的好心意，与“他的……让我很感动”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，不能让人感动。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指体型，不能让人感动。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教具，不能让人感动。"}], "explanations": {"善意": "善意：对别人的好心意，与“他的……让我很感动”相合。", "冰箱": "语义：“冰箱”是电器，不能让人感动。", "身高": "体貌：“身高”指体型，不能让人感动。", "黑板": "语义：“黑板”是教具，不能让人感动。"}, "sentence_index": 0, "correct_answer": "善意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的善意在学校举行。", "explanation": "这里应该用〈活动〉。善意是好心，不是能在学校举行的事；能举行的是“活动”。"}, {"text": "他把善意放进了冰箱。", "explanation": "这里应该用〈食物〉。善意是好心，不是能放进冰箱的东西；能放进冰箱的是“食物”。"}, {"text": "妈妈切开了一份善意。", "explanation": "这里应该用〈蛋糕〉。善意是抽象的心意，不能像蛋糕那样切开；能切开的是“蛋糕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善意", "is_correct": true, "explanation": "善意：对别人的好心意，与“能看出他的……”相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通讯工具，不是可以被看出的心意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“看出”后接的是心意或状态，不能接“窗户”。"}, {"text": "锅", "is_correct": false, "explanation": "语义：“锅”是炊具，不能被“看出”。"}], "explanations": {"善意": "善意：对别人的好心意，与“能看出他的……”相合。", "电话": "语义：“电话”是通讯工具，不是可以被看出的心意。", "窗户": "搭配：“看出”后接的是心意或状态，不能接“窗户”。", "锅": "语义：“锅”是炊具，不能被“看出”。"}, "sentence_index": 6, "correct_answer": "善意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的善意很咸。", "explanation": "这里应该用〈口味〉。善意是好心，没有咸淡之分；说咸淡要用“口味”，指食物才说咸。"}, {"text": "他用善意修好了那辆自行车。", "explanation": "这里应该用〈工具〉。善意是好心，不能拿来修理东西；修车要用“工具”。"}, {"text": "她的善意很湿。", "explanation": "这里应该用〈衣服〉。善意是心意，没有干湿之分；会湿的是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她善意的帮助了我。", "corrected_sentence": "她善意地帮助了我。", "error_description": "状语错误：修饰动词“帮助”的状语要用“地”，“善意的帮助了我”应为“善意地帮助了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她曾经收到过我的一只善意。", "corrected_sentence": "她曾经收到过我的一份善意。", "error_description": "量词错误：“善意”应用量词“份”计量，“一只”只用于动物，应说“一份善意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1290d92c-e7b4-47b3-ad92-00364367db95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
