INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指一样东西是不是真的。", "primary_collocate": null, "pronunciation": "zhēn shí xìng", "ipa": "ʈʂən˥ ʂʐ̩˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "买东西时，要看商品的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀疑这张钱的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话，我不知道真实性有多高。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友发来的消息，我还没检查真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的真实性，要请专家来看。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道这张照片的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些名牌鞋的真实性很让人担心。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的故事，常常没有人检查真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在检查这张票的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想确认这份合同的真实性。", "target_word": "真实性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真實性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "东西是真是假", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真实性", "is_correct": true, "explanation": "正确：「真实性」指东西是不是真的，符合「要看商品的……」的语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人或动物的高度，商品没有身高。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：性格只与人或动物搭配，不说商品的性格。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人或动物身体的温度，与商品不符。"}], "explanations": {"真实性": "正确：「真实性」指东西是不是真的，符合「要看商品的……」的语境。", "身高": "语义：身高指人或动物的高度，商品没有身高。", "性格": "搭配：性格只与人或动物搭配，不说商品的性格。", "体温": "语义：体温指人或动物身体的温度，与商品不符。"}, "sentence_index": 0, "correct_answer": "真实性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的真实性很长。", "explanation": "这里应该用〈长度〉。「真实性」指东西是否真，路的长短要用「长度」。"}, {"text": "他终于流露出了真实性。", "explanation": "这里应该用〈真情〉。「真实性」指东西是否真实，流露的是感情，要用「真情」。"}, {"text": "这块石头的真实性很重。", "explanation": "这里应该用〈重量〉。「真实性」指东西是否真，石头的轻重要用「重量」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真实性", "is_correct": true, "explanation": "正确：「真实性」指东西是不是真的，符合「让人担心」的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，鞋子不说体重。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情只属于有感情的人，鞋子没有心情。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气只用于人或动物，不能与「鞋」搭配。"}], "explanations": {"真实性": "正确：「真实性」指东西是不是真的，符合「让人担心」的语境。", "体重": "语义：体重指人或动物的重量，鞋子不说体重。", "心情": "语义：心情只属于有感情的人，鞋子没有心情。", "脾气": "搭配：脾气只用于人或动物，不能与「鞋」搭配。"}, "sentence_index": 6, "correct_answer": "真实性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们必须搬走这个真实性。", "explanation": "这里应该用〈东西〉。「真实性」是性质，不能搬走；搬动的是具体的东西。"}, {"text": "他终于说出了真实性。", "explanation": "这里应该用〈实情〉。「说出」的对象是具体的情况，真实性不能被说出。"}, {"text": "这家公司的真实性雄厚。", "explanation": "这里应该用〈实力〉。「雄厚」形容实力或资金，「真实性」指事物是否真实，不能说雄厚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要核实这份资料的一个真实性。", "corrected_sentence": "我们要核实这份资料的真实性。", "error_description": "「真实性」表示事物的总体性质，不宜与「一个」计数；「资料的一个真实性」不通，应去掉「一个」，说「资料的真实性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家正在鉴定这些古画真实性。", "corrected_sentence": "专家正在鉴定这些古画的真实性。", "error_description": "修饰语和中心语之间要加「的」，应为「古画的真实性」，不能直接说「古画真实性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
