INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "颜色就是眼睛看到的东西的样子，比如红色、蓝色、黄色。", "primary_collocate": null, "pronunciation": "yán sè", "ipa": "jɛn˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "红、黄、蓝都是颜色。", "target_word": "颜色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你知道苹果有哪些颜色吗？", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们用不同的颜色画了一幅画。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的铅笔盒里有十二种颜色的笔。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你告诉我，天空是什么颜色。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小狗的颜色是黑白相间的。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们最喜欢哪种颜色。", "target_word": "颜色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色和黄色混在一起，会变成新的颜色。", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子有两种颜色，你想要哪一种？", "target_word": "颜色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想用什么颜色画太阳？", "target_word": "颜色", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "顏色", "label": "繁体"}], "register": "中性", "sense_fingerprint": "红、蓝、黄等日常所说的颜色种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色（yán sè）：红、蓝、黄等日常所说的颜色种类，是本词条的读音与意义。"}, {"text": "严肃", "is_correct": false, "explanation": "yán 相同，第二音节韵母 e 与 u 不同，意思是严肃。"}, {"text": "眼色", "is_correct": false, "explanation": "yǎn（上声）与 yán（阳平）声调不同，意思是眼神示意。"}, {"text": "难色", "is_correct": false, "explanation": "声母 n 与 y 不同，意思是为难的神色。"}], "explanations": {"颜色": "颜色（yán sè）：红、蓝、黄等日常所说的颜色种类，是本词条的读音与意义。", "严肃": "yán 相同，第二音节韵母 e 与 u 不同，意思是严肃。", "眼色": "yǎn（上声）与 yán（阳平）声调不同，意思是眼神示意。", "难色": "声母 n 与 y 不同，意思是为难的神色。"}, "sentence_index": null, "correct_answer": "颜色"}, "level_3": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色：红、黄、蓝都属于颜色的种类，句意通顺。"}, {"text": "形状", "is_correct": false, "explanation": "语义：红、黄、蓝指颜色，不是形状，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：红、黄、蓝指颜色，不是味道，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：红、黄、蓝指颜色，不是声音，句意不通。"}], "explanations": {"颜色": "颜色：红、黄、蓝都属于颜色的种类，句意通顺。", "形状": "语义：红、黄、蓝指颜色，不是形状，句意不通。", "味道": "语义：红、黄、蓝指颜色，不是味道，句意不通。", "声音": "语义：红、黄、蓝指颜色，不是声音，句意不通。"}, "sentence_index": 0, "correct_answer": "颜色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的颜色很长。", "explanation": "这里应该用〈深〉。颜色用深浅形容，不能用长短形容。"}, {"text": "我的铅笔盒里有十二只颜色的笔。", "explanation": "这里应该用〈种〉。颜色的量词是“种”，不用“只”。"}, {"text": "这朵花很颜色。", "explanation": "这里应该用〈鲜艳〉。“颜色”是名词，不能用“很”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": true, "explanation": "颜色：可以被“最喜欢哪种”挑选的对象，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能作“最喜欢哪种”的挑选对象。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：没有人会“最喜欢哪种疾病”，句意荒谬。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以挑选喜好的对象，句意不通。"}], "explanations": {"颜色": "颜色：可以被“最喜欢哪种”挑选的对象，句意通顺。", "空气": "搭配：“空气”不能作“最喜欢哪种”的挑选对象。", "疾病": "语义：没有人会“最喜欢哪种疾病”，句意荒谬。", "时间": "语义：时间不是可以挑选喜好的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "颜色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你把这个太阳颜色一下。", "explanation": "这里应该用〈上色〉。“颜色”是名词，不能直接作动词表示涂色。"}, {"text": "他买了一台颜色。", "explanation": "这里应该用〈种〉。颜色的量词是“种”，不用“台”。"}, {"text": "你想给太阳颜色吗？", "explanation": "这里应该用〈上色〉。“颜色”不作动词，不能说“给太阳颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你喜欢哪一只颜色？", "corrected_sentence": "你喜欢哪一种颜色？", "error_description": "量词错误：“颜色”的量词用“种”，不用“只”，应说“哪一种颜色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
