INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西都放到一起。", "primary_collocate": null, "pronunciation": "shōu jí", "ipa": "ʂoʊ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈把吃完饭的碗收集起来，拿去洗。", "target_word": "收集", "complexity_tier": "T3", "furigana": "shōu jí", "sentence_source": "generated"}, {"text": "请把大家的本子收集到一起。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公园里收集落叶。", "target_word": "收集", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们收集了很多漂亮的石头。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明每天收集一个空瓶子。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先收集废纸，再送去回收站。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，爷爷用桶收集屋顶流下来的水。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把用过的笔收集起来。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收集着家里所有的旧杂志。", "target_word": "收集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，我们去山上收集松果。", "target_word": "收集", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "收集了", "label": "体标（完成）"}, {"form": "收集过", "label": "体标（经历）"}, {"form": "收集着", "label": "体标（持续）"}, {"form": "收集起来", "label": "复合（趋向）"}], "register": "中性", "sense_fingerprint": "收集：把零散的实物都放到一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b91ba0fb-3b3b-487a-84e1-8487031e38b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。收集（shōu jí）指把东西都放到一起。"}, {"text": "手机", "is_correct": false, "explanation": "手（shǒu）与收（shōu）声调不同，“手机”指手持的电话。"}, {"text": "招集", "is_correct": false, "explanation": "招（zhāo）与收（shōu）声母不同（zh 与 sh），声调相同，意思是召集、集合人员。"}, {"text": "收寄", "is_correct": false, "explanation": "寄（jì）与集（jí）声调不同，意思是收取并寄出邮件。"}, {"text": "首集", "is_correct": false, "explanation": "首（shǒu）与收（shōu）声调不同，集（jí）同调，意思是电视剧等的第一集。"}], "explanations": {"收集": "正确。收集（shōu jí）指把东西都放到一起。", "手机": "手（shǒu）与收（shōu）声调不同，“手机”指手持的电话。", "招集": "招（zhāo）与收（shōu）声母不同（zh 与 sh），声调相同，意思是召集、集合人员。", "收寄": "寄（jì）与集（jí）声调不同，意思是收取并寄出邮件。", "首集": "首（shǒu）与收（shōu）声调不同，集（jí）同调，意思是电视剧等的第一集。"}, "sentence_index": null, "correct_answer": "收集"}, "level_3": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。“把碗收集起来，拿去洗”指把碗放到一起，再拿去洗。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说“把碗煮起来”。"}, {"text": "摆", "is_correct": false, "explanation": "语义：“摆”是摆放展示，与后面“拿去洗”的意思不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与后面“拿去洗”的意思相矛盾。"}], "explanations": {"收集": "正确。“把碗收集起来，拿去洗”指把碗放到一起，再拿去洗。", "煮": "搭配：“煮”的对象是食物，不能说“把碗煮起来”。", "摆": "语义：“摆”是摆放展示，与后面“拿去洗”的意思不符。", "扔": "语义：“扔”是丢弃，与后面“拿去洗”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "收集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们收集了一个小男孩。", "explanation": "这里应该用〈收养〉。收养指领养孩子，收集只用于分散的东西。"}, {"text": "父亲决定收集那家小饭馆。", "explanation": "这里应该用〈收购〉。收购指买下企业，收集指把零散的东西聚到一起。"}, {"text": "他正在收集房间。", "explanation": "这里应该用〈收拾〉。收拾指整理，收集不用于整理房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27756, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。收集（shōu jí）指把东西都放到一起。"}, {"text": "受挤", "is_correct": false, "explanation": "受（shòu）与收（shōu）声调不同，挤（jǐ）与集（jí）声调不同，意思是被挤压。"}, {"text": "兽迹", "is_correct": false, "explanation": "兽（shòu）与收声调不同，迹（jì）与集声调不同，意思是野兽留下的足迹。"}, {"text": "手记", "is_correct": false, "explanation": "手记（shǒu jì）两个音节的声调都与收集不同，意思是亲手写下的记录。"}, {"text": "首级", "is_correct": false, "explanation": "首（shǒu）与收声调不同，意思是古代战争中割下的敌人头颅。"}], "explanations": {"收集": "正确。收集（shōu jí）指把东西都放到一起。", "受挤": "受（shòu）与收（shōu）声调不同，挤（jǐ）与集（jí）声调不同，意思是被挤压。", "兽迹": "兽（shòu）与收声调不同，迹（jì）与集声调不同，意思是野兽留下的足迹。", "手记": "手记（shǒu jì）两个音节的声调都与收集不同，意思是亲手写下的记录。", "首级": "首（shǒu）与收声调不同，意思是古代战争中割下的敌人头颅。"}, "sentence_index": null, "correct_answer": "收集"}, "level_3": {"options": [{"text": "收集", "is_correct": true, "explanation": "正确。“用桶收集屋顶流下来的水”指用桶把流下来的水接到一起。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”与“用桶”组合不通，也不说“喝屋顶流下来的水”。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”不能与“水”构成这样的搭配。"}, {"text": "喷", "is_correct": false, "explanation": "语义：“喷”是向外射出，与“用桶承接”雨水的意思相反。"}], "explanations": {"收集": "正确。“用桶收集屋顶流下来的水”指用桶把流下来的水接到一起。", "喝": "搭配：“喝”与“用桶”组合不通，也不说“喝屋顶流下来的水”。", "踩": "搭配：“踩”不能与“水”构成这样的搭配。", "喷": "语义：“喷”是向外射出，与“用桶承接”雨水的意思相反。"}, "sentence_index": 6, "correct_answer": "收集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只流浪猫被好心人收集了。", "explanation": "这里应该用〈收留〉。收留用于收容人或动物，收集只用于分散的东西。"}, {"text": "政府对进口汽车收集高额关税。", "explanation": "这里应该用〈征收〉。征收指国家依法收取税款，收集不用于收税。"}, {"text": "她每天晚上都收集广播。", "explanation": "这里应该用〈收听〉。收听指听广播，收集不用于听广播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸收集了着很多旧报纸。", "corrected_sentence": "爸爸收集着很多旧报纸。", "error_description": "错误：“收集了着”，“了”和“着”不能同时用在同一个动词上。正确：“收集着”，表示动作正在持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把晾干的衣服收集一起。", "corrected_sentence": "妈妈把晾干的衣服收集到一起。", "error_description": "错误：“收集一起”，缺少介词“到”。正确：“收集到一起”，表示把东西归到同一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
