INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "折射出就像镜子照出东西一样，让人看到隐藏的样子。", "primary_collocate": null, "pronunciation": "zhé shè chū", "ipa": "ʈʂɤ˧˥ ʂɤ˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "他的作文折射出他的想法。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑容折射出心里的高兴。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片折射出老人的孤单。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的话折射出家里的样子。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的画折射出心里的害怕。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的疲惫折射出工作的压力。", "target_word": "折射出", "complexity_tier": "T3", "furigana": "tā de pí bèi zhé shè chū gōng zuò de yā lì", "sentence_source": "generated"}, {"text": "一个小动作折射出他的性格。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边的小店折射出城市的生活。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信折射出他心里的想法。", "target_word": "折射出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的选择折射出他的真实想法。", "target_word": "折射出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "折射出了", "label": "体标"}, {"form": "折射出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：像镜子一样让人看到隐藏的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折射出", "is_correct": true, "explanation": "正确：“折射出”表示通过作文让人看到隐藏的想法，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”说把想法吞没，与让人看到想法的意思相反。"}, {"text": "洗掉", "is_correct": false, "explanation": "语义：“洗掉”使想法消失，与“让人看到”的意思相反。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”的对象是纸张，不能说“装订想法”。"}], "explanations": {"折射出": "正确：“折射出”表示通过作文让人看到隐藏的想法，符合句意。", "吃掉": "语义：“吃掉”说把想法吞没，与让人看到想法的意思相反。", "洗掉": "语义：“洗掉”使想法消失，与“让人看到”的意思相反。", "装订": "搭配：“装订”的对象是纸张，不能说“装订想法”。"}, "sentence_index": 0, "correct_answer": "折射出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "橱窗里折射出新款衣服。", "explanation": "这里应该用〈展示〉。展示是把东西摆出来给人看；折射出是让隐藏的样子显露，不能用于摆放商品。"}, {"text": "乌云折射出了太阳。", "explanation": "这里应该用〈掩盖〉。掩盖是遮住、不让人看见；折射出是让隐藏的样子显露出来，二者意思相反。"}, {"text": "窗帘折射出了光线。", "explanation": "这里应该用〈遮挡〉。遮挡是挡住光线、不让它透过；折射出是让隐藏的样子显露。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折射出", "is_correct": true, "explanation": "正确：“小动作”能折射出性格，符合句意。"}, {"text": "收起", "is_correct": false, "explanation": "语义：“收起”是收藏的意思，与“小动作”显示性格的意思不合。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉他的性格”与“让人看到”的意思相反。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于“性格”。"}], "explanations": {"折射出": "正确：“小动作”能折射出性格，符合句意。", "收起": "语义：“收起”是收藏的意思，与“小动作”显示性格的意思不合。", "丢掉": "语义：“丢掉他的性格”与“让人看到”的意思相反。", "煮": "搭配：“煮”的对象是食物，不能用于“性格”。"}, "sentence_index": 6, "correct_answer": "折射出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆折射出许多古代文物。", "explanation": "这里应该用〈陈列〉。陈列是把物品摆放出来供人参观；折射出不用于具体文物的展出。"}, {"text": "货架折射出各种水果。", "explanation": "这里应该用〈摆出〉。摆出指把物品摆放在货架上；折射出不能用于具体物品的摆放。"}, {"text": "工厂折射出精美的礼盒。", "explanation": "这里应该用〈包装〉。包装指把物品装进包装物；折射出不能用于制作礼盒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的沉默被折射出心里的不安。", "corrected_sentence": "他的沉默折射出心里的不安。", "error_description": "错误：多用了“被”。正确：“折射出”是主动式，表示让人看到隐藏的样子，不加“被”，应说“他的沉默折射出心里的不安。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封信折射出他的真实想法来。", "corrected_sentence": "这封信折射出他的真实想法。", "error_description": "错误：在句末多用了“来”。正确：“折射出”后直接接宾语，句末不加“来”，应说“这封信折射出他的真实想法。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
