INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水流很急，不平稳。", "primary_collocate": null, "pronunciation": "luàn liú", "ipa": "lwan˥˩ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这条河有乱流，游泳很危险。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船长看到前面有乱流，马上慢下来。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洪过后，河水里出现了乱流。", "target_word": "乱流", "complexity_tier": "T3", "furigana": "luàn liú", "sentence_source": "generated"}, {"text": "河中间的乱流很急，小船过不去。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水下有乱流，游泳的人要小心。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乱流中用力划船。", "target_word": "乱流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桥下的乱流把小船推走了。", "target_word": "乱流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的乱流让很多人不敢下水。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山口的河水很急，形成了乱流。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说这里的乱流，去年带走了一条船。", "target_word": "乱流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "亂流", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水中又急又不平稳的水流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1bae2b-5f4e-4b27-899a-8770b7917f2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乱流", "is_correct": true, "explanation": "“乱流”指又急又不平稳的水流，正是“游泳很危险”的原因。"}, {"text": "书", "is_correct": false, "explanation": "语义：河里不会有书，与“游泳很危险”的语境不相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：河中没有钢琴，这个说法不成立。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“有”后的花园多指岸边的园林，不说河里有花园。"}], "explanations": {"乱流": "“乱流”指又急又不平稳的水流，正是“游泳很危险”的原因。", "书": "语义：河里不会有书，与“游泳很危险”的语境不相合。", "钢琴": "语义：河中没有钢琴，这个说法不成立。", "花园": "搭配：“有”后的花园多指岸边的园林，不说河里有花园。"}, "sentence_index": 0, "correct_answer": "乱流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们用乱流做了一张桌子。", "explanation": "这里应该用〈木材〉。“乱流”指水流，不能用作制作桌子的材料。"}, {"text": "山间的溪流平静得像一面镜子。", "explanation": "这里应该用〈溪流〉。“乱流”指又急又不平稳的水流，与“平静得像一面镜子”矛盾。"}, {"text": "湖面上泛起一圈乱流。", "explanation": "这里应该用〈涟漪〉。“乱流”指激烈不平的水流，不能形容湖面上轻微的涟漪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乱流", "is_correct": true, "explanation": "“乱流”指桥下急而不平的水流，能把小船冲走，与句意相合。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸推不动小船，句意不通。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：花瓣太轻，不会把小船推走。"}, {"text": "鼓声", "is_correct": false, "explanation": "搭配：“推走”的施事多为水流、风等，“鼓声”不能推船。"}], "explanations": {"乱流": "“乱流”指桥下急而不平的水流，能把小船冲走，与句意相合。", "报纸": "语义：报纸推不动小船，句意不通。", "花瓣": "语义：花瓣太轻，不会把小船推走。", "鼓声": "搭配：“推走”的施事多为水流、风等，“鼓声”不能推船。"}, "sentence_index": 6, "correct_answer": "乱流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的乱流很平缓，适合游泳。", "explanation": "这里应该用〈水流〉。“乱流”指又急又不平稳的水流，不能形容平缓的河水。"}, {"text": "足球场上，球员们在草地上乱流，没有配合。", "explanation": "这里应该用〈乱跑〉。“乱流”只指水流，不用于形容球员在场上奔跑。"}, {"text": "乱流在石头间平静地流着。", "explanation": "这里应该用〈溪水〉。“乱流”指又急又不平稳的水，与“平静地流着”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面有一把乱流，船要慢下来。", "corrected_sentence": "前面有一股乱流，船要慢下来。", "error_description": "“乱流”的量词应用“股”；“把”用于有柄的器具，不能用于水流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河里的乱流了很急，船不能过。", "corrected_sentence": "河里的乱流很急，船不能过。", "error_description": "“乱流”是名词，“了”不能直接加在名词与形容词“很急”之间；应说“河里的乱流很急”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
