INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等啊等，直到某个时候。", "primary_collocate": null, "pronunciation": "děng dào", "ipa": "tɤŋ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们等到十点，他还没来。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在门口等到天黑。", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我一直等到十二点才睡觉。", "target_word": "等到", "complexity_tier": "T3", "furigana": "děng dào", "sentence_source": "generated"}, {"text": "他在办公室里等到下班才离开。", "target_word": "等到", "complexity_tier": "T3", "furigana": "děng dào", "sentence_source": "generated"}, {"text": "病人一直等到医生来。", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要等到什么时候？", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗在门口等到主人回家。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们等到比赛结束才离开。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他等啊等，一直等到太阳下山。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈等到半夜，孩子才回来。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等到了", "label": "体标（完成）"}, {"form": "等到过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "等到：一直等，直到某个时间或结果出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b91ba0fb-3b3b-487a-84e1-8487031e38b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示一直等，直到某个时间，与“十点”和“他还没来”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃到十点”说的是吃东西吃到某时，与“他还没来”的等待语境不合。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫到十点”不是“等待”的搭配，不能表示一直等到某个时间。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿到十点”不成立，“拿到”指取得物品，不能表示持续到某个时间。"}], "explanations": {"等到": "等到表示一直等，直到某个时间，与“十点”和“他还没来”相呼应。", "吃": "语义：“吃到十点”说的是吃东西吃到某时，与“他还没来”的等待语境不合。", "叫": "搭配：“叫到十点”不是“等待”的搭配，不能表示一直等到某个时间。", "拿": "语义：“拿到十点”不成立，“拿到”指取得物品，不能表示持续到某个时间。"}, "sentence_index": 0, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站等到了一个小时。", "explanation": "这里应该用〈等了〉或〈等待〉。〈等到〉表示等来某个时间或结果，不能与表示持续时段的“一个小时”连用。"}, {"text": "这场比赛等到天黑才结束。", "explanation": "这里应该用〈直到〉。〈等到〉的主语必须是能够等待的人，“这场比赛”不能等待，表示事情持续到某时才结束要用〈直到〉。"}, {"text": "这项工程等到明年才完工。", "explanation": "这里应该用〈直到〉。〈等到〉的主语须能等待，“这项工程”不能等待，表示持续到某时才完成要用〈直到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示一直等，直到主人回家，与“在门口”和“回家”相呼应。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬到主人回家”说的是咬东西，与“在门口”等待的语境不合。"}, {"text": "挡", "is_correct": false, "explanation": "搭配：“挡”需要带宾语，不能说“挡到主人回家”。"}, {"text": "扑", "is_correct": false, "explanation": "语义：“扑到主人回家”说的是扑上去，与小狗在门口静候的意思不合。"}], "explanations": {"等到": "等到表示一直等，直到主人回家，与“在门口”和“回家”相呼应。", "咬": "语义：“咬到主人回家”说的是咬东西，与“在门口”等待的语境不合。", "挡": "搭配：“挡”需要带宾语，不能说“挡到主人回家”。", "扑": "语义：“扑到主人回家”说的是扑上去，与小狗在门口静候的意思不合。"}, "sentence_index": 6, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨等到半夜才停。", "explanation": "这里应该用〈直到〉。〈等到〉的主语必须能够等待，“雨”不能等待，表示持续到某时才停要用〈直到〉。"}, {"text": "妈妈在门口等到了半个晚上。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻或结果，不能与持续的时段“半个晚上”连用。"}, {"text": "妈妈等到门口，孩子才回来。", "explanation": "这里应该用〈走到〉。〈等到〉表示等待直到某个时刻或事件出现，不表示移动到某个地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在车站等到到了天亮。", "corrected_sentence": "我在车站等到了天亮。", "error_description": "错误：“到”被重复写了一次。正确：“等到了”中只用一个“到”，“了”紧跟在“等到”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在门口的等到了妈妈。", "corrected_sentence": "孩子在门口等到了妈妈。", "error_description": "错误：“等到”前多加了“的”，使动词被错误地当作名词性修饰语。正确：“孩子在门口”作状语，“等到了妈妈”直接作谓语，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从坐着或躺着变成站着。", "primary_collocate": null, "pronunciation": "qǐ lái", "ipa": "tɕʰi˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始了，观众都起来鼓掌。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从椅子上起来，给老人让座。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他躺了一会儿，就起来倒水喝。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你起来，让我过去一下。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗趴在地上，听到声音就起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸坐在门口，看见客人马上起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡醒了，自己从床上起来穿衣服。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“都坐下，谁也不要起来。”", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他累得坐在地上，半天没起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车一停，坐着的人都起来拿行李。", "target_word": "起来", "complexity_tier": "T3", "furigana": "chē yì tíng, zuò zhe de rén dōu qǐ lái ná xíng li.", "sentence_source": "generated"}], "morphological_forms": [{"form": "起来了", "label": "体标"}], "register": "口语", "sense_fingerprint": "由坐或躺变成站；起身站立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示由坐变为站立，符合“比赛开始了，观众都……鼓掌”的语境。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”表示快速移动，不能与“鼓掌”搭配说明观众的动作状态。"}, {"text": "走", "is_correct": false, "explanation": "搭配：“走”表示移动，不能与“鼓掌”搭配说明观众的状态。"}, {"text": "躺", "is_correct": false, "explanation": "语义：观众躺着鼓掌与比赛场景不合，也与起身的意思相反。"}], "explanations": {"起来": "起来：表示由坐变为站立，符合“比赛开始了，观众都……鼓掌”的语境。", "跑": "搭配：“跑”表示快速移动，不能与“鼓掌”搭配说明观众的动作状态。", "走": "搭配：“走”表示移动，不能与“鼓掌”搭配说明观众的状态。", "躺": "语义：观众躺着鼓掌与比赛场景不合，也与起身的意思相反。"}, "sentence_index": 0, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站着说话，突然坐起来了。", "explanation": "这里应该用〈坐下来〉。“坐起来”指从躺卧变为坐直，从站立变为坐要用“坐下来”。"}, {"text": "他从椅子上一站，就躺起来了。", "explanation": "这里应该用〈躺下来〉。“躺下来”表示由站或坐变为躺，“起来”表示起身，方向相反。"}, {"text": "他正在走，突然停起来了。", "explanation": "这里应该用〈停下来〉。“起来”表示开始，中止要用“停下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从床上起身，符合“孩子睡醒了，自己从床上……穿衣服”的语境。"}, {"text": "躺", "is_correct": false, "explanation": "语义：“躺”指躺卧，与睡醒后起身穿衣的动作相反"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”不能表示从床上离开后再穿衣服的动作，搭配不当。"}, {"text": "睡", "is_correct": false, "explanation": "语义：句首已说“睡醒了”，“睡”与前文重复，且与起身穿衣不合。"}], "explanations": {"起来": "起来：表示从床上起身，符合“孩子睡醒了，自己从床上……穿衣服”的语境。", "躺": "语义：“躺”指躺卧，与睡醒后起身穿衣的动作相反", "站": "搭配：“站”不能表示从床上离开后再穿衣服的动作，搭配不当。", "睡": "语义：句首已说“睡醒了”，“睡”与前文重复，且与起身穿衣不合。"}, "sentence_index": 6, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一推，就倒起来了。", "explanation": "这里应该用〈倒下〉。“倒下”表示由站或坐变为躺卧，“起来”表示起身，不能表示倒下。"}, {"text": "他坐在椅子上，突然跪起来了。", "explanation": "这里应该用〈跪下来〉。从坐到跪是向下的动作，应说“跪下来”；“跪起来”表示由卧倒的姿势起身成跪，与“坐在椅子上”的前提不合。"}, {"text": "他忘了这件事，过了很久才停起来。", "explanation": "这里应该用〈停下来〉。“停下来”表示中止，“起来”表示开始，不能用于中止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一听到门铃，就从沙发上站起来着。", "corrected_sentence": "他一听到门铃，就从沙发上站起来了。", "error_description": "错误形式：“站起来着”；正确形式：“站起来了”。动作已经完成要用“了”，“着”不能表示此处的完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坐在后面的人就站起来的。", "corrected_sentence": "坐在后面的人就站起来了。", "error_description": "错误形式：“站起来的”；正确形式：“站起来了”。表示动作已经发生要用“了”，“的”不能代替“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
