INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "用来表示做一件事的目的或方法。", "primary_collocate": null, "pronunciation": "yòng lái", "ipa": "jʊŋ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这把刀用来切菜。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "筷子是用来吃饭的。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子用来喝水。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机可以用来看书。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用来写字的笔坏了。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱用来买书了。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上的纸是用来画画的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个本子是用来记生词的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把这个房间用来学习。", "target_word": "用来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱是用来放吃的东西的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "动词，后面接动词，表示某物被拿来做某件事的用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cff21b5d-b947-4065-949c-1c97782d2ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用来", "is_correct": true, "explanation": "“用来”表示用途，这把刀正是用来切菜的。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”的主语须是有感情的人，刀不能喜欢切菜。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后接活动或事件，不能接“切菜”这样的动作。"}, {"text": "管理", "is_correct": false, "explanation": "搭配：“管理”的对象是人、事务或单位，不能接“切菜”。"}], "explanations": {"用来": "“用来”表示用途，这把刀正是用来切菜的。", "喜欢": "语义：“喜欢”的主语须是有感情的人，刀不能喜欢切菜。", "参加": "搭配：“参加”后接活动或事件，不能接“切菜”这样的动作。", "管理": "搭配：“管理”的对象是人、事务或单位，不能接“切菜”。"}, "sentence_index": 0, "correct_answer": "用来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用来去学校。", "explanation": "这里不能用〈用来〉。〈用来〉的主语应是物品，“他”是人，应说“他骑车去学校”。"}, {"text": "明天用来下雨。", "explanation": "这里应该用〈会〉。〈用来〉表示为了某个目的使用物品或做事，“下雨”是自然现象，不能作为目的，应说“明天会下雨”。"}, {"text": "用来省钱，我每天带午饭。", "explanation": "这里应该用〈为了〉。〈用来〉多用于物品的用途，人主动做事表示目的时应说“为了省钱，我每天带午饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用来", "is_correct": true, "explanation": "“用来”表示用途，这里说纸是用来画画的。"}, {"text": "负责", "is_correct": false, "explanation": "语义：“负责”的主语须是能承担责任的人，纸不能负责画画。"}, {"text": "擅长", "is_correct": false, "explanation": "语义：“擅长”的主语须是有技能的人，纸不能擅长画画。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”需要有参与者，纸不能讨论画画。"}], "explanations": {"用来": "“用来”表示用途，这里说纸是用来画画的。", "负责": "语义：“负责”的主语须是能承担责任的人，纸不能负责画画。", "擅长": "语义：“擅长”的主语须是有技能的人，纸不能擅长画画。", "讨论": "配价：“讨论”需要有参与者，纸不能讨论画画。"}, "sentence_index": 6, "correct_answer": "用来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室用来学生上课。", "explanation": "这里应该用〈供〉。〈用来〉表示物品的用途，不能直接把人作为受益者，应说“供学生上课”。"}, {"text": "这家商店用来顾客买东西。", "explanation": "这里应该用〈方便〉。〈用来〉的宾语应是物品的用途，不能直接把顾客作为使用者，应说“这家商店方便顾客买东西”。"}, {"text": "这间屋子用来老人的休息。", "explanation": "这里应该用〈供〉。“用来”不能接“老人的休息”这样的名词短语，应说“供老人休息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把刀用来用削水果。", "corrected_sentence": "这把刀用来削水果。", "error_description": "错误：“用来”后面多加了一个“用”（用来用削水果）。正确：应说“用来削水果”，“用来”后直接接动词，不能再加“用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子是用来用来装针的。", "corrected_sentence": "这个盒子是用来装针的。", "error_description": "错误：“用来”重复出现（用来用来装针）。正确：只用一个“用来”，说“是用来装针的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西被拉或压时，里面产生的力。", "primary_collocate": null, "pronunciation": "yìng lì", "ipa": "iŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "拉橡皮筋的时候，里面有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西一压，里面就会有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁条弯了，是因为应力太大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力是东西里面产生的力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用力拉绳子，绳子里有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力越大，应力也越大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用弹簧给我们讲应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃杯里有应力，所以容易裂。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根木头压断了，应力太大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力小，东西就不容易坏。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应力集中", "label": "复合词"}, {"form": "残余应力", "label": "复合词"}], "register": "通用", "sense_fingerprint": "日常：东西被拉或压时里面产生的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。应力指东西被拉或压时里面产生的力。"}, {"text": "引力", "is_correct": false, "explanation": "yǐn（第三声）与 yìng（第四声）韵母与声调都不同，意思是引力。"}, {"text": "盈利", "is_correct": false, "explanation": "声调混淆：yíng 与 yìng 只差声调，意思是盈利。"}, {"text": "用力", "is_correct": false, "explanation": "yòng 与 yìng 声调相同，但韵母不同（ong 与 ing），意思是用力。"}], "explanations": {"应力": "正确答案。应力指东西被拉或压时里面产生的力。", "引力": "yǐn（第三声）与 yìng（第四声）韵母与声调都不同，意思是引力。", "盈利": "声调混淆：yíng 与 yìng 只差声调，意思是盈利。", "用力": "yòng 与 yìng 声调相同，但韵母不同（ong 与 ing），意思是用力。"}, "sentence_index": null, "correct_answer": "应力"}, "level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。拉橡皮筋时，橡皮筋里面产生的就是应力。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是东西被拉时里面产生的力，与句中语境不符。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会在橡皮筋里产生，与拉伸的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能说东西里面有身高。"}], "explanations": {"应力": "正确答案。拉橡皮筋时，橡皮筋里面产生的就是应力。", "颜色": "语义：颜色不是东西被拉时里面产生的力，与句中语境不符。", "饭菜": "语义：饭菜不会在橡皮筋里产生，与拉伸的语境不符。", "身高": "体貌：身高是人的外形特征，不能说东西里面有身高。"}, "sentence_index": 0, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的应力很大。", "explanation": "这里应该用〈力气〉。应力是东西被拉或压时里面产生的力，指人身上的力气不说应力。"}, {"text": "这次考试我的应力很大。", "explanation": "这里应该用〈压力〉。应力指东西里面的力，考试带来的心理负担要用“压力”。"}, {"text": "空气应力很大。", "explanation": "这里应该用〈阻力〉。应力是东西里面产生的力，外部阻碍运动的力要用“阻力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。老师用弹簧讲的是东西被拉或压时里面产生的应力。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不能被“讲”，且与弹簧的物理语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭与用弹簧讲解的内容无关。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“讲”的宾语应是知识内容，楼梯不能作为讲的对象。"}], "explanations": {"应力": "正确答案。老师用弹簧讲的是东西被拉或压时里面产生的应力。", "饺子": "语义：饺子不能被“讲”，且与弹簧的物理语境不符。", "早饭": "语义：早饭与用弹簧讲解的内容无关。", "楼梯": "搭配：“讲”的宾语应是知识内容，楼梯不能作为讲的对象。"}, "sentence_index": 6, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "绳子里有一座应力。", "explanation": "这里应该用〈种〉。“座”用于山、房屋等大型固定的东西，应力是一种力，应用“种”。"}, {"text": "箱子里有一颗应力。", "explanation": "这里应该用〈种〉。“颗”用于颗粒状的东西，应力不能这样计量。"}, {"text": "木条里有一本应力。", "explanation": "这里应该用〈种〉。“本”用于书册，应力是一种力，应用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "绳子有里应力，所以会断。", "corrected_sentence": "绳子里有应力，所以会断。", "error_description": "位置错误：「有里应力」应为「里有应力」。方位词“里”要放在“有”之前，表示在绳子内部。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "绳子拉紧后，里面的应力变大着。", "corrected_sentence": "绳子拉紧后，里面的应力变大了。", "error_description": "动态助词错误：「变大着」应为「变大了」。变化已经发生，要用“了”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
