INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机肥是用动植物做成的肥料，能让植物长得更好。", "primary_collocate": null, "pronunciation": "yǒu jī féi", "ipa": "iou˨˩˦ tɕi˥ fei˧˥", "syllable_count": 3, "sentences": [{"text": "妈妈在花盆里放了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥是用动物粪便做成的。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋有机肥可以用来种菜。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了有机肥，青菜长得很快。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷自己在院子里做有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥没有化肥那么快见效。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥放久了会有一点臭味。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给西红柿浇水，又加了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的有机肥都是牛粪做的。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥能让土地更肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机肥料", "label": "复合"}, {"form": "有機肥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用动植物做成、让植物长得更好的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：有机肥是施在花盆土里的肥料，与“花盆里”和“放了”相符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是施在花盆里的肥料。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油易燃，不能放在花盆里给植物用。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“牛奶”是液体，在花盆里应说“倒”，不与“放了”搭配。"}], "explanations": {"有机肥": "正确：有机肥是施在花盆土里的肥料，与“花盆里”和“放了”相符。", "饼干": "语义：饼干是食品，不是施在花盆里的肥料。", "汽油": "语义：汽油易燃，不能放在花盆里给植物用。", "牛奶": "搭配：“牛奶”是液体，在花盆里应说“倒”，不与“放了”搭配。"}, "sentence_index": 0, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用了有机肥，虫子就死了。", "explanation": "这里应该用〈农药〉。有机肥用来增加土壤肥力，不能杀虫，杀虫要用农药。"}, {"text": "播下有机肥，等它发芽。", "explanation": "这里应该用〈种子〉。有机肥是肥料，不能播下去发芽，播下的应是种子。"}, {"text": "我买了一只有机肥。", "explanation": "量词：有机肥应用“袋”或“堆”计量，“只”一般用于动物，这里不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：有机肥是由有机物质制成的，放久会发酵产生气味，与“臭味”相符。"}, {"text": "钢材", "is_correct": false, "explanation": "语义：钢材不会腐烂，也不会产生臭味。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“放久了会有臭味”通常说易腐物，“玻璃”不能与“臭味”搭配。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池放久不会因腐败而产生臭味。"}], "explanations": {"有机肥": "正确：有机肥是由有机物质制成的，放久会发酵产生气味，与“臭味”相符。", "钢材": "语义：钢材不会腐烂，也不会产生臭味。", "玻璃": "搭配：“放久了会有臭味”通常说易腐物，“玻璃”不能与“臭味”搭配。", "电池": "语义：电池放久不会因腐败而产生臭味。"}, "sentence_index": 6, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牛每天要吃有机肥。", "explanation": "这里应该用〈饲料〉。有机肥是肥料，不能给牛吃，给牛吃的是饲料。"}, {"text": "用有机肥洗手。", "explanation": "这里应该用〈肥皂〉。有机肥不能用来洗手，“肥皂”与“肥”字相近，学习者易混淆，洗手应使用肥皂。"}, {"text": "我买了一把有机肥。", "explanation": "量词：“把”用于可以握住的东西，有机肥应用“袋”或“堆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上放着两个有机肥。", "corrected_sentence": "我家阳台上放着两袋有机肥。", "error_description": "量词错误：“有机肥”应用“袋”计量，说“两袋有机肥”；用“个”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落堆着一堆有机肥们。", "corrected_sentence": "院子角落堆着一堆有机肥。", "error_description": "词缀错误：“们”不能加在“有机肥”后面。“们”只用于指人或拟人的复数，表示物质的肥料应直接说“一堆有机肥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自制", "is_correct": true, "explanation": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。"}, {"text": "精美", "is_correct": false, "explanation": "精美指精致漂亮，与市售不构成反义关系。"}, {"text": "廉价", "is_correct": false, "explanation": "廉价指价格低，与市售不构成反义关系。"}, {"text": "大号", "is_correct": false, "explanation": "大号指尺寸大，与市售不构成反义关系。"}], "correct_answer": "自制", "explanations": {"自制": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。", "精美": "精美指精致漂亮，与市售不构成反义关系。", "廉价": "廉价指价格低，与市售不构成反义关系。", "大号": "大号指尺寸大，与市售不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自制", "is_correct": true, "explanation": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。"}, {"text": "进口", "is_correct": false, "explanation": "进口指从国外输入，与市售不构成反义关系。"}, {"text": "高档", "is_correct": false, "explanation": "高档指等级高，与市售不构成反义关系。"}, {"text": "常见", "is_correct": false, "explanation": "常见指经常看到，与市售不构成反义关系。"}], "correct_answer": "自制", "explanations": {"自制": "正确答案。自制指自己制作，与“市售”（在商店里卖的）相对。", "进口": "进口指从国外输入，与市售不构成反义关系。", "高档": "高档指等级高，与市售不构成反义关系。", "常见": "常见指经常看到，与市售不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在商店里卖的。", "primary_collocate": null, "pronunciation": "shì shòu", "ipa": "ʂɨ˥˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "市售面包比家里做的贵。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些饼干都是市售的。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喝市售饮料，只喝白开水。", "target_word": "市售", "complexity_tier": "T3", "furigana": "shì shòu", "sentence_source": "generated"}, {"text": "市售酱油有很多牌子。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市售的花盆太小了。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用市售肥料给花施肥。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市售洗发水里有香味。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市售茶叶种类很多，价格差别也很大。", "target_word": "市售", "complexity_tier": "T3", "furigana": "shì shòu", "sentence_source": "generated"}, {"text": "市售牛肉每斤多少钱？", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自己做的饺子比市售的好吃。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在商店里买得到的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "制售", "is_correct": false, "explanation": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。"}, {"text": "世守", "is_correct": false, "explanation": "shì shǒu 第二音节声调不同（shǒu 与 shòu），意思是世代守护。"}, {"text": "私售", "is_correct": false, "explanation": "sī shòu（第一声）与 shì shòu 声母与声调都不同，意思是私下出售。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "制售": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。", "世守": "shì shǒu 第二音节声调不同（shǒu 与 shòu），意思是世代守护。", "私售": "sī shòu（第一声）与 shì shòu 声母与声调都不同，意思是私下出售。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。与“面包比家里做的贵”形成比较，指在商店买的面包。"}, {"text": "自家", "is_correct": false, "explanation": "语义：“自家”与“家里做的”意思重复，句子自相矛盾。"}, {"text": "家常", "is_correct": false, "explanation": "搭配：“家常”多修饰菜肴，一般不说家常面包。"}, {"text": "自制", "is_correct": false, "explanation": "语义：自制面包与“家里做的”同属自家制作，比较对象矛盾。"}], "explanations": {"市售": "正确答案。与“面包比家里做的贵”形成比较，指在商店买的面包。", "自家": "语义：“自家”与“家里做的”意思重复，句子自相矛盾。", "家常": "搭配：“家常”多修饰菜肴，一般不说家常面包。", "自制": "语义：自制面包与“家里做的”同属自家制作，比较对象矛盾。"}, "sentence_index": 0, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自己做的酱油是市售的，很好吃。", "explanation": "这里应该用〈自制〉。市售指在商店里卖的，自己做的酱油不能说是市售的。"}, {"text": "这些蔬菜是市售的，不用花钱，很新鲜。", "explanation": "这里应该用〈自产〉。市售指在商店里卖的，此处说不用花钱，应说自产的。"}, {"text": "这幅画是市售的，从来不卖。", "explanation": "这里应该用〈私藏〉。市售指在商店里卖的，与“从来不卖”自相矛盾；私藏指自己收藏，从不拿出来卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "失守", "is_correct": false, "explanation": "shī shǒu 两个音节的声调都不同，意思是丢掉阵地。"}, {"text": "失收", "is_correct": false, "explanation": "shī shōu 两个音节的声调都不同，意思是农作物歉收。"}, {"text": "实收", "is_correct": false, "explanation": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "失守": "shī shǒu 两个音节的声调都不同，意思是丢掉阵地。", "失收": "shī shōu 两个音节的声调都不同，意思是农作物歉收。", "实收": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。指在商店买的洗发水，与“有香味”不矛盾。"}, {"text": "无香", "is_correct": false, "explanation": "语义：“无香”与后文“有香味”直接矛盾。"}, {"text": "无味", "is_correct": false, "explanation": "语义：“无味”与后文“有香味”直接矛盾。"}, {"text": "臭", "is_correct": false, "explanation": "语义：“臭”表示难闻，与后文“有香味”直接矛盾。"}], "explanations": {"市售": "正确答案。指在商店买的洗发水，与“有香味”不矛盾。", "无香": "语义：“无香”与后文“有香味”直接矛盾。", "无味": "语义：“无味”与后文“有香味”直接矛盾。", "臭": "语义：“臭”表示难闻，与后文“有香味”直接矛盾。"}, "sentence_index": 6, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有个市售的主意，大家都很佩服。", "explanation": "这里应该用〈现成〉。市售指在商店里卖的，主意不能在商店里买，应说现成的主意。"}, {"text": "这个问题是市售的，我们一起讨论。", "explanation": "这里应该用〈共同〉。市售指在商店里卖的商品，问题不是商品；大家都关心的问题应说共同的问题。"}, {"text": "我的朋友是市售的，我很喜欢他。", "explanation": "这里应该用〈亲密〉。市售只能指商品，不能用来形容人；表示关系近，应说亲密的朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶酱油是市售，买来就能用。", "corrected_sentence": "这瓶酱油是市售的，买来就能用。", "error_description": "“市售”作谓语时后面要加“的”，应说“是市售的”，不能只说“是市售”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种面包是市售，我每天都买。", "corrected_sentence": "这种面包是市售的，我每天都买。", "error_description": "「市售」作谓语时后面要加「的」，应说「是市售的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
