INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河里面。", "primary_collocate": null, "pronunciation": "hé li", "ipa": "xɤ˧˥ li", "syllable_count": 2, "sentences": [{"text": "桥下的河里有一条小船。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里有几只白色的鸭子。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，河里的冰化了。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把石头扔进河里。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的水又深又凉。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸在河里钓了一个小时。", "target_word": "河里", "complexity_tier": "T3", "furigana": "hé li", "sentence_source": "generated"}, {"text": "河里长着很多绿色的草。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下雨，河里的水变多了。", "target_word": "河里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗跳到河里去找球。", "target_word": "河里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在河里看见过一只大乌龟。", "target_word": "河里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "河裡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河的里面，河水所在的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc291c4a-a51a-41d4-a5f8-14d9ec8cbac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河里", "is_correct": true, "explanation": "河里指水中，桥下的水里有小船，符合常识。"}, {"text": "天上", "is_correct": false, "explanation": "语义：“桥下”指桥的下方，天上在空中，小船不会在天上。"}, {"text": "树上", "is_correct": false, "explanation": "语义：小船不能停在树上，与“有一条小船”的语境不符。"}, {"text": "地下", "is_correct": false, "explanation": "搭配：“桥下”与“地下”都表示下方，重复并列，不能说“桥下的地下”。"}], "explanations": {"河里": "河里指水中，桥下的水里有小船，符合常识。", "天上": "语义：“桥下”指桥的下方，天上在空中，小船不会在天上。", "树上": "语义：小船不能停在树上，与“有一条小船”的语境不符。", "地下": "搭配：“桥下”与“地下”都表示下方，重复并列，不能说“桥下的地下”。"}, "sentence_index": 0, "correct_answer": "河里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们常在河里散步，看两岸的风景。", "explanation": "这里应该用〈河边〉。散步要在岸边进行，「河里」指水中。"}, {"text": "学生们在河里打篮球，玩得很开心。", "explanation": "这里应该用〈操场〉。打篮球要在场地上，「河里」指水中，不能在水里打篮球。"}, {"text": "我们在河里搭帐篷，过夜很舒服。", "explanation": "这里应该用〈岸上〉。搭帐篷要在陆地上，「河里」指水中，帐篷不能立在水里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad8b29ac-064f-498b-9d02-96f632d8d41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河里", "is_correct": true, "explanation": "河里指水中，水中长草是常见的情况，句意通顺。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：书包里不会长草，与“长着很多绿色的草”的语境冲突。"}, {"text": "天空中", "is_correct": false, "explanation": "语义：草不能长在天空中，句子与常识相矛盾。"}, {"text": "作业本上", "is_correct": false, "explanation": "语义：作业本是纸张，草不能长在作业本上，句意不通。"}], "explanations": {"河里": "河里指水中，水中长草是常见的情况，句意通顺。", "书包里": "语义：书包里不会长草，与“长着很多绿色的草”的语境冲突。", "天空中": "语义：草不能长在天空中，句子与常识相矛盾。", "作业本上": "语义：作业本是纸张，草不能长在作业本上，句意不通。"}, "sentence_index": 6, "correct_answer": "河里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在河里玩滑梯，很开心。", "explanation": "这里应该用〈游乐场〉。滑梯设在陆地上，「河里」指水中，不能在水里玩滑梯。"}, {"text": "农民在河里插秧，一片绿油油的。", "explanation": "这里应该用〈田里〉。插秧要在水田中，「河里」指天然河流的水中，不是田地。"}, {"text": "奶奶坐在河里看电视，看得很开心。", "explanation": "这里应该用〈沙发上〉。看电视要坐在沙发或椅子上，「河里」指水中，不能坐在水里看电视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad8b29ac-064f-498b-9d02-96f632d8d41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一群鸭子河里游。", "corrected_sentence": "一群鸭子在河里游。", "error_description": "错误：处所词「河里」前漏掉介词「在」，写成「河里游」。正确应为「在河里游」，处所要由「在」引出，放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad8b29ac-064f-498b-9d02-96f632d8d41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在河里的找到一只乌龟。", "corrected_sentence": "他在河里找到一只乌龟。", "error_description": "错误：「河里」后多出结构助词「的」，使「在河里的」变成定语，句子缺少中心语。正确应为「在河里找到一只乌龟」，处所短语后不加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad8b29ac-064f-498b-9d02-96f632d8d41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
