INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长着很多树的地方。", "primary_collocate": null, "pronunciation": "lín dì", "ipa": "lin˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "我家附近有一片林地。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "林地里的树又高又密。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在林地里捉迷藏。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天，林地里比外面凉快。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他沿着林地边走了很久。", "target_word": "林地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林地里住着很多鸟和松鼠。", "target_word": "林地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片林地太大了，我们差点迷路。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们去林地里散步。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨后的林地里有一股泥土的味道。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人每天早上都到林地里锻炼。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片林地", "label": "量词"}, {"form": "一块林地", "label": "量词"}, {"form": "林地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "林地|长着很多树的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff60a6df-f4f4-401a-bb61-77843d9f1642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确答案：长着很多树的地方。"}, {"text": "领地", "is_correct": false, "explanation": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。"}, {"text": "林立", "is_correct": false, "explanation": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。"}, {"text": "林带", "is_correct": false, "explanation": "dài 与 dì 韵母不同（ai / i），意思是成条状的防护林。"}, {"text": "心地", "is_correct": false, "explanation": "xīn 与 lín 声母和声调都不同，dì 相同，意思是内心、心肠。"}], "explanations": {"林地": "正确答案：长着很多树的地方。", "领地": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。", "林立": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。", "林带": "dài 与 dì 韵母不同（ai / i），意思是成条状的防护林。", "心地": "xīn 与 lín 声母和声调都不同，dì 相同，意思是内心、心肠。"}, "sentence_index": null, "correct_answer": "林地"}, "level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：“一片”用于成片的土地，“林地”与“我家附近有一片”搭配自然。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“一片”不能修饰手机，手机应说“一部”。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“一片”不能修饰教室，教室应说“一间”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通线路，不是可以成片的地方，“我家附近有一片地铁”不成立。"}], "explanations": {"林地": "正确：“一片”用于成片的土地，“林地”与“我家附近有一片”搭配自然。", "手机": "搭配：“一片”不能修饰手机，手机应说“一部”。", "教室": "搭配：“一片”不能修饰教室，教室应说“一间”。", "地铁": "语义：地铁是交通线路，不是可以成片的地方，“我家附近有一片地铁”不成立。"}, "sentence_index": 0, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家在山脚下有一把林地。", "explanation": "这里应该用〈片〉。“把”用于有柄的器具，林地是成片的土地，不能用“把”计量。"}, {"text": "村口那只林地是我们的骄傲。", "explanation": "这里应该用〈片〉。“只”用于动物等，不能用来计量土地。"}, {"text": "这座小镇里有一本林地。", "explanation": "这里应该用〈块〉。“本”用于书册等，不能用来计量林地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：“这片”用于成片的地方，“太大了，差点迷路”符合林地的语境。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“这片”不能修饰手机，手机应说“这部”或“这台”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是大到会让人迷路的地方，“太大了，差点迷路”不符合常识。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不会“太大到差点迷路”。"}], "explanations": {"林地": "正确：“这片”用于成片的地方，“太大了，差点迷路”符合林地的语境。", "手机": "搭配：“这片”不能修饰手机，手机应说“这部”或“这台”。", "课本": "语义：课本不是大到会让人迷路的地方，“太大了，差点迷路”不符合常识。", "电话": "语义：电话是通讯工具，不会“太大到差点迷路”。"}, "sentence_index": 6, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人家门口有一棵林地，每天早上都去锻炼。", "explanation": "这里应该用〈片〉。“棵”用于单株的树，林地是一大片土地，不能用“棵”计量。"}, {"text": "老人家的后院有一扇林地。", "explanation": "这里应该用〈片〉。“扇”用于门窗等，林地不能用“扇”计量。"}, {"text": "老人每天早上都去一朵林地里锻炼。", "explanation": "这里应该用〈片〉。“朵”用于花、云等，林地不能用“朵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口有一把林地。", "corrected_sentence": "村口有一片林地。", "error_description": "量词错误：“林地”是成片的土地，应说“一片林地”，不能说“一把林地”。“把”用于有柄的器具，不能用来计量林地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们常常林地里采蘑菇。", "corrected_sentence": "我们常常在林地里采蘑菇。", "error_description": "介词缺失：表示地点的状语“林地里”前应加介词“在”，说“在林地里采蘑菇”，不能省去“在”直接说“林地里采蘑菇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3257bc17-cdf2-4445-9d7d-b458351f56b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
