INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买东西时心里想的怎么花钱的想法。", "primary_collocate": null, "pronunciation": "xiāo fèi guān niàn", "ipa": "ɕiɑʊ˥ feɪ˥˩ kuan˥ njɛn˥˩", "syllable_count": 4, "sentences": [{"text": "我妈妈的消费观念是能省就省。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的消费观念是想买就买，不太想以后。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西以前，先想想你的消费观念。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们夫妻的消费观念不一样，常常吵架。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买东西很小心，因为她的消费观念比较保守。", "target_word": "消费观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的消费观念差别很大。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的消费观念变了，现在不乱买东西了。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈人的消费观念是先存钱，再花钱。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的消费观念影响了我的购物习惯。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生的消费观念应该是够用就行。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "消費觀念", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人买东西时关于怎么花钱的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f3ad525-ec43-4f5b-948b-9899e9b8bc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "语义：“学历”是教育背景，与“能省就省”的花钱态度无关，句子语义不通"}, {"text": "消费观念", "is_correct": true, "explanation": "“消费观念”指花钱的想法，与“能省就省”相符"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句的语体不协调，且不适合指称母亲的想法"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体特征，不能说“能省就省”"}], "explanations": {"学历": "语义：“学历”是教育背景，与“能省就省”的花钱态度无关，句子语义不通", "消费观念": "“消费观念”指花钱的想法，与“能省就省”相符", "玩意儿": "语域：“玩意儿”是口语说法，与这句的语体不协调，且不适合指称母亲的想法", "身高": "语义：“身高”是身体特征，不能说“能省就省”"}, "sentence_index": 0, "correct_answer": "消费观念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的消费观念很贵，一个人就能买下整套房子。", "explanation": "这里应该用〈购买力〉。消费观念是看法，不能用“很贵”来形容；说购买能力的强弱要用〈购买力〉。"}, {"text": "我们家的消费观念比邻居贵很多。", "explanation": "这里应该用〈消费水平〉。观念是看法，比较花钱多少要用〈消费水平〉"}, {"text": "他有一把好的消费观念。", "explanation": "量词错误：消费观念应搭配〈种〉，〈把〉用于有柄的器具。这里应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发型", "is_correct": false, "explanation": "语义：发型的变化与“不乱买东西”没有关联，句子语义不通"}, {"text": "消费观念", "is_correct": true, "explanation": "“消费观念”指花钱的想法，它的变化能带来不乱买东西的结果"}, {"text": "行头", "is_correct": false, "explanation": "语义：“行头”指服装装扮，与“不乱买东西”的消费态度没有关联，句意不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡的变化不能带来“不乱买东西”的结果，句子语义不通"}], "explanations": {"发型": "语义：发型的变化与“不乱买东西”没有关联，句子语义不通", "消费观念": "“消费观念”指花钱的想法，它的变化能带来不乱买东西的结果", "行头": "语义：“行头”指服装装扮，与“不乱买东西”的消费态度没有关联，句意不通。", "咖啡": "语义：咖啡的变化不能带来“不乱买东西”的结果，句子语义不通"}, "sentence_index": 6, "correct_answer": "消费观念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她周末去商场买了不少消费观念。", "explanation": "这里把消费观念当作商品来买。买的对象应是〈商品〉，消费观念是看法，不能被买"}, {"text": "他在消费观念里找到了一份工作。", "explanation": "这里把消费观念误当作找工作的场所。找工作应去〈公司〉，消费观念是抽象的看法"}, {"text": "她每天早上都喝消费观念。", "explanation": "这里把消费观念当作饮料来喝。喝的应是〈饮料〉，消费观念不能喝"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一块节俭的消费观念。", "corrected_sentence": "他有一种节俭的消费观念。", "error_description": "量词错误：“消费观念”应搭配“种”，“块”用于块状的东西，不能说“一块消费观念”，应说“一种节俭的消费观念”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友有一种很超前消费观念，常常提前买东西。", "corrected_sentence": "朋友有一种很超前的消费观念，常常提前买东西。", "error_description": "结构错误：“很超前”修饰名词时要加“的”，应说“很超前的消费观念”，不能省略“的”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
