INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物种是长得像、能生宝宝的一类动物或植物。", "primary_collocate": null, "pronunciation": "wù zhǒng", "ipa": "u˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "地球上有很多不同的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎是很珍贵的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个物种长得很像。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个物种的动物可以生宝宝。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有成千上万个物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的物种已经从地球上消失了。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究海里的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫是中国特有的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个物种只生活在热带雨林里。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同物种的动物通常不能生出宝宝。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "物種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物种：日常所说的长得像、能生宝宝的一类动物或植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。物种读作 wù zhǒng，指长得像、能生宝宝的一类动植物。"}, {"text": "五种", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。"}, {"text": "雾中", "is_correct": false, "explanation": "声调混淆：zhōng（第一声）与 zhǒng（第三声）只差声调，“雾中”指在雾里。"}, {"text": "误中", "is_correct": false, "explanation": "声调混淆：zhòng（第四声）与 zhǒng（第三声）只差声调，“误中”指错误地击中。"}], "explanations": {"物种": "正确。物种读作 wù zhǒng，指长得像、能生宝宝的一类动植物。", "五种": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。", "雾中": "声调混淆：zhōng（第一声）与 zhǒng（第三声）只差声调，“雾中”指在雾里。", "误中": "声调混淆：zhòng（第四声）与 zhǒng（第三声）只差声调，“误中”指错误地击中。"}, "sentence_index": null, "correct_answer": "物种"}, "level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“地球上有很多不同的物种”是常见说法。"}, {"text": "天体", "is_correct": false, "explanation": "语义：天体在地球之外的天空中，与“地球上”的语境不符。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指人的性情，不用来描述地球上的事物。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”多用于人或个体，不说“地球上有很多不同的性格”。"}], "explanations": {"物种": "正确。“地球上有很多不同的物种”是常见说法。", "天体": "语义：天体在地球之外的天空中，与“地球上”的语境不符。", "脾气": "搭配：“脾气”指人的性情，不用来描述地球上的事物。", "性格": "搭配：“性格”多用于人或个体，不说“地球上有很多不同的性格”。"}, "sentence_index": 0, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "文具店里的文具物种很多。", "explanation": "这里应该用〈种类〉。物种指能相互生宝宝的一类动植物，不用来说文具的种类。"}, {"text": "水是一种很常见的物种。", "explanation": "这里应该用〈物质〉。物种指能生宝宝的动植物，水不是动植物，不能叫物种，应说物质。"}, {"text": "这本书属于哪个物种？", "explanation": "这里应该用〈类别〉。物种只指动植物的类别，书籍的分类不叫物种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“研究海里的物种”指研究海洋中的动植物种类，合乎语境。"}, {"text": "大陆", "is_correct": false, "explanation": "语义：大陆是陆地，不在海里，不能作为海里的研究对象。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是交易凭证，不是可以在海里研究的对象。"}, {"text": "品德", "is_correct": false, "explanation": "搭配：“品德”多指人的道德修养，不说“海里的品德”。"}], "explanations": {"物种": "正确。“研究海里的物种”指研究海洋中的动植物种类，合乎语境。", "大陆": "语义：大陆是陆地，不在海里，不能作为海里的研究对象。", "发票": "语义：发票是交易凭证，不是可以在海里研究的对象。", "品德": "搭配：“品德”多指人的道德修养，不说“海里的品德”。"}, "sentence_index": 6, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个游戏的物种很多。", "explanation": "这里应该用〈类型〉。物种只指动植物的类别，不能用来说游戏的类型。"}, {"text": "这间屋子里摆满了各种物种。", "explanation": "这里应该用〈物件〉。物种指动植物的类别，屋里的器物不叫物种，应说物件。"}, {"text": "这所学校开设的课程物种很齐全。", "explanation": "这里应该用〈门类〉。物种只用于生物分类，不能用来说课程的门类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们发现了一只新的物种。", "corrected_sentence": "我们发现了一个新的物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“只”用于单个动物，不能用来修饰物种。正确说法：一个新的物种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里发现了一棵古老的物种。", "corrected_sentence": "这里发现了一个古老的物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“棵”用于树木，不能用来修饰物种。正确说法：一个古老的物种。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
