INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最下面的一层，比如政府的乡镇、街道和村这些离老百姓最近的地方。", "primary_collocate": null, "pronunciation": "jī céng", "ipa": "tɕi⁵⁵ tsʰəŋ³⁵", "syllable_count": 2, "sentences": [{"text": "乡镇和村都属于基层。", "target_word": "基层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "基层离老百姓最近，问题也最多。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在街道办事处工作，是基层的工作人员。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓有困难，常常先找基层。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个镇是最基层的政府，直接管村里的事。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策要先让基层的人听明白。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基层的医院帮了村里很多人。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想去基层，看看村里的真实情况。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些问题在基层最容易发现。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村委会是离农民最近的基层组织。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "基層", "label": "繁体"}, {"form": "基层组织", "label": "复合"}, {"form": "基层政府", "label": "复合"}], "register": "中性", "sense_fingerprint": "最下面、离老百姓最近的一层（乡镇、街道、村）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f217853e-c44a-4a7e-bf9e-9fbe27715e66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指最下面一层，即乡镇、街道和村这些离老百姓最近的地方。"}, {"text": "几层", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。"}, {"text": "集成", "is_correct": false, "explanation": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。"}, {"text": "几成", "is_correct": false, "explanation": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}], "explanations": {"基层": "“基层”指最下面一层，即乡镇、街道和村这些离老百姓最近的地方。", "几层": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。", "集成": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。", "几成": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}, "sentence_index": null, "correct_answer": "基层"}, "level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指乡镇、街道和村这些最下面的一层，与句意相符。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指过去的时间与事件，乡镇和村不属于“历史”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是组织层级，“属于”后接的类别搭配不当。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“机器”是器械，乡镇和村不属于机器，句意不通。"}], "explanations": {"基层": "“基层”指乡镇、街道和村这些最下面的一层，与句意相符。", "历史": "语义：“历史”指过去的时间与事件，乡镇和村不属于“历史”。", "颜色": "搭配：“颜色”不是组织层级，“属于”后接的类别搭配不当。", "机器": "语义：“机器”是器械，乡镇和村不属于机器，句意不通。"}, "sentence_index": 0, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "以这次调查的数据为基层，我们做了分析。", "explanation": "这里应该用〈基准〉。基准指衡量事物的标准，基层指离老百姓最近的一层。"}, {"text": "他有扎实的数学基层，学得很快。", "explanation": "这里应该用〈基础〉。基础指学习或事物的根基，基层指离老百姓最近的一层。"}, {"text": "这个班的学生基层是三十人。", "explanation": "这里应该用〈基数〉。基数指计算时的基础数目，基层指离老百姓最近的一层，不能表示人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”修饰“医院”，指离老百姓最近的一层医院，与句意相符。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”不能修饰“医院”来指帮助村民的机构，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”不能修饰“医院”，说“花园的医院”搭配不当。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”与“医院”不搭，无法构成有意义的修饰，句意不通。"}], "explanations": {"基层": "“基层”修饰“医院”，指离老百姓最近的一层医院，与句意相符。", "游戏": "语义：“游戏”不能修饰“医院”来指帮助村民的机构，句意不通。", "花园": "搭配：“花园”不能修饰“医院”，说“花园的医院”搭配不当。", "数学": "语义：“数学”与“医院”不搭，无法构成有意义的修饰，句意不通。"}, "sentence_index": 6, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府设立了一项扶贫基层，帮助困难家庭。", "explanation": "这里应该用〈基金〉。基金指为某种用途聚集的资金，基层指离老百姓最近的一层。"}, {"text": "这个基层决定了植物的颜色。", "explanation": "这里应该用〈基因〉。基因指决定生物遗传性状的单位，基层不能决定植物的颜色。"}, {"text": "勤奋是成功的基层。", "explanation": "这里应该用〈基石〉。基石指建筑的根基，比喻根本，基层指离老百姓最近的一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要基层多听听群众的意见。", "corrected_sentence": "我们要在基层多听听群众的意见。", "error_description": "缺少介词：“要”后直接接处所名词“基层”，句子缺少介词，应加“在”，说“在基层多听听”（也可说“到基层”“深入基层”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乡里有一把基层医院。", "corrected_sentence": "乡里有一家基层医院。", "error_description": "量词“把”用于有柄的器具，医院应用量词“家”，应说“一家基层医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ecf2b32-2b1c-46a3-a1c6-90b36bd3fee9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "正确。“留下”与“带走”相反，指把东西留在原来的地方。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。"}, {"text": "修补", "is_correct": false, "explanation": "“修补”指修理破损的东西，与“带走”没有反义关系。"}, {"text": "聊天", "is_correct": false, "explanation": "“聊天”指交谈，与“带走”没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "正确。“留下”与“带走”相反，指把东西留在原来的地方。", "整理": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。", "修补": "“修补”指修理破损的东西，与“带走”没有反义关系。", "聊天": "“聊天”指交谈，与“带走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "正确。“留下”与“带走”相反，指离开时把小猫留在原处。"}, {"text": "喂养", "is_correct": false, "explanation": "“喂养”指给动物或人提供食物，与“带走”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走走，与“带走”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指用笔写字，与“带走”没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "正确。“留下”与“带走”相反，指离开时把小猫留在原处。", "喂养": "“喂养”指给动物或人提供食物，与“带走”没有反义关系。", "散步": "“散步”指随意走走，与“带走”没有反义关系。", "写字": "“写字”指用笔写字，与“带走”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某人或某物从一处带到另一处。", "primary_collocate": null, "pronunciation": "dài zǒu", "ipa": "tai̯˥˩ tsou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察把那个人带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把迷路的孩子带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人带走了，去做检查。", "target_word": "带走", "complexity_tier": "T3", "furigana": "yī shēng bǎ bìngrén dàizǒu le, qù zuò jiǎnchá", "sentence_source": "generated"}, {"text": "工人把这些箱子从房间带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来了以后，把旧桌子带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸今天把我的自行车带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车明天会把这些书带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把垃圾带走，不要放在这里。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友开车把我带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人把路边的小猫带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带走了", "label": "体标（完成）"}, {"form": "带走过", "label": "体标（经历）"}, {"form": "带不走", "label": "可能补语（否定）"}, {"form": "带得走", "label": "可能补语（肯定）"}], "register": "中性", "sense_fingerprint": "把人或物从原来的地方转移带往别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带走", "is_correct": true, "explanation": "正确。带走 dài zǒu，指把人或物从一处带到另一处。"}, {"text": "抬走", "is_correct": false, "explanation": "tái（第二声）与 dài（第四声）声母与声调都不同，意思是用手抬起来搬走。"}, {"text": "再走", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），意思是再走一次或稍后再走。"}, {"text": "得走", "is_correct": false, "explanation": "děi（第三声）与 dài（第四声）韵母与声调不同，意思是不得不离开。"}], "explanations": {"带走": "正确。带走 dài zǒu，指把人或物从一处带到另一处。", "抬走": "tái（第二声）与 dài（第四声）声母与声调都不同，意思是用手抬起来搬走。", "再走": "zài 与 dài 声母不同（z 与 d），意思是再走一次或稍后再走。", "得走": "děi（第三声）与 dài（第四声）韵母与声调不同，意思是不得不离开。"}, "sentence_index": null, "correct_answer": "带走"}, "level_3": {"options": [{"text": "复印", "is_correct": false, "explanation": "语义：“复印”的对象是纸张文件，不能用来处理一个人。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示把人从一处带到别处，与“警察”的执法语境相合。"}, {"text": "推销", "is_correct": false, "explanation": "搭配：“推销”的宾语是商品，不能说推销一个人。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：人不能被吃掉，与句中警察处理人员的语境不合。"}], "explanations": {"复印": "语义：“复印”的对象是纸张文件，不能用来处理一个人。", "带走": "正确。“带走”表示把人从一处带到别处，与“警察”的执法语境相合。", "推销": "搭配：“推销”的宾语是商品，不能说推销一个人。", "吃掉": "语义：人不能被吃掉，与句中警察处理人员的语境不合。"}, "sentence_index": 0, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把这些箱子给我们带走了。", "explanation": "这里应该用〈运来〉。带走是把东西从一处拿到别处，送到说话人一方要用运来，“给我们”与带走方向相反。"}, {"text": "他把这些书往我们这儿带走了。", "explanation": "这里应该用〈带来〉。带走指从这里拿走，朝说话人这边运来要用带来，“往我们这儿”与带走方向相反。"}, {"text": "他把那座桥带走了。", "explanation": "这里不能用〈带走〉。桥固定不动，不能随人离开，不能说带走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装饰", "is_correct": false, "explanation": "语义：货车是运输工具，不会去装饰书，与句中的运送语境不合。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示把东西拿到别处，与“货车明天会”的运送语境相合。"}, {"text": "晾干", "is_correct": false, "explanation": "搭配：“晾干”多用于湿的衣物，不说晾干要运走的书。"}, {"text": "修理", "is_correct": false, "explanation": "语义：货车不会去修理书，与运送的语境矛盾。"}], "explanations": {"装饰": "语义：货车是运输工具，不会去装饰书，与句中的运送语境不合。", "带走": "正确。“带走”表示把东西拿到别处，与“货车明天会”的运送语境相合。", "晾干": "搭配：“晾干”多用于湿的衣物，不说晾干要运走的书。", "修理": "语义：货车不会去修理书，与运送的语境矛盾。"}, "sentence_index": 6, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友给我们带走一只小猫，让我们养。", "explanation": "这里应该用〈送来〉。带走是把东西从一处拿到别处，“给我们”的东西是送到说话人一方，要用送来。"}, {"text": "他把路边的那堵墙带走了。", "explanation": "这里不能用〈带走〉。墙固定在地上，不能被人或车带离原处，不能说带走。"}, {"text": "老师给我们带走一本书，让我们读。", "explanation": "这里应该用〈拿来〉。带走指把东西拿到别处，交到说话人手里要用拿来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人已经箱子带走了。", "corrected_sentence": "工人已经把箱子带走了。", "error_description": "漏掉“把”：“箱子”是“带走”的宾语，要用“把”提到动词前，应说“工人已经把箱子带走了”，不能说“工人已经箱子带走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个箱子很轻，你它把带走吧。", "corrected_sentence": "这个箱子很轻，你把它带走吧。", "error_description": "语序错误：“把”应放在宾语“它”之前，不能把“它”放在“把”的前面，应说“你把它带走吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
