INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花粉是花里面的一种小粉末，能让花结出种子。", "primary_collocate": null, "pronunciation": "huā fěn", "ipa": "xua˥ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "花里有一些黄色的花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小蜜蜂的身上都是花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花粉很小，像细细的粉末。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用手摸了花，手上有花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了花粉，花才能结出种子。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟看着花上的花粉，觉得很好玩。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂把花粉带到别的花上，花才能结出果实。", "target_word": "花粉", "complexity_tier": "T3", "furigana": "mì fēng bǎ huā fěn dài dào bié de huā shàng, huā cái néng jiē chū guǒ shí", "sentence_source": "generated"}, {"text": "这朵花的花粉是白色的。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天风大，花粉飞得到处都是。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，不要把花粉弄到眼睛里。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点花粉", "label": "量词"}, {"form": "花粉管", "label": "复合"}], "register": "中性", "sense_fingerprint": "花里的小粉末，能让花结出种子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43fcd651-f37e-4c54-87ee-af7602635d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "正确：句中“花粉”指花里的小粉末，能让花结出种子。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不会出现在花里，句子说的是花的粉末。"}, {"text": "绿叶", "is_correct": false, "explanation": "体貌：“黄色的”和“绿叶”颜色冲突，绿叶本身是绿色的。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会长在花里，这句话不合事实。"}], "explanations": {"花粉": "正确：句中“花粉”指花里的小粉末，能让花结出种子。", "电脑": "语义：电脑是机器，不会出现在花里，句子说的是花的粉末。", "绿叶": "体貌：“黄色的”和“绿叶”颜色冲突，绿叶本身是绿色的。", "面包": "语义：面包不会长在花里，这句话不合事实。"}, "sentence_index": 0, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用花粉做了一锅面条。", "explanation": "这里应该用〈面粉〉。做面条要用面粉，花粉不能用来和面。"}, {"text": "他用花粉在纸上写了名字。", "explanation": "这里应该用〈笔〉。在纸上写字要用笔，花粉是粉末，不能用来写字。"}, {"text": "桌子上放着一个花粉。", "explanation": "这里应该用〈点〉。“个”是通用量词，用于能一个一个数的东西；花粉是粉末，应该说“一点花粉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "正确：句中“花粉”是花里的粉状微粒，蜜蜂把它带到别的花上，花才能结出果实。"}, {"text": "种子", "is_correct": false, "explanation": "语义：种子不能靠蜜蜂带到别的花上来帮花结果，句子说的是授粉。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是蜜蜂酿在蜂巢里的，不用来带到花上促进结果。"}, {"text": "大树", "is_correct": false, "explanation": "体貌：大树体形很大，蜜蜂带不动，句子不合常理。"}], "explanations": {"花粉": "正确：句中“花粉”是花里的粉状微粒，蜜蜂把它带到别的花上，花才能结出果实。", "种子": "语义：种子不能靠蜜蜂带到别的花上来帮花结果，句子说的是授粉。", "蜂蜜": "语义：蜂蜜是蜜蜂酿在蜂巢里的，不用来带到花上促进结果。", "大树": "体貌：大树体形很大，蜜蜂带不动，句子不合常理。"}, "sentence_index": 6, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天到了，院子里的花粉都开了。", "explanation": "这里应该用〈花朵〉。“开”的对象是花，花粉不会开放。"}, {"text": "妈妈用花粉捏了几个小动物。", "explanation": "这里应该用〈面团〉。捏小动物要用有黏性的面团，花粉是干的粉末，捏不成形。"}, {"text": "桌上摆着一张花粉。", "explanation": "这里应该用〈点〉。“张”用于纸、桌子等平面的东西，花粉要用“点”或“粒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂身上沾了许多黄色地花粉。", "corrected_sentence": "蜜蜂身上沾了许多黄色的花粉。", "error_description": "结构助词错误：修饰名词“花粉”的“黄色”要用“的”，“地”用于修饰动词，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂的腿上沾了一只花粉。", "corrected_sentence": "蜜蜂的腿上沾了一点花粉。", "error_description": "量词错误：花粉是粉末，应用“点”或“粒”计量；“只”多用于动物，不能用来称量花粉，应为“一点花粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
