INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "快要消失了，就像快没了的动物或植物。", "primary_collocate": null, "pronunciation": "bīn wēi", "ipa": "pʰin˥˥ wei˥˥", "syllable_count": 2, "sentences": [{"text": "这种鱼很少了，已经濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "濒危动物需要我们的保护。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看过濒危的金丝猴。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花越来越少，现在很濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了濒危植物的故事。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上有很多濒危的动物。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林变小了，小鸟也濒危了。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护濒危物种，他去了山里。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只濒危的小鸟住在山上。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一张濒危动物的画。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濒危物种", "label": "复合"}, {"form": "濒危植物", "label": "复合"}], "register": "书面", "sense_fingerprint": "动植物快要消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危作谓语，指快要消失，与“很少了”的语境相符。"}, {"text": "充足", "is_correct": false, "explanation": "语义：“充足”指数量多，与“很少了”的语境矛盾。"}, {"text": "繁多", "is_correct": false, "explanation": "语义：“繁多”指数量多，与“很少了”的语境矛盾。"}, {"text": "旺盛", "is_correct": false, "explanation": "搭配：“旺盛”多形容生命力或势头，不用来描述鱼的数量状况。"}], "explanations": {"濒危": "濒危作谓语，指快要消失，与“很少了”的语境相符。", "充足": "语义：“充足”指数量多，与“很少了”的语境矛盾。", "繁多": "语义：“繁多”指数量多，与“很少了”的语境矛盾。", "旺盛": "搭配：“旺盛”多形容生命力或势头，不用来描述鱼的数量状况。"}, "sentence_index": 0, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的队员很濒危，个个都精神饱满。", "explanation": "这里应该用〈健壮〉。队员精神饱满，与“快要消失”相矛盾，应说“健壮”。"}, {"text": "这份工作的压力很濒危。", "explanation": "这里应该用〈沉重〉。濒危指快要消失的动植物或事物，压力不会“消失”，形容压力大应说“沉重”。"}, {"text": "这座城市的人口很濒危，走路都挤。", "explanation": "这里应该用〈密集〉。濒危指快要消失的动植物或事物，人口多不是快要消失，不能说“濒危”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危作谓语，指快要消失，与“树林变小了”的语境相符。"}, {"text": "富足", "is_correct": false, "explanation": "语义：“富足”指物质充裕，不用来描述小鸟的状况，句意不通。"}, {"text": "繁荣", "is_correct": false, "explanation": "语义：“树林变小了，小鸟也……”中的“也”表示同样的遭遇，“繁荣”与之矛盾，句意不通。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指愉快，与“树林变小了”的语境矛盾。"}], "explanations": {"濒危": "濒危作谓语，指快要消失，与“树林变小了”的语境相符。", "富足": "语义：“富足”指物质充裕，不用来描述小鸟的状况，句意不通。", "繁荣": "语义：“树林变小了，小鸟也……”中的“也”表示同样的遭遇，“繁荣”与之矛盾，句意不通。", "欢乐": "语义：“欢乐”指愉快，与“树林变小了”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们画了一个濒危的太阳，天空很亮。", "explanation": "这里应该用〈灿烂〉。太阳快要消失，与“天空很亮”相矛盾，形容太阳明亮应说“灿烂”。"}, {"text": "他的心情很濒危。", "explanation": "这里应该用〈低落〉。濒危指面临灭绝或消亡，不能用来形容心情。"}, {"text": "这所学校的学生很濒危，每年都招满了新生。", "explanation": "这里应该用〈众多〉。招满新生说明人数多，与“快要消失”相矛盾，应说“众多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种树已经濒危着。", "corrected_sentence": "这种树已经濒危了。", "error_description": "错误形式：“濒危着”；正确形式：“濒危了”。“濒危”是形容词，表示快要消失的状态，不能带动态助词“着”，应把“着”改为表示变化的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟被濒危了。", "corrected_sentence": "这种鸟快要濒危了。", "error_description": "错误形式：“被濒危”；正确形式：“快要濒危”。“濒危”是形容词，不能与“被”构成被动式，应把“被”改为“快要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个住的地方，搬到另一个住的地方去。", "primary_collocate": null, "pronunciation": "bān jiā", "ipa": "pan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他上周搬家，现在住在新小区。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥住得太远，下个月想搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王搬家那天，下了很大的雨。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们为了方便上班，打算搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人搬家时都会发现很多旧东西。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚搬家，还不知道超市在哪里。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们搬家时请了三个朋友来帮忙。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人不喜欢搬家，因为他住惯了老房子。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租太贵了，所以他们想搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天搬家，今晚我得把东西装进箱子里。", "target_word": "搬家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了家", "label": "体标：了"}, {"form": "搬过家", "label": "体标：过"}, {"form": "搬个家", "label": "离合：插入量词"}], "register": "中性", "sense_fingerprint": "搬家：从一处住所迁到另一处住所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搬家", "is_correct": true, "explanation": "搬家 bān jiā，从一处住所迁到另一处住所，即本题目标词。"}, {"text": "半价", "is_correct": false, "explanation": "bàn jià 两个音节的声调都与 bān jiā 不同，意思是打折后的价格。"}, {"text": "本家", "is_correct": false, "explanation": "běn（第三声）与 bān（第一声）韵母 en 与 an 不同，声调也不同，意思是同一宗族的人。"}, {"text": "返家", "is_correct": false, "explanation": "fǎn（第三声）与 bān（第一声）声母 f 与 b 不同，声调也不同，意思是回到家里。"}], "explanations": {"搬家": "搬家 bān jiā，从一处住所迁到另一处住所，即本题目标词。", "半价": "bàn jià 两个音节的声调都与 bān jiā 不同，意思是打折后的价格。", "本家": "běn（第三声）与 bān（第一声）韵母 en 与 an 不同，声调也不同，意思是同一宗族的人。", "返家": "fǎn（第三声）与 bān（第一声）声母 f 与 b 不同，声调也不同，意思是回到家里。"}, "sentence_index": null, "correct_answer": "搬家"}, "level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指从一处住所迁到另一处，与“现在住在新小区”相呼应。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”与“现在住在新小区”矛盾，句意不通。"}, {"text": "离世", "is_correct": false, "explanation": "语义：“离世”之后不可能“现在住在新小区”，句意矛盾。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要带搬运的对象，“他上周搬运”不完整。"}], "explanations": {"搬家": "正确：“搬家”指从一处住所迁到另一处，与“现在住在新小区”相呼应。", "出生": "语义：“出生”与“现在住在新小区”矛盾，句意不通。", "离世": "语义：“离世”之后不可能“现在住在新小区”，句意矛盾。", "搬运": "配价：“搬运”需要带搬运的对象，“他上周搬运”不完整。"}, "sentence_index": 0, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天下午搬家去超市买菜。", "explanation": "这里应该用〈去〉。搬家指长期迁居，每天去超市买菜不叫搬家。"}, {"text": "每年寒假，他都搬家回老家过年。", "explanation": "这里应该用〈回家〉。搬家指长期迁居，寒假回老家过年不叫搬家。"}, {"text": "妈妈从客厅搬家到了厨房。", "explanation": "这里不能用“搬家”。搬家指全家迁入另一处住所，同一套房子里换房间不说搬家，要说“搬到厨房”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指全家迁居，与“请了三个朋友来帮忙”的情境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能请朋友来帮忙，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与请朋友来帮忙的情境不符，句意不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与请朋友来帮忙的情境不符，句意不通。"}], "explanations": {"搬家": "正确：“搬家”指全家迁居，与“请了三个朋友来帮忙”的情境相符。", "下雨": "语义：“下雨”是天气现象，不能请朋友来帮忙，句意不通。", "睡觉": "语义：“睡觉”与请朋友来帮忙的情境不符，句意不通。", "迟到": "语义：“迟到”与请朋友来帮忙的情境不符，句意不通。"}, "sentence_index": 6, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱昨天搬家到了厨房。", "explanation": "这里应该用〈搬运〉。搬家的主语必须是人或家庭，冰箱只能被搬运，不能搬家。"}, {"text": "他从这所中学搬家到了另一所中学。", "explanation": "这里应该用〈转学〉。学生换学校要用转学，搬家只指家庭住所的迁移。"}, {"text": "他十六岁时搬家出走，再也没有回来。", "explanation": "这里应该用〈离家出走〉。搬家是迁居，不指离开家庭出走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥明年要搬家在上海。", "corrected_sentence": "我哥哥明年要搬家去上海。", "error_description": "“搬家”后面表示去向时要用“去”或“到”，不能用“在”。错误形式是“搬家在上海”，正确形式是“搬家去上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经搬着两次家了。", "corrected_sentence": "他们已经搬过两次家了。", "error_description": "体标用错：表示经历过某事要用“过”，“着”表示动作持续或状态保持，不能与“两次”这类次数搭配。错误形式是“搬着两次家”，正确形式是“搬过两次家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
