INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在事情开始之前做好该做的事。", "primary_collocate": null, "pronunciation": "tí qián zhǔn bèi", "ipa": "tʰi˧˥ tɕʰjɛn˧˥ ʈʂuən˨˩˦ pei˥˩", "syllable_count": 4, "sentences": [{"text": "明天有客人来，我们要提前准备。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说下周要考试，她已经提前准备了。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门旅行以前，请提前准备好行李。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校提前准备了很多新书给学生。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末要请朋友吃饭，我想提前准备几个菜。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气会变冷，你应该提前准备厚衣服。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演讲在下午，他上午已经提前准备好了。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子下个月上学，妈妈开始提前准备书包。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理让大家提前准备自己的报告。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有提前准备，所以今天很忙。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提前准备了", "label": "体标"}, {"form": "提前准备过", "label": "体标"}, {"form": "提前准备好", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情开始前，先把该做的事做好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提前准备", "is_correct": true, "explanation": "正确：“提前准备”指事前做好该做的事，与“明天有客人来”相呼应。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“明天有客人来，我们要……”的意思矛盾，句意不通。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“客人来”的情境不符，句意不通。"}, {"text": "提醒", "is_correct": false, "explanation": "配价：“提醒”需要带被提醒的对象，“我们要提醒”不完整。"}], "explanations": {"提前准备": "正确：“提前准备”指事前做好该做的事，与“明天有客人来”相呼应。", "忘记": "语义：“忘记”与“明天有客人来，我们要……”的意思矛盾，句意不通。", "逃跑": "语义：“逃跑”与“客人来”的情境不符，句意不通。", "提醒": "配价：“提醒”需要带被提醒的对象，“我们要提醒”不完整。"}, "sentence_index": 0, "correct_answer": "提前准备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位经济学家提前准备了金融危机。", "explanation": "这里应该用〈预见〉。“准备”指做准备工作，不能用来指预先看出未来的事情。"}, {"text": "比赛结束以后，他们才提前准备了战术。", "explanation": "这里应该用〈总结〉。“提前准备”指比赛开始之前做准备，比赛结束后只能总结战术，不能说提前准备。"}, {"text": "我们提前准备了律师。", "explanation": "这里应该用〈预约〉。“准备”指做准备工作，不能用来指事先约定人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提前准备", "is_correct": true, "explanation": "正确：“提前准备”指事前做好准备，与“他上午已经……好了”相呼应。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“已经准备好了”的情况相反，句意不通。"}, {"text": "撕掉", "is_correct": false, "explanation": "配价：“撕掉”需要带宾语，这里单用不完整，且与准备的意思相反。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“失败”不能和“准备好了”搭配，句意不通。"}], "explanations": {"提前准备": "正确：“提前准备”指事前做好准备，与“他上午已经……好了”相呼应。", "放弃": "语义：“放弃”与“已经准备好了”的情况相反，句意不通。", "撕掉": "配价：“撕掉”需要带宾语，这里单用不完整，且与准备的意思相反。", "失败": "语义：“失败”不能和“准备好了”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "提前准备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气象台提前准备了明天的天气。", "explanation": "这里应该用〈预报〉。“准备”指做准备工作，不能用来指事先发布天气情况。"}, {"text": "专家提前准备了地震。", "explanation": "这里应该用〈预防〉。“准备”不能用于自然灾害本身，预先防范地震要用预防。"}, {"text": "考试时间被提前准备了一周。", "explanation": "这里应该用〈调整〉。“提前准备”指做准备工作，不能用于时间本身；考试时间的变动要说“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今晚要把提前准备饭菜。", "corrected_sentence": "我们今晚要提前准备饭菜。", "error_description": "“把”字不能插在“提前准备”前面。“把”字句要求“把+宾语+动词”，这里结构不成立，应去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演讲在下午，他上午要提前准备过稿子。", "corrected_sentence": "演讲在下午，他上午要提前准备好稿子。", "error_description": "错误形式：“提前准备过稿子”。正确形式：“提前准备好稿子”。“过”表示曾经有过的经历，与表示将来的“要”不搭配；这里应用结果补语“好”，表示准备完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "正确：“有”与“没有”构成反义关系，表示拥有。"}, {"text": "拿", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“拿”指用手取物。"}, {"text": "送", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“送”指赠予。"}, {"text": "写", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“写”指书写。"}], "correct_answer": "有", "explanations": {"有": "正确：“有”与“没有”构成反义关系，表示拥有。", "拿": "与“没有”无反义或近义关系：“拿”指用手取物。", "送": "与“没有”无反义或近义关系：“送”指赠予。", "写": "与“没有”无反义或近义关系：“写”指书写。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "正确：“有”与“没有”构成反义关系，表示拥有。"}, {"text": "借", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“借”指借入。"}, {"text": "卖", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“卖”指出售。"}, {"text": "找", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“找”指寻求。"}], "correct_answer": "有", "explanations": {"有": "正确：“有”与“没有”构成反义关系，表示拥有。", "借": "与“没有”无反义或近义关系：“借”指借入。", "卖": "与“没有”无反义或近义关系：“卖”指出售。", "找": "与“没有”无反义或近义关系：“找”指寻求。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示某人不拥有某物，或不具有某种东西。", "primary_collocate": null, "pronunciation": "méi yǒu", "ipa": "mei˧˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我没有玩具。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没有手机。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟没有姐姐。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天没有时间。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个教室没有空调。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有钱买新车。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有铅笔，你有吗？", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家没有小狗。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这里没有朋友。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们没有票，不能进去。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沒有", "label": "繁体"}, {"form": "没", "label": "省略形式"}, {"form": "有没有", "label": "正反问"}], "register": "口语", "sense_fingerprint": "没有：某人不拥有某物，或不具有某种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有”表示不拥有，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃玩具。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只接衣物，不能说穿玩具。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能说喝玩具。"}], "explanations": {"没有": "正确：“没有”表示不拥有，与句意一致。", "吃": "语义：“吃”的对象是食物，不能说吃玩具。", "穿": "搭配：“穿”只接衣物，不能说穿玩具。", "喝": "语义：“喝”的对象是饮品，不能说喝玩具。"}, "sentence_index": 0, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有我高，但他跑得比我快。", "explanation": "这里的“没有”表示“不如”，用于比较，是另一个意思，不表示不拥有。"}, {"text": "我昨天没有去学校，因为生病了。", "explanation": "这里的“没有”表示动作未发生，用于过去，是另一个意思，不表示不拥有。"}, {"text": "电影还没有开始，我们再等一会儿。", "explanation": "这里的“没有”表示“尚未”，是另一个意思，不表示不拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有”与后句“你有吗”相对，表示不拥有。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”只接帽子、眼镜等，不能说戴铅笔。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能说煮铅笔。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲，不能说唱铅笔。"}], "explanations": {"没有": "正确：“没有”与后句“你有吗”相对，表示不拥有。", "戴": "搭配：“戴”只接帽子、眼镜等，不能说戴铅笔。", "煮": "语义：“煮”的对象是食物，不能说煮铅笔。", "唱": "搭配：“唱”接歌曲，不能说唱铅笔。"}, "sentence_index": 6, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服没有那么贵，我们可以买。", "explanation": "这里的“没有”表示“不太”，用于程度比较，是另一个意思，不表示不拥有。"}, {"text": "我一次都没有迟到，老师很表扬我。", "explanation": "这里的“没有”表示“从未”，是另一个意思，不表示不拥有。"}, {"text": "我们没有必要着急，慢慢走吧。", "explanation": "这里的“没有必要”表示“不必”，是另一个意思，不表示不拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家里不没有电脑。", "corrected_sentence": "我家里没有电脑。", "error_description": "错误：“不没有”。正确：“没有”。表示领有的否定只用“没有”或“没”，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家里没有有车。", "corrected_sentence": "他家里没有车。", "error_description": "错误：“没有有车”。正确：“没有车”。“没有”是一个整体，后面直接接宾语，不能重复“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
