INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27830, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人可以做某事。", "primary_collocate": null, "pronunciation": "shòu quán", "ipa": "ʂoʊ̯˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈授权我管家里的钱。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师授权班长收作业。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我授权你替我签收快递。", "target_word": "授权", "complexity_tier": "T3", "furigana": "wǒ shòu quán nǐ tì wǒ qiān shōu kuài dì", "sentence_source": "generated"}, {"text": "爸爸授权哥哥使用他的会员账号。", "target_word": "授权", "complexity_tier": "T3", "furigana": "bà ba shòu quán gē ge shǐ yòng tā de huì yuán zhàng hào", "sentence_source": "generated"}, {"text": "经理授权小王决定这件事。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你授权我用你的账号。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他授权朋友替他开会。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经授权同事访问我的电脑。", "target_word": "授权", "complexity_tier": "T3", "furigana": "wǒ yǐ jīng shòu quán tóng shì fǎng wèn wǒ de diàn nǎo", "sentence_source": "generated"}, {"text": "奶奶授权孙子替她办理医保手续。", "target_word": "授权", "complexity_tier": "T3", "furigana": "nǎi nai shòu quán sūn zi tì tā bàn lǐ yī bǎo shǒu xù", "sentence_source": "generated"}, {"text": "老板没有授权我们改价格。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授权了", "label": "体标"}, {"form": "授权过", "label": "体标"}, {"form": "授权书", "label": "复合"}, {"form": "授權", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中允许别人替自己做某事或使用某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。授权（shòu quán）指让别人可以做某事。"}, {"text": "售券", "is_correct": false, "explanation": "quàn（第四声）与 quán（第二声）声调不同，售券意思是卖票。"}, {"text": "收权", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收权意思是收回权力。"}, {"text": "收拳", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收拳意思是收起拳头。"}], "explanations": {"授权": "正确。授权（shòu quán）指让别人可以做某事。", "售券": "quàn（第四声）与 quán（第二声）声调不同，售券意思是卖票。", "收权": "shōu（第一声）与 shòu（第四声）声调不同，收权意思是收回权力。", "收拳": "shōu（第一声）与 shòu（第四声）声调不同，收拳意思是收起拳头。"}, "sentence_index": null, "correct_answer": "授权"}, "level_3": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。「妈妈授权我管家里的钱」指妈妈允许我管钱，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能表示允许对方做某事，「吃我管家里的钱」无法成立。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：「拥抱」不能带出「我管钱」这样的兼语结构。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清理，与「管钱」不相关，句子意思不通。"}], "explanations": {"授权": "正确。「妈妈授权我管家里的钱」指妈妈允许我管钱，符合语境。", "吃": "语义：「吃」不能表示允许对方做某事，「吃我管家里的钱」无法成立。", "拥抱": "搭配：「拥抱」不能带出「我管钱」这样的兼语结构。", "打扫": "语义：「打扫」指清理，与「管钱」不相关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "授权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他授权了错误。", "explanation": "这里应该用〈承认〉。授权是允许别人做某事，不能用于错误。"}, {"text": "我授权你的帮助。", "explanation": "这里应该用〈感谢〉。授权是让别人做某事，不用来表达对帮助的谢意。"}, {"text": "他授权一辆车。", "explanation": "这里应该用〈拥有〉。授权指允许别人做某事，不表示自己有某物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。「他授权朋友替他开会」指他允许朋友代替自己开会，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」不能表示允许别人代替自己，「他唱朋友替他开会」不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」与「替他开会」的动作无关，句子意思不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：「咬」不能与「替他开会」搭配，无法表示代替别人做事。"}], "explanations": {"授权": "正确。「他授权朋友替他开会」指他允许朋友代替自己开会，符合语境。", "唱": "语义：「唱」不能表示允许别人代替自己，「他唱朋友替他开会」不成立。", "睡": "语义：「睡」与「替他开会」的动作无关，句子意思不通。", "咬": "搭配：「咬」不能与「替他开会」搭配，无法表示代替别人做事。"}, "sentence_index": 6, "correct_answer": "授权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人授权了任务。", "explanation": "这里应该用〈完成〉。授权是允许别人做某事，任务应该被完成，不能被授权。"}, {"text": "大家授权新同学。", "explanation": "这里应该用〈欢迎〉。授权指允许别人做某事，不用来表示对新同学的接纳。"}, {"text": "他授权失去的钥匙。", "explanation": "这里应该用〈寻找〉。授权是允许他人做某事，不能用来表示找回失物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的授权我用她的银行卡。", "corrected_sentence": "妈妈授权我用她的银行卡。", "error_description": "错误：加“的”后“授权”变成名词，句中缺少谓语动词；应直接用动词“授权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板下周授权了我签字。", "corrected_sentence": "老板下周授权我签字。", "error_description": "错误：“下周”指将来，动作尚未发生，不能用“了”，应为“老板下周授权我签字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
