INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人叫你的那个词。", "primary_collocate": null, "pronunciation": "míng zi", "ipa": "miŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "你叫什么名字？", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的名字是小明。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师记住了我的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的名字很好听。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请在这里写上你的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他的名字。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给我起了这个名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一叫我的名字，我就回头了。", "target_word": "名字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子还没有名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能告诉我你朋友的名字吗？", "target_word": "名字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个名字", "label": "量词"}], "register": "中性", "sense_fingerprint": "别人称呼你的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4177ca5c-ed1d-4b04-aa07-385752d02c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名字", "is_correct": true, "explanation": "名字 míng zi，指别人叫你的那个词，是正确答案。"}, {"text": "名次", "is_correct": false, "explanation": "名次 míng cì 与 míng zi 的第二音节声母不同（c 与 z），声调也不同（第四声与轻声），意思是排列的位次。"}, {"text": "名词", "is_correct": false, "explanation": "名词 míng cí 与 míng zi 的第二音节声母不同（c 与 z），声调也不同（第二声与轻声），意思是语法上的词类。"}, {"text": "明智", "is_correct": false, "explanation": "明智 míng zhì 与 míng zi 的第二音节声母不同（zh 与 z），声调也不同，意思是聪明、有见识。"}], "explanations": {"名字": "名字 míng zi，指别人叫你的那个词，是正确答案。", "名次": "名次 míng cì 与 míng zi 的第二音节声母不同（c 与 z），声调也不同（第四声与轻声），意思是排列的位次。", "名词": "名词 míng cí 与 míng zi 的第二音节声母不同（c 与 z），声调也不同（第二声与轻声），意思是语法上的词类。", "明智": "明智 míng zhì 与 míng zi 的第二音节声母不同（zh 与 z），声调也不同，意思是聪明、有见识。"}, "sentence_index": null, "correct_answer": "名字"}, "level_3": {"options": [{"text": "名字", "is_correct": true, "explanation": "名字：指人的称呼，与“叫什么”搭配，是正确答案。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历不是人的称呼，不能用“叫什么”来问。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“叫什么”后只能接名称，不能接体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是数字，不是称呼，不能用“叫”来问。"}], "explanations": {"名字": "名字：指人的称呼，与“叫什么”搭配，是正确答案。", "学历": "语义：学历不是人的称呼，不能用“叫什么”来问。", "体重": "搭配：“叫什么”后只能接名称，不能接体重。", "年龄": "语义：年龄是数字，不是称呼，不能用“叫”来问。"}, "sentence_index": 0, "correct_answer": "名字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试排在班里的名字很靠前，大家都很佩服。", "explanation": "这里应该用〈名次〉。名字指称呼，表示排名要说名次，“名字很靠前”不成立。"}, {"text": "他把名字递给我，上面印着公司电话。", "explanation": "这里应该用〈名片〉。递给别人、上面印有电话的是名片，名字只是称呼，不能这样递送。"}, {"text": "这位明星的名字非常大，走到哪里都有人认出来。", "explanation": "这里应该用〈名气〉。名字指称呼，说一个人有名气要用“名气很大”，“名字很大”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": true, "explanation": "名字：指给孩子起的称呼，与“起了这个”搭配，是正确答案。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“起”不能接身高，身高不是可以起的称呼。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不是可以起的称呼。"}, {"text": "分数", "is_correct": false, "explanation": "语义：分数是考核的结果，不能用“起”来命名。"}], "explanations": {"名字": "名字：指给孩子起的称呼，与“起了这个”搭配，是正确答案。", "身高": "搭配：“起”不能接身高，身高不是可以起的称呼。", "工资": "语义：工资是报酬，不是可以起的称呼。", "分数": "语义：分数是考核的结果，不能用“起”来命名。"}, "sentence_index": 6, "correct_answer": "名字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校授予他“三好学生”的名字。", "explanation": "这里应该用〈称号〉。授予的是称号，名字是人的本名，不能被授予。"}, {"text": "她荣获了“年度人物”的名字。", "explanation": "这里应该用〈头衔〉。荣获的是头衔，名字是称呼，不能说荣获名字。"}, {"text": "学校只分给我们班一个名字，我们都很想去。", "explanation": "这里应该用〈名额〉。学校分配的是名额，名字不能分配，这里应该说“一个名额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一块很好听的名字。", "corrected_sentence": "她有一个很好听的名字。", "error_description": "量词错误：名字的量词应为“个”，“块”用于片状的东西，不能用于名字。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶给我起了着一个好名字。", "corrected_sentence": "奶奶给我起了一个好名字。", "error_description": "体标错误：“了”与“着”不能同时用在同一动词后；“起了着”应去掉“着”，写作“起了一个好名字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
