INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "熊是一种大动物，有毛，会爬树。", "primary_collocate": null, "pronunciation": "xióng", "ipa": "ɕjʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "动物园里的熊正在吃苹果。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊冬天会在山洞里睡很久，醒来就找蜂蜜吃。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只熊爬上树，想找蜂蜜吃。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头熊很大，站起来比爸爸还高。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊的毛又黑又厚，冬天一点儿也不冷。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊喜欢吃蜂蜜，也喜欢吃鱼。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在山上看见了一头熊，吓了一跳。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊用大手抓住河里的鱼。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在笼子外面看熊。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到熊走过来，我们马上跑了。", "target_word": "熊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一头熊", "label": "量词"}, {"form": "黑熊", "label": "复合"}, {"form": "北极熊", "label": "复合"}], "register": "口语", "sense_fingerprint": "熊：身体很大、有毛、会爬树的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cff4beb-2454-4408-ae79-6e87aa30b10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊（第二声）是本词，指一种大型动物。"}, {"text": "兄", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“哥哥”。"}, {"text": "胸", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“胸口”。"}, {"text": "凶", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“凶猛”。"}, {"text": "穷", "is_correct": false, "explanation": "qióng（第二声）与 xióng（第二声）声母不同（q 与 x），意思是“贫穷”。"}], "explanations": {"熊": "熊（第二声）是本词，指一种大型动物。", "兄": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“哥哥”。", "胸": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“胸口”。", "凶": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“凶猛”。", "穷": "qióng（第二声）与 xióng（第二声）声母不同（q 与 x），意思是“贫穷”。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊：本词，指动物，符合“动物园里”和“吃苹果”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是动物，不会吃苹果。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是动物，不能进食。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“吃”的主语必须是能进食的生命体，房子不能充当。"}], "explanations": {"熊": "熊：本词，指动物，符合“动物园里”和“吃苹果”的语境。", "桌子": "语义：桌子不是动物，不会吃苹果。", "汽车": "语义：汽车不是动物，不能进食。", "房子": "配价：“吃”的主语必须是能进食的生命体，房子不能充当。"}, "sentence_index": 0, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这头熊长着长长的耳朵，每天吃胡萝卜。", "explanation": "此处的“熊”指向兔子，错误。“熊”不能指兔子，描述的是兔子，应说“兔子”。"}, {"text": "这头熊会汪汪叫，见了陌生人就摇尾巴。", "explanation": "此处的“熊”指向狗，错误。“熊”不能指狗，描述的是狗，应说“狗”。"}, {"text": "这头熊有翅膀，在天上飞来飞去。", "explanation": "此处的“熊”指向鸟，错误。“熊”不能指鸟，描述的是鸟，应说“鸟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊（第二声）是本词，指一种大型动物。"}, {"text": "汹", "is_correct": false, "explanation": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“汹涌”。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“形状”。"}, {"text": "刑", "is_correct": false, "explanation": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“刑罚”。"}], "explanations": {"熊": "熊（第二声）是本词，指一种大型动物。", "汹": "xiōng（第一声）与 xióng（第二声）声调不同，意思是“汹涌”。", "形": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“形状”。", "刑": "xíng（第二声）与 xióng（第二声）韵母不同（ing 与 ong），意思是“刑罚”。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊：本词，指动物，符合“看见一头…吓了一跳”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "量词：“头”主要用于牛、熊等大型动物，石头应说“一块”，“一头石头”不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“一头”不搭配窗户，量词不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一头”不搭配冰箱，量词不符。"}], "explanations": {"熊": "熊：本词，指动物，符合“看见一头…吓了一跳”的语境。", "石头": "量词：“头”主要用于牛、熊等大型动物，石头应说“一块”，“一头石头”不成立。", "窗户": "搭配：“一头”不搭配窗户，量词不符。", "冰箱": "搭配：“一头”不搭配冰箱，量词不符。"}, "sentence_index": 6, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这头熊喜欢在窗台上晒太阳，还会喵喵叫。", "explanation": "此处的“熊”指向猫，错误。“熊”不能指猫，描述的是猫，应说“猫”。"}, {"text": "农民把这头熊赶进猪圈，给它喂食。", "explanation": "此处的“熊”指向猪，错误。“熊”不能指猪，应说“猪”。"}, {"text": "这头熊在院子里下蛋，每天早上叫醒大家。", "explanation": "此处的“熊”指向鸡，错误。“熊”不能指鸡，描述的是鸡，应说“鸡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条熊在河边抓鱼。", "corrected_sentence": "一头熊在河边抓鱼。", "error_description": "量词错误：熊是大型动物，应说“一头熊”，“条”用于狗、蛇、鱼等，不能用于熊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在动物园把熊看。", "corrected_sentence": "孩子们在动物园看熊。", "error_description": "“把”字句不完整：“把熊看”后面缺少补语或其他成分，应去掉“把”，说“孩子们在动物园看熊。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": true, "explanation": "硬：与“软”相对，指摸上去不柔软，构成触感上的反义。"}, {"text": "甜", "is_correct": false, "explanation": "甜指味道，与“软”没有对立关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与“软”不构成反义。"}, {"text": "暖", "is_correct": false, "explanation": "暖指温度，与“软”不构成反义。"}], "correct_answer": "硬", "explanations": {"硬": "硬：与“软”相对，指摸上去不柔软，构成触感上的反义。", "甜": "甜指味道，与“软”没有对立关系。", "亮": "亮指光线，与“软”不构成反义。", "暖": "暖指温度，与“软”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": true, "explanation": "硬：与“软”相对，指摸上去不柔软，构成触感上的反义。"}, {"text": "凉", "is_correct": false, "explanation": "凉指温度，与“软”没有对立关系。"}, {"text": "长", "is_correct": false, "explanation": "长指长度，与“软”不构成反义。"}, {"text": "高", "is_correct": false, "explanation": "高指高度，与“软”不构成反义。"}], "correct_answer": "硬", "explanations": {"硬": "硬：与“软”相对，指摸上去不柔软，构成触感上的反义。", "凉": "凉指温度，与“软”没有对立关系。", "长": "长指长度，与“软”不构成反义。", "高": "高指高度，与“软”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "摸起来不像石头那么硬，像棉花一样。", "primary_collocate": null, "pronunciation": "ruǎn", "ipa": "ʐwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个枕头很软，睡起来真舒服。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫的毛很软，摸起来像棉花。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的沙发又大又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "刚出炉的面包又香又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条毛巾很软，擦脸一点儿也不疼。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿的小手又小又软。", "target_word": "软", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "床太软，睡久了腰会不舒服。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她摸了摸被子，说：“真软，像云一样。”", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋底很软，走路时脚不累。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我喜欢盖软一点儿的被子。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "软软", "label": "重叠"}, {"form": "柔软", "label": "复合"}, {"form": "軟", "label": "繁体"}], "register": "通用", "sense_fingerprint": "软：触感柔软，不硬，像棉花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。"}, {"text": "染", "is_correct": false, "explanation": "rǎn 与 ruǎn 少了介音 u，意思是染色。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "暖": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。", "染": "rǎn 与 ruǎn 少了介音 u，意思是染色。", "卵": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：触感柔软，与“睡起来真舒服”相合。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容易碎或口感，不能用来形容枕头的软硬。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与枕头的触感无关。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线，与枕头的舒适感不相合。"}], "explanations": {"软": "软：触感柔软，与“睡起来真舒服”相合。", "脆": "搭配：“脆”形容易碎或口感，不能用来形容枕头的软硬。", "甜": "语义：“甜”指味道，与枕头的触感无关。", "亮": "语义：“亮”指光线，与枕头的舒适感不相合。"}, "sentence_index": 0, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种红色很软，看着很温柔。", "explanation": "这里误用了〈软〉。“软”形容触感，不能用来形容颜色；这里应该用〈柔和〉。"}, {"text": "这盏台灯很软，照得屋子很亮。", "explanation": "这里误用了〈软〉。“软”形容触感，台灯不能这样形容；这里应该用〈明亮〉。"}, {"text": "这个数字很软，我总是记不住。", "explanation": "这里误用了〈软〉。“软”形容触感，数字没有触感；这里应该用〈好记〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "短": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。", "缓": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。", "碗": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：触感柔软，床太软会让腰受力，与“睡久了腰会不舒服”相合。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，与床的软硬及腰的感受无关。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”指价格高，与“睡久了腰会不舒服”没有关系。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”形容形状，“床太圆”不成立，也无法解释腰的不适。"}], "explanations": {"软": "软：触感柔软，床太软会让腰受力，与“睡久了腰会不舒服”相合。", "白": "语义：“白”指颜色，与床的软硬及腰的感受无关。", "贵": "语义：“贵”指价格高，与“睡久了腰会不舒服”没有关系。", "圆": "搭配：“圆”形容形状，“床太圆”不成立，也无法解释腰的不适。"}, "sentence_index": 6, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玻璃杯很软，轻轻一碰就碎了。", "explanation": "这里误用了〈软〉。“软”形容触感柔软，玻璃杯一碰就碎应说〈脆〉。"}, {"text": "这碗汤很软，喝下去很烫。", "explanation": "这里误用了〈软〉。“软”形容触感，不能形容汤的温度；这里应该用〈烫〉。"}, {"text": "这间屋子很软，只有五平方米。", "explanation": "这里误用了〈软〉。“软”形容触感，不能形容房间的大小；这里应该用〈小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块海绵踩上去软很，像棉花一样。", "corrected_sentence": "这块海绵踩上去很软，像棉花一样。", "error_description": "“很”应放在形容词前面，说“很软”，不能说“软很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面团揉了一会儿，慢慢软出来了。", "corrected_sentence": "面团揉了一会儿，慢慢软下来了。", "error_description": "“软”后应接趋向补语“下来”，表示变软的过程；“软出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": true, "explanation": "硬：与“软”相对，指物体内部紧实、不易变形，构成反义。"}, {"text": "深", "is_correct": false, "explanation": "深指深度，与“软”不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与“软”没有对立关系。"}, {"text": "圆", "is_correct": false, "explanation": "圆指形状，与“软”不构成反义。"}], "correct_answer": "硬", "explanations": {"硬": "硬：与“软”相对，指物体内部紧实、不易变形，构成反义。", "深": "深指深度，与“软”不构成反义。", "亮": "亮指光线，与“软”没有对立关系。", "圆": "圆指形状，与“软”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": true, "explanation": "硬：与“软”相对，指物体内部紧实、不易变形，构成反义。"}, {"text": "矮", "is_correct": false, "explanation": "矮指高度，与“软”不构成反义。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与“软”没有对立关系。"}, {"text": "直", "is_correct": false, "explanation": "直指形状，与“软”不构成反义。"}], "correct_answer": "硬", "explanations": {"硬": "硬：与“软”相对，指物体内部紧实、不易变形，构成反义。", "矮": "矮指高度，与“软”不构成反义。", "轻": "轻指重量，与“软”没有对立关系。", "直": "直指形状，与“软”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体内部组织疏松，受力后容易改变形状。", "primary_collocate": null, "pronunciation": "ruǎn", "ipa": "ʐwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "铅是一种很软的金属，用力就能弯。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨，地很软，一踩就是一个坑。", "target_word": "软", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头太软，钉子一敲就进去了。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桃子熟透了，一捏就软。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团发好后很软，一压就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土豆煮得很软，用勺子一压就碎了。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料很软，一捏就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新雪很软，踩下去会陷进去。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蜡很软，用手一捏就变形。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软的黏土可以随便捏成各种形状。", "target_word": "软", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "软软", "label": "重叠"}, {"form": "变软", "label": "复合"}, {"form": "軟", "label": "繁体"}], "register": "通用", "sense_fingerprint": "软：物体内部疏松，一受力就变形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "短": "duǎn 与 ruǎn 声母不同（d 与 r），意思是短。", "缓": "huǎn 与 ruǎn 声母不同（h 与 r），意思是缓慢。", "碗": "wǎn 与 ruǎn 只差开头的 r 音，意思是碗。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：内部疏松、用力就能弯，与“铅”的性质相合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，金属不能用味道来形容。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与金属的硬度、可弯曲性无关。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”指易断，与“用力就能弯”的性质矛盾。"}], "explanations": {"软": "软：内部疏松、用力就能弯，与“铅”的性质相合。", "甜": "语义：“甜”指味道，金属不能用味道来形容。", "咸": "语义：“咸”指味道，与金属的硬度、可弯曲性无关。", "脆": "搭配：“脆”指易断，与“用力就能弯”的性质矛盾。"}, "sentence_index": 0, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资很软，一下子就花光了。", "explanation": "这里误用了〈软〉。“软”形容物体内部疏松、易变形，工资不能这样形容；这里应该用〈少〉。"}, {"text": "这把锁很软，怎么也打不开。", "explanation": "这里误用了〈软〉。锁是金属构件，不能说“软”；这里应该用〈牢〉。"}, {"text": "这个房间很软，只有十平方米。", "explanation": "这里误用了〈软〉。“软”形容物体内部疏松、受力易变形，房间的大小不能用“软”来说；这里应该用〈小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "软", "is_correct": true, "explanation": "软（ruǎn）即正确答案。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。"}, {"text": "染", "is_correct": false, "explanation": "rǎn 与 ruǎn 少了介音 u，意思是染色。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}], "explanations": {"软": "软（ruǎn）即正确答案。", "暖": "nuǎn 与 ruǎn 声母不同（n 与 r），意思是温暖。", "染": "rǎn 与 ruǎn 少了介音 u，意思是染色。", "卵": "luǎn 与 ruǎn 声母不同（l 与 r），意思是卵，即蛋。"}, "sentence_index": null, "correct_answer": "软"}, "level_3": {"options": [{"text": "软", "is_correct": true, "explanation": "软：物体受力后容易变形，与“一捏就变形”相合。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，与塑料的形变无关。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”指味道，不能用来形容塑料的软硬。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，“香的塑料”不成立，也与“一捏就变形”无关。"}], "explanations": {"软": "软：物体受力后容易变形，与“一捏就变形”相合。", "苦": "语义：“苦”指味道，与塑料的形变无关。", "辣": "语义：“辣”指味道，不能用来形容塑料的软硬。", "香": "搭配：“香”形容气味，“香的塑料”不成立，也与“一捏就变形”无关。"}, "sentence_index": 6, "correct_answer": "软"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校离我家很软，走路要半个小时。", "explanation": "这里误用了〈软〉。“软”形容触感，不能形容距离；这里应该用〈远〉。"}, {"text": "这个假期很软，一下子就过去了。", "explanation": "这里误用了〈软〉。假期的长短不能用“软”来形容；这里应该用〈短〉。"}, {"text": "这箱书很软，我一个人搬不动。", "explanation": "这里误用了〈软〉。“软”形容触感或内部疏松，不能用来形容箱子的重量；这里应该用〈重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块年糕蒸好后软很，一咬就散。", "corrected_sentence": "这块年糕蒸好后很软，一咬就散。", "error_description": "“很”应放在形容词前面，说“很软”，不能说“软很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气一热，黄油就软出来了。", "corrected_sentence": "天气一热，黄油就软下来了。", "error_description": "“软”后应接趋向补语“下来”，表示变软的过程；“软出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
