INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容天气晴朗，阳光充足，让人感到温暖和愉快。", "primary_collocate": null, "pronunciation": "yáng guāng míng mèi", "ipa": "jɑŋ˧˥ kwɑŋ˥ miŋ˧˥ meɪ˥˩", "syllable_count": 4, "sentences": [{"text": "天气预报说明天阳光明媚，很适合爬山。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三月的北京阳光明媚，不冷也不热。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天阳光明媚，温暖的风吹在脸上。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期的第一天阳光明媚，我们决定去骑车。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年秋天一直阳光明媚，我们过得很愉快。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚那天阳光明媚，大家都很高兴。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光明媚的周末，公园里有很多人晒太阳。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的冬天也常常阳光明媚，一点儿都不冷。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光明媚的日子里，奶奶喜欢在阳台上看书。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然昨天下雨，今天却阳光明媚，真让人开心。", "target_word": "阳光明媚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天气晴朗，阳光充足，温暖愉快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凄惨", "is_correct": false, "explanation": "语义：“凄惨”形容悲惨的景象，与适合爬山的好天气矛盾。"}, {"text": "阳光明媚", "is_correct": true, "explanation": "正确：“阳光明媚”形容天气晴朗，与“很适合爬山”相符。"}, {"text": "呆板", "is_correct": false, "explanation": "搭配：“呆板”不能用来形容天气。"}, {"text": "萧条", "is_correct": false, "explanation": "语义：“萧条”形容冷清衰败，与适合爬山的天气不合。"}], "explanations": {"凄惨": "语义：“凄惨”形容悲惨的景象，与适合爬山的好天气矛盾。", "阳光明媚": "正确：“阳光明媚”形容天气晴朗，与“很适合爬山”相符。", "呆板": "搭配：“呆板”不能用来形容天气。", "萧条": "语义：“萧条”形容冷清衰败，与适合爬山的天气不合。"}, "sentence_index": 0, "correct_answer": "阳光明媚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋房子阳光明媚，要重新装修。", "explanation": "这里应该用〈陈旧〉。“阳光明媚”不能用来形容房子，房子老旧要用“陈旧”。"}, {"text": "鸟儿的叫声阳光明媚，很好听。", "explanation": "这里应该用〈清脆〉。“阳光明媚”只形容天气或景色，声音响亮悦耳要用“清脆”。"}, {"text": "这块石头摸起来阳光明媚。", "explanation": "这里应该用〈光滑〉。“阳光明媚”不能用来形容触感，表面平滑要用“光滑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体沉，不能用来形容周末。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指人少，与“公园里有很多人晒太阳”矛盾。"}, {"text": "阳光明媚", "is_correct": true, "explanation": "正确：“阳光明媚”形容天气晴朗，与人们在公园晒太阳相符。"}, {"text": "寒冷刺骨", "is_correct": false, "explanation": "语义：“寒冷刺骨”形容极冷的天气，与人们晒太阳的情景矛盾。"}], "explanations": {"笨重": "搭配：“笨重”形容物体沉，不能用来形容周末。", "冷清": "语义：“冷清”指人少，与“公园里有很多人晒太阳”矛盾。", "阳光明媚": "正确：“阳光明媚”形容天气晴朗，与人们在公园晒太阳相符。", "寒冷刺骨": "语义：“寒冷刺骨”形容极冷的天气，与人们晒太阳的情景矛盾。"}, "sentence_index": 6, "correct_answer": "阳光明媚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件手工艺品阳光明媚，摆在桌上很漂亮。", "explanation": "这里应该用〈精致〉。“阳光明媚”只形容天气或景色，工艺品做得细致要用“精致”。"}, {"text": "这碗汤阳光明媚，我再加点水吧。", "explanation": "这里应该用〈咸〉。“阳光明媚”不能用来形容味道，味道太重要用“咸”。"}, {"text": "字写得阳光明媚，老师看了很满意。", "explanation": "这里应该用〈工整〉。“阳光明媚”不能用来形容字迹，字写得整齐要用“工整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光明媚早上，适合去散步。", "corrected_sentence": "阳光明媚的早上，适合去散步。", "error_description": "“阳光明媚”修饰名词“早上”时应加“的”，应说“阳光明媚的早上”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳光明媚地午后，我们在湖边散步。", "corrected_sentence": "阳光明媚的午后，我们在湖边散步。", "error_description": "“阳光明媚”修饰名词“午后”时应用“的”，不能用“地”；“地”用在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
