INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房间就是屋子，人们可以在里面睡觉、玩。", "primary_collocate": null, "pronunciation": "fáng jiān", "ipa": "faŋ˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我的房间在二楼。", "target_word": "房间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间很大，也很干净。", "target_word": "房间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子在房间里写作业。", "target_word": "房间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你把房间打扫一下。", "target_word": "房间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的房间有一张大床。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他关上门，一个人在房间里哭。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们订了两个房间，一共住三天。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间太小了，放不下这张桌子。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的房间里有很多玩具。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走进房间，开了灯。", "target_word": "房间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "房間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房子或酒店里用墙隔开、供人睡觉生活的一间屋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房间", "is_correct": true, "explanation": "“房间”：房屋中隔开的一间屋子，可以位于二楼。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，没有楼层位置，句子不成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体器官，不能说位于二楼。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：“心脏”是器官，不能说位于二楼。"}], "explanations": {"房间": "“房间”：房屋中隔开的一间屋子，可以位于二楼。", "名字": "语义：“名字”是称呼，没有楼层位置，句子不成立。", "眼睛": "体貌：“眼睛”是身体器官，不能说位于二楼。", "心脏": "语义：“心脏”是器官，不能说位于二楼。"}, "sentence_index": 0, "correct_answer": "房间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间有三层楼。", "explanation": "这里应该用〈房子〉。“房间”指屋子里隔开的一间，没有几层楼，整座建筑才用“房子”。"}, {"text": "这间房间有两部电梯。", "explanation": "这里应该用〈大楼〉。“房间”只是一间屋子，没有电梯，整栋建筑才用“大楼”。"}, {"text": "这间房间有一个大花园。", "explanation": "这里应该用〈别墅〉。“房间”是屋内的一间，没有花园，带花园的整栋住宅要用“别墅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房间", "is_correct": true, "explanation": "“房间”：可以预订并住宿的房间，与“订”和“住三天”相符。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是时间段，不能预订或用来住宿。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“订”不能用于行李，行李不能预订。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能被预订，与“订”不搭配。"}], "explanations": {"房间": "“房间”：可以预订并住宿的房间，与“订”和“住三天”相符。", "学期": "语义：“学期”是时间段，不能预订或用来住宿。", "行李": "搭配：“订”不能用于行李，行李不能预订。", "作业": "搭配：“作业”不能被预订，与“订”不搭配。"}, "sentence_index": 6, "correct_answer": "房间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房间的物业很负责。", "explanation": "这里应该用〈小区〉。“房间”是屋内的一间，没有物业管理，整个小区才有物业。"}, {"text": "这间房间的门票很贵。", "explanation": "这里应该用〈景点〉。“房间”不收门票，景点、展馆的门票要用“景点”。"}, {"text": "这间房间每天营业到晚上十点。", "explanation": "这里应该用〈超市〉。“房间”不营业，营业时间用于商店、超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把房间很亮。", "corrected_sentence": "这间房间很亮。", "error_description": "量词错误：“房间”的量词是“间”，不能用“把”（“把”用于有柄或可握持的东西）。应改为“这间房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在三楼订了两座房间。", "corrected_sentence": "我们在三楼订了两间房间。", "error_description": "量词错误：“房间”的量词是“间”，不能用“座”（“座”用于山、桥、大型建筑等）。应改为“两间房间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
