INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叔叔是爸爸的弟弟，或者像爸爸一样大的男人。", "primary_collocate": null, "pronunciation": "shū shu", "ipa": "ʂu˥ ʂu", "syllable_count": 2, "sentences": [{"text": "我叔叔是爸爸的弟弟。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔每个周末都来我家。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子，快叫叔叔好！", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的叔叔在医院工作。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔给我买了一个新书包。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个叔叔帮我找到了妈妈。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔比爸爸小三岁。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一位叔叔在问路。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔住在北京，我很少见到他。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔开车送我去学校。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "爸爸的弟弟；与爸爸年纪相近的男性长辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哥哥", "is_correct": false, "explanation": "语义：哥哥不能是父亲的弟弟，这一句的关系说不通。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不是人，不能是父亲的弟弟。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不能作亲属称谓，与“爸爸的弟弟”无法搭配。"}, {"text": "叔叔", "is_correct": true, "explanation": "叔叔：父亲的弟弟，或与父亲年纪相近的男性长辈。"}], "explanations": {"哥哥": "语义：哥哥不能是父亲的弟弟，这一句的关系说不通。", "猫": "语义：猫不是人，不能是父亲的弟弟。", "桌子": "搭配：“桌子”不能作亲属称谓，与“爸爸的弟弟”无法搭配。", "叔叔": "叔叔：父亲的弟弟，或与父亲年纪相近的男性长辈。"}, "sentence_index": 0, "correct_answer": "叔叔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的叔叔是我妈妈的妹妹，在医院工作。", "explanation": "这里应该用〈阿姨〉。妈妈的妹妹是女性，“叔叔”只指男性。"}, {"text": "我的叔叔五岁，还在上幼儿园。", "explanation": "这里应该用〈小朋友〉。“叔叔”是与父亲同辈或年纪相近的成年男性，不能指小孩子。"}, {"text": "医院里有一只叔叔在工作。", "explanation": "这里应该用〈位〉。“只”用于动物，指人要用量词“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爷爷", "is_correct": false, "explanation": "语义：爷爷比爸爸大，不可能比爸爸小三岁。"}, {"text": "伯伯", "is_correct": false, "explanation": "语义：伯伯是父亲的哥哥，年龄比爸爸大，不能比爸爸小三岁。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“比较年龄”要求有年龄的人作主语，桌子不能比较年龄。"}, {"text": "叔叔", "is_correct": true, "explanation": "叔叔：父亲的弟弟，年龄比父亲小，可以说“比爸爸小三岁”。"}], "explanations": {"爷爷": "语义：爷爷比爸爸大，不可能比爸爸小三岁。", "伯伯": "语义：伯伯是父亲的哥哥，年龄比爸爸大，不能比爸爸小三岁。", "桌子": "配价：“比较年龄”要求有年龄的人作主语，桌子不能比较年龄。", "叔叔": "叔叔：父亲的弟弟，年龄比父亲小，可以说“比爸爸小三岁”。"}, "sentence_index": 6, "correct_answer": "叔叔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔是爷爷的弟弟，住在农村。", "explanation": "这里应该用〈叔爷〉。“叔叔”指父亲的弟弟，爷爷的弟弟不能称为叔叔。"}, {"text": "我叔叔是我的同学，和我一起上课。", "explanation": "这里不能用〈叔叔〉。“叔叔”是长辈称呼，不能用于〈朋友〉这类同龄人。"}, {"text": "我叔叔比爸爸大五岁，住在农村。", "explanation": "这里应该用〈伯伯〉。比父亲年长的男性要称伯伯，“叔叔”只指比父亲年轻或与父亲年龄相仿的男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位叔叔们在医院工作。", "corrected_sentence": "一位叔叔在医院工作。", "error_description": "“一位”表示一个人，不能与复数标记“们”同用；正确说法是“一位叔叔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只叔叔来了，他是爸爸的弟弟。", "corrected_sentence": "一位叔叔来了，他是爸爸的弟弟。", "error_description": "量词错误：指人的“叔叔”要用量词“位”，“只”用于动物，不能说「一只叔叔」；应把“只”改为“位”，正确说法是「一位叔叔来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
