INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39791, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "称呼与父母同辈但比父亲年轻的男性，可以是亲戚或非亲戚。", "primary_collocate": null, "pronunciation": "shū shu", "ipa": "ʂu˥ ʂu", "syllable_count": 2, "sentences": [{"text": "我叔叔是医生，在北京工作。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔比爸爸小三岁。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末叔叔开车带我去公园。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位叔叔帮我找到了我的书包。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友，叔叔请你吃糖。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔家有一只白色的小狗。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“快叫叔叔好！”", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔和阿姨今天来我们家吃饭。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的叔叔住在国外，很少回家。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，叔叔给了我一个红包。", "target_word": "叔叔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "叔叔们", "label": "复数"}], "register": "口语", "sense_fingerprint": "叔叔：父亲的弟弟，也用来称呼比父亲年轻的男性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "猫", "is_correct": false, "explanation": "语义：猫不能当医生，句子说的是一个人。"}, {"text": "叔叔", "is_correct": true, "explanation": "叔叔：父亲的弟弟，也可以用来称呼比父亲年轻的男性。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是人，不能作“我”的亲属称谓，也不能做医生。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：小孩子不能是医生，与“在北京工作”也不相符。"}], "explanations": {"猫": "语义：猫不能当医生，句子说的是一个人。", "叔叔": "叔叔：父亲的弟弟，也可以用来称呼比父亲年轻的男性。", "桌子": "搭配：“桌子”不是人，不能作“我”的亲属称谓，也不能做医生。", "小孩子": "语义：小孩子不能是医生，与“在北京工作”也不相符。"}, "sentence_index": 0, "correct_answer": "叔叔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我叔叔是我爸爸的哥哥。", "explanation": "这里应该用〈伯伯〉。叔叔指父亲的弟弟，父亲的哥哥要用伯伯。"}, {"text": "那位叔叔是我妈妈的妹妹，她很温柔。", "explanation": "这里应该用〈阿姨〉。妈妈的妹妹是女性，“叔叔”只指男性。"}, {"text": "我们班来了一只叔叔。", "explanation": "这里应该用〈位〉。“只”用于动物，指人要用量词“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "配价：“叫……好”要求人作宾语，石头不能被问候。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会听，也不能被称呼。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能用“快叫……好”这样的问候语来称呼。"}, {"text": "叔叔", "is_correct": true, "explanation": "叔叔：比父亲年轻的男性，小孩子可以用“叔叔”来称呼。"}], "explanations": {"石头": "配价：“叫……好”要求人作宾语，石头不能被问候。", "桌子": "语义：桌子不会听，也不能被称呼。", "小猫": "语义：小猫不能用“快叫……好”这样的问候语来称呼。", "叔叔": "叔叔：比父亲年轻的男性，小孩子可以用“叔叔”来称呼。"}, "sentence_index": 6, "correct_answer": "叔叔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我叔叔今年五岁，正在上幼儿园。", "explanation": "这里不能用〈叔叔〉。“叔叔”指与父母同辈的人，不能指小孩子。"}, {"text": "我的叔叔是爷爷的弟弟，住在农村。", "explanation": "这里应该用〈叔爷〉。“叔叔”指比父亲年轻的男性；爷爷的弟弟比父亲长一辈，不能称叔叔。"}, {"text": "我叔叔是我的同学，和我一起上课。", "explanation": "这里不能用〈叔叔〉。“叔叔”指长辈或比父亲年轻的男性，不能用于〈朋友〉这样的同辈人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只叔叔是老师，在上海工作。", "corrected_sentence": "我有一位叔叔是老师，在上海工作。", "error_description": "“只”用于动物或成对东西中的一个，指人要用量词“位”；正确说法是“一位叔叔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位叔叔们来我家了。", "corrected_sentence": "一位叔叔来我家了。", "error_description": "“一位”表示一个人，不能与表示复数的“们”同用；正确说法是“一位叔叔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
