INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "青少年是年龄在十三岁到十九岁之间的人。", "primary_collocate": null, "pronunciation": "qīng shào nián", "ipa": "tɕʰiŋ˥ ʂau˥˩ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "青少年的年龄在十三岁到十九岁之间。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十五岁的孩子是青少年。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年比小孩子懂得多一些。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是给青少年准备的。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年放学后常常去打球。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说青少年要多运动。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有两个青少年，一个十四岁。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年要学会照顾自己。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明十六岁，已经是青少年了。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多青少年活动中心。", "target_word": "青少年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "青少年期", "label": "复合"}], "register": "中性", "sense_fingerprint": "年龄在十三到十九岁之间的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b67ea2c-4f99-4305-8a7b-096353e3f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "青少年", "is_correct": true, "explanation": "语义：指年龄在十三岁到十九岁之间的人，与句中的年龄范围一致。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿的年龄远小于十三岁，与“十三岁到十九岁之间”不符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人的年龄远大于十九岁，与句中的年龄段矛盾。"}, {"text": "教师", "is_correct": false, "explanation": "搭配：“教师”是职业，不指一个年龄段，不能说“教师的年龄在十三岁到十九岁之间”。"}], "explanations": {"青少年": "语义：指年龄在十三岁到十九岁之间的人，与句中的年龄范围一致。", "婴儿": "语义：婴儿的年龄远小于十三岁，与“十三岁到十九岁之间”不符。", "老人": "语义：老人的年龄远大于十九岁，与句中的年龄段矛盾。", "教师": "搭配：“教师”是职业，不指一个年龄段，不能说“教师的年龄在十三岁到十九岁之间”。"}, "sentence_index": 0, "correct_answer": "青少年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶今年七十岁，已经是青少年了。", "explanation": "这里应该用〈老年人〉。青少年指十三岁到十九岁左右的人，七十岁的奶奶是老年人。"}, {"text": "院子里有一个三岁的青少年在玩。", "explanation": "这里应该用〈幼儿〉。青少年指十三岁到十九岁之间的人，三岁的孩子是幼儿，不能称青少年。"}, {"text": "花园里长着很多青少年。", "explanation": "这里应该用〈花〉。青少年只指人，不能用来指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青少年", "is_correct": true, "explanation": "语义：指十三到十九岁的人，“一个十四岁”符合这个年龄段。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人一般不会十四岁，与“一个十四岁”矛盾。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼不属于一个家庭，也没有年龄，这句话说不通。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“个”不搭配动物，“两个猫”不通，应说“只”。"}], "explanations": {"青少年": "语义：指十三到十九岁的人，“一个十四岁”符合这个年龄段。", "老人": "语义：老人一般不会十四岁，与“一个十四岁”矛盾。", "大楼": "语义：大楼不属于一个家庭，也没有年龄，这句话说不通。", "猫": "搭配：量词“个”不搭配动物，“两个猫”不通，应说“只”。"}, "sentence_index": 6, "correct_answer": "青少年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子才一岁，就是青少年了。", "explanation": "这里应该用〈婴儿〉。青少年指十三岁到十九岁之间的人，一岁的孩子是婴儿，不能称青少年。"}, {"text": "我哥哥二十五岁，还是个青少年。", "explanation": "这里应该用〈成年人〉。青少年指十三岁到十九岁之间的人，二十五岁的哥哥已是成年人。"}, {"text": "他三十岁了，是一名青少年。", "explanation": "这里应该用〈青年〉。青少年指十三岁到十九岁之间的人，三十岁的人应称青年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个夏令营里有一个青少年们，他很会游泳。", "corrected_sentence": "这个夏令营里有一个青少年，他很会游泳。", "error_description": "错误在“们”。“一个”与“们”不能同用，“青少年们”是复数，与“一个”矛盾。应改为“一个青少年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区里住着一只青少年，他很喜欢画画。", "corrected_sentence": "社区里住着一个青少年，他很喜欢画画。", "error_description": "错误在量词“只”。“青少年”指人，量词应用“个”，“只”多用于动物。正确的说法是“一个青少年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
