INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己有的东西送给需要的人。", "primary_collocate": null, "pronunciation": "juān xiàn", "ipa": "tɕɥɛn˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧衣服捐献给了山区的孩子。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些书捐献给图书馆。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捐献了自己一半的工资。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人把一生的积蓄都捐献给了学校。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人捐献粮食，帮助受灾的家庭。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司向灾区捐献了大量药品。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的孩子冬天很冷，大家捐献了很多棉衣。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有钱，只能捐献几件旧玩具。", "target_word": "捐献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己的奖金全部捐献给了养老院。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们捐献了自己的零花钱，帮助生病的小朋友。", "target_word": "捐献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐献了", "label": "完成体"}, {"form": "捐献过", "label": "经历体"}, {"form": "捐献者", "label": "复合"}, {"form": "捐獻", "label": "繁体"}], "register": "正式", "sense_fingerprint": "把自己的物品或钱送给需要帮助的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b67ea2c-4f99-4305-8a7b-096353e3f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿把财物送给需要帮助的人，与“给了山区的孩子”相符。"}, {"text": "修", "is_correct": false, "explanation": "配价：“修”不带“给”的双宾结构，不能说修给别人。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚烧，旧衣服烧掉后无法送给孩子，句子说不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指割开，与“旧衣服”和“给”搭配不当，不能说切给孩子。"}], "explanations": {"捐献": "语义：捐献指无偿把财物送给需要帮助的人，与“给了山区的孩子”相符。", "修": "配价：“修”不带“给”的双宾结构，不能说修给别人。", "烧": "语义：“烧”是焚烧，旧衣服烧掉后无法送给孩子，句子说不通。", "切": "搭配：“切”指割开，与“旧衣服”和“给”搭配不当，不能说切给孩子。"}, "sentence_index": 0, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把生日礼物捐献给了朋友。", "explanation": "这里应该用〈赠送〉。捐献指无偿交给机构或用于公益，送给朋友的礼物要用〈赠送〉。"}, {"text": "他把旧车捐献出去，还收了两千元。", "explanation": "这里应该用〈卖〉。捐献是无偿的，不能同时收取钱款。"}, {"text": "我把书捐献给了同学，过几天他还给我。", "explanation": "这里应该用〈借〉。捐献是把东西永久送出，不能说之后归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐献", "is_correct": true, "explanation": "语义：捐献指无偿送给需要的人，与“山区的孩子冬天很冷”的语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“棉衣”搭配，不能说吃棉衣。"}, {"text": "脱", "is_correct": false, "explanation": "语义：“脱”指脱下衣服，与“孩子冬天很冷”的语境相反，不能用来帮助孩子。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“大家帮助孩子”的语境相反。"}], "explanations": {"捐献": "语义：捐献指无偿送给需要的人，与“山区的孩子冬天很冷”的语境一致。", "吃": "搭配：“吃”不能与“棉衣”搭配，不能说吃棉衣。", "脱": "语义：“脱”指脱下衣服，与“孩子冬天很冷”的语境相反，不能用来帮助孩子。", "偷": "语义：“偷”是窃取，与“大家帮助孩子”的语境相反。"}, "sentence_index": 6, "correct_answer": "捐献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们捐献了那些贫困学生。", "explanation": "这里应该用〈资助〉。捐献的对象是财物或器官，不能用于人；资助人要用〈资助〉。"}, {"text": "他捐献了一场官司，结果输了。", "explanation": "这里应该用〈打〉。捐献的对象是财物或器官，不能用于官司这样的事件，应说“打官司”。"}, {"text": "他每年都按时捐献水电费。", "explanation": "这里应该用〈交纳〉。捐献是自愿无偿的，水电费是应付的费用，不能说捐献。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧书捐献给着山区的小学。", "corrected_sentence": "他把旧书捐献给了山区的小学。", "error_description": "错误在“了”。“捐献给”表示已完成的动作，应用“了”，不能用“着”。正确的说法是“捐献给了山区的小学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把社区捐献了一批旧书。", "corrected_sentence": "她向社区捐献了一批旧书。", "error_description": "错误在介词“向”。“捐献”的对象要用“向”引出，不能用“把”引出“社区”。正确的说法是“她向社区捐献了一批旧书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
