INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39800, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个人的器官放到另一个人身体里。", "primary_collocate": null, "pronunciation": "yí zhí", "ipa": "i˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "他生病了，需要别人给他移植肾脏。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一个肾脏移植给了儿子。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给爷爷移植了一颗新心脏。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她等了两年，终于等到可以移植的肝脏。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想把自己的肝脏移植给爸爸。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这位病人要移植别人的肾脏。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心脏不好，必须移植。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在给小女孩移植肺。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "移植别人的器官，病人要吃很多药。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意把眼角膜移植给看不见的孩子。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移植了", "label": "体标"}, {"form": "移植过", "label": "体标"}, {"form": "移植手术", "label": "复合"}], "register": "中性", "sense_fingerprint": "把一个人的器官放进另一个人的身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39800, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。移植指把一个人的器官放到另一个人身体里。"}, {"text": "一直", "is_correct": false, "explanation": "yī zhí（一直）与 yí zhí（移植）第一个音节声调不同，意思是连续不断。"}, {"text": "一致", "is_correct": false, "explanation": "yí zhì（一致）与 yí zhí（移植）第二个音节声调不同，意思是相同、协调。"}, {"text": "遗址", "is_correct": false, "explanation": "yí zhǐ（遗址）与 yí zhí（移植）第二个音节声调不同，意思是古代遗留下来的建筑或场所。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ zhì（以至）与 yí zhí（移植）两个音节声调都不同，意思是以致、甚至。"}], "explanations": {"移植": "正确答案。移植指把一个人的器官放到另一个人身体里。", "一直": "yī zhí（一直）与 yí zhí（移植）第一个音节声调不同，意思是连续不断。", "一致": "yí zhì（一致）与 yí zhí（移植）第二个音节声调不同，意思是相同、协调。", "遗址": "yí zhǐ（遗址）与 yí zhí（移植）第二个音节声调不同，意思是古代遗留下来的建筑或场所。", "以至": "yǐ zhì（以至）与 yí zhí（移植）两个音节声调都不同，意思是以致、甚至。"}, "sentence_index": null, "correct_answer": "移植"}, "level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。“需要别人给他移植肾脏”中，指把别人的器官放进他体内。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能把器官放进身体，与句意冲突。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热，不能用来处理器官，与句意冲突。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”用于悬挂物品，不说挂肾脏。"}], "explanations": {"移植": "正确答案。“需要别人给他移植肾脏”中，指把别人的器官放进他体内。", "吃": "语义：“吃”指进食，不能把器官放进身体，与句意冲突。", "烤": "语义：“烤”指用火加热，不能用来处理器官，与句意冲突。", "挂": "搭配：“挂”用于悬挂物品，不说挂肾脏。"}, "sentence_index": 0, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他移植了一个心脏起搏器。", "explanation": "这里应该用〈植入〉。起搏器是人工装置，放入体内要说植入，移植只用于别人的器官。"}, {"text": "医生给他移植了一个人工关节。", "explanation": "这里应该用〈换〉。人工关节不是别人的器官，换装人工关节不说移植。"}, {"text": "医生移植了他的伤口。", "explanation": "这里应该用〈缝合〉。伤口要缝合，不能移植；移植指把别人的器官放进身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39800, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。移植指把一个人的器官放到另一个人身体里。"}, {"text": "已知", "is_correct": false, "explanation": "yǐ zhī（已知）与 yí zhí（移植）两个音节声调都不同，意思是已经知道。"}, {"text": "遗志", "is_correct": false, "explanation": "yí zhì（遗志）与 yí zhí（移植）第二个音节声调不同，意思是人去世后留下的心愿。"}, {"text": "一支", "is_correct": false, "explanation": "yī zhī（一支）与 yí zhí（移植）两个音节声调都不同，此处是量词，意思是一根、一枝。"}, {"text": "以致", "is_correct": false, "explanation": "yǐ zhì（以致）与 yí zhí（移植）两个音节声调都不同，意思是因而导致。"}], "explanations": {"移植": "正确答案。移植指把一个人的器官放到另一个人身体里。", "已知": "yǐ zhī（已知）与 yí zhí（移植）两个音节声调都不同，意思是已经知道。", "遗志": "yí zhì（遗志）与 yí zhí（移植）第二个音节声调不同，意思是人去世后留下的心愿。", "一支": "yī zhī（一支）与 yí zhí（移植）两个音节声调都不同，此处是量词，意思是一根、一枝。", "以致": "yǐ zhì（以致）与 yí zhí（移植）两个音节声调都不同，意思是因而导致。"}, "sentence_index": null, "correct_answer": "移植"}, "level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。“他的心脏不好，必须移植”中，指通过手术更换器官。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指用热风弄干，不用于心脏，与句意冲突。"}, {"text": "编辑", "is_correct": false, "explanation": "语义：“编辑”指整理文字或资料，与心脏治疗无关，与句意冲突。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于房间、物品，不用于心脏。"}], "explanations": {"移植": "正确答案。“他的心脏不好，必须移植”中，指通过手术更换器官。", "烘干": "语义：“烘干”指用热风弄干，不用于心脏，与句意冲突。", "编辑": "语义：“编辑”指整理文字或资料，与心脏治疗无关，与句意冲突。", "装饰": "搭配：“装饰”用于房间、物品，不用于心脏。"}, "sentence_index": 6, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他移植了一针维生素。", "explanation": "这里应该用〈注射〉。维生素要注射或服用，不是器官，不能说移植。"}, {"text": "医生给他移植了两袋血。", "explanation": "这里应该用〈输〉。血液要说输，移植的对象只能是器官。"}, {"text": "护士把病床移植到了窗边。", "explanation": "这里应该用〈移动〉。病床是物品，移动要说移动，移植只用于器官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位母亲愿意把自己的一个肾移植女儿。", "corrected_sentence": "这位母亲愿意把自己的一个肾移植给女儿。", "error_description": "漏掉“给”：“移植”带受体时要用“给”引出，应说“移植给女儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把那位老人移植了一对新肺。", "corrected_sentence": "医生给那位老人移植了一对新肺。", "error_description": "“把”用错：“把”会把受体“那位老人”当作被移植的对象，应用“给”引出受体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
