INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将生物体的组织或器官从一个体转移到另一个体，或从身体的一部分转移到另一部分。", "primary_collocate": null, "pronunciation": "yí zhí", "ipa": "i˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "医生把他腿上的皮肤移植到手上。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烧伤后，医生要移植一块皮肤。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手术可以移植头发。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生从背部取皮，移植到脸上。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛受伤了，需要移植角膜。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把一段血管移植到了心脏上。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "移植骨头的手术做了五个小时。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的肝脏坏了，要移植新的。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在给病人移植皮肤。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术很成功，医生移植了一块新骨头。", "target_word": "移植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移植了", "label": "体标"}, {"form": "移植过", "label": "体标"}, {"form": "移植手术", "label": "复合"}], "register": "中性", "sense_fingerprint": "把组织或器官转移到另一个体或身体另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。移植指把组织或器官转移到另一个体或身体的另一处。"}, {"text": "一直", "is_correct": false, "explanation": "yī zhí（一直）与 yí zhí（移植）第一个音节声调不同，意思是连续不断。"}, {"text": "一致", "is_correct": false, "explanation": "yí zhì（一致）与 yí zhí（移植）第二个音节声调不同，意思是相同、协调。"}, {"text": "遗址", "is_correct": false, "explanation": "yí zhǐ（遗址）与 yí zhí（移植）第二个音节声调不同，意思是古代遗留下来的建筑或场所。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ zhì（以至）与 yí zhí（移植）两个音节声调都不同，意思是以致、甚至。"}], "explanations": {"移植": "正确答案。移植指把组织或器官转移到另一个体或身体的另一处。", "一直": "yī zhí（一直）与 yí zhí（移植）第一个音节声调不同，意思是连续不断。", "一致": "yí zhì（一致）与 yí zhí（移植）第二个音节声调不同，意思是相同、协调。", "遗址": "yí zhǐ（遗址）与 yí zhí（移植）第二个音节声调不同，意思是古代遗留下来的建筑或场所。", "以至": "yǐ zhì（以至）与 yí zhí（移植）两个音节声调都不同，意思是以致、甚至。"}, "sentence_index": null, "correct_answer": "移植"}, "level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。“医生把他腿上的皮肤移植到手上”中，指把皮肤转到另一处。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多用于可整体挪动的物件，不说搬皮肤。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”指把膏状物抹在表面，不说把皮肤涂到手上。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是割开，不能表示把皮肤放到另一处，与句意冲突。"}], "explanations": {"移植": "正确答案。“医生把他腿上的皮肤移植到手上”中，指把皮肤转到另一处。", "搬": "搭配：“搬”多用于可整体挪动的物件，不说搬皮肤。", "涂": "搭配：“涂”指把膏状物抹在表面，不说把皮肤涂到手上。", "切": "语义：“切”是割开，不能表示把皮肤放到另一处，与句意冲突。"}, "sentence_index": 0, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他移植了一个人工心脏瓣膜。", "explanation": "这里应该用〈植入〉。移植指把组织或器官转到体内，人工装置放入体内要说植入。"}, {"text": "医生把病人移植到了病房。", "explanation": "这里应该用〈移动〉。移植只用于组织或器官，移动病人要说移动。"}, {"text": "医生移植了他的伤口。", "explanation": "这里应该用〈缝合〉。伤口要缝合，不能移植；移植指把组织或器官转到别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39801, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。移植指把组织或器官转移到另一个体或身体的另一处。"}, {"text": "已知", "is_correct": false, "explanation": "yǐ zhī（已知）与 yí zhí（移植）两个音节声调都不同，意思是已经知道。"}, {"text": "遗志", "is_correct": false, "explanation": "yí zhì（遗志）与 yí zhí（移植）第二个音节声调不同，意思是人去世后留下的心愿。"}, {"text": "一支", "is_correct": false, "explanation": "yī zhī（一支）与 yí zhí（移植）两个音节声调都不同，此处是量词，意思是一根、一枝。"}, {"text": "以致", "is_correct": false, "explanation": "yǐ zhì（以致）与 yí zhí（移植）两个音节声调都不同，意思是因而导致。"}], "explanations": {"移植": "正确答案。移植指把组织或器官转移到另一个体或身体的另一处。", "已知": "yǐ zhī（已知）与 yí zhí（移植）两个音节声调都不同，意思是已经知道。", "遗志": "yí zhì（遗志）与 yí zhí（移植）第二个音节声调不同，意思是人去世后留下的心愿。", "一支": "yī zhī（一支）与 yí zhí（移植）两个音节声调都不同，此处是量词，意思是一根、一枝。", "以致": "yǐ zhì（以致）与 yí zhí（移植）两个音节声调都不同，意思是因而导致。"}, "sentence_index": null, "correct_answer": "移植"}, "level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正确答案。“移植骨头的手术”中，移植是修饰“手术”的动词。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清洁，与骨头手术无关，与句意冲突。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热，不用于手术，与句意冲突。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物送食，与手术无关，与句意冲突。"}], "explanations": {"移植": "正确答案。“移植骨头的手术”中，移植是修饰“手术”的动词。", "洗": "语义：“洗”指用水清洁，与骨头手术无关，与句意冲突。", "烤": "语义：“烤”指用火加热，不用于手术，与句意冲突。", "喂": "语义：“喂”指给人或动物送食，与手术无关，与句意冲突。"}, "sentence_index": 6, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他移植了一针疫苗。", "explanation": "这里应该用〈注射〉。疫苗要注射，不是器官，不能说移植。"}, {"text": "医生把两百毫升血移植到了病人身上。", "explanation": "这里应该用〈输〉。血液要输入，不能移植；移植只用于组织或器官。"}, {"text": "他把存款移植到了另一个账户。", "explanation": "这里应该用〈转移〉。存款要说转移，移植只用于生物组织或器官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生打算把健康的皮肤移植他的烧伤处。", "corrected_sentence": "医生打算把健康的皮肤移植到他的烧伤处。", "error_description": "漏掉“到”：“移植”后要用“到”引出受体位置，应说“移植到他的烧伤处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把一个新肾移植了他的父亲。", "corrected_sentence": "医生把一个新肾移植给了他的父亲。", "error_description": "漏掉“给”：“移植”的受体要用“给”引出，“移植了他的父亲”会被理解为移植父亲本人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
