INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茶是一种用茶树叶子加工制成的饮品，常以热水冲泡后饮用。", "primary_collocate": null, "pronunciation": "chá", "ipa": "tʂʰa˧˥", "syllable_count": 1, "sentences": [{"text": "在日本，茶的喝法是一种重要的仪式。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "喝茶时，人们要安静，心里想好事。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我每天早上喝一杯热茶。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯茶太烫了，我不能喝。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，妈妈给他倒了一杯茶。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢喝茶，不喜欢喝咖啡。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这壶茶是用开水泡的。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶喝茶的时候喜欢看报纸。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶太苦了，请给我一点儿糖。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后喝一杯茶，对身体好。", "target_word": "茶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "壶", "label": "量词"}, {"form": "茶叶", "label": "复合"}, {"form": "茶杯", "label": "复合"}], "register": "中性", "sense_fingerprint": "用茶叶泡成的热饮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39803, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”（chá）指用茶叶泡成的热饮，是本词的读音。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是叉子。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 chá（第二声）声调不同，意思是插入。"}, {"text": "馋", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是贪吃。"}, {"text": "岔", "is_correct": false, "explanation": "chà（第四声）与 chá（第二声）声调不同，意思是岔开。"}], "explanations": {"茶": "“茶”（chá）指用茶叶泡成的热饮，是本词的读音。", "叉": "chā（第一声）与 chá（第二声）声调不同，意思是叉子。", "插": "chā（第一声）与 chá（第二声）声调不同，意思是插入。", "馋": "chán 与 chá 韵母不同（多了 n），意思是贪吃。", "岔": "chà（第四声）与 chá（第二声）声调不同，意思是岔开。"}, "sentence_index": null, "correct_answer": "茶"}, "level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”指饮品，与“喝法是一种重要的仪式”相合。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“喝法”只用于饮品，不说“饭的喝法”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能用来喝，与“喝法”不合。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来喝，与“喝法”不合。"}], "explanations": {"茶": "“茶”指饮品，与“喝法是一种重要的仪式”相合。", "饭": "搭配：“喝法”只用于饮品，不说“饭的喝法”。", "桌子": "语义：桌子不能用来喝，与“喝法”不合。", "书": "语义：书不能用来喝，与“喝法”不合。"}, "sentence_index": 0, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一只热茶。", "explanation": "这里应该用〈杯〉。茶作饮品计量用杯、壶，不用“只”。"}, {"text": "他穿了一件茶色的外套。", "explanation": "这里的“茶”在“茶色”中指颜色，是另一义项，不是饮品。"}, {"text": "我们下午去茶楼坐了一会儿。", "explanation": "这里的“茶”在“茶楼”中指茶馆，是另一义项，不是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39803, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”（chá）指用茶叶泡成的热饮，是本词的读音。"}, {"text": "缠", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是缠绕。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chá 韵母不同（多了 n），意思是蝉（昆虫）。"}, {"text": "扯", "is_correct": false, "explanation": "chě（第三声）与 chá（第二声）声调不同，意思是拉、扯。"}, {"text": "差", "is_correct": false, "explanation": "chà（第四声）与 chá（第二声）声调不同，意思是不好、欠缺。"}], "explanations": {"茶": "“茶”（chá）指用茶叶泡成的热饮，是本词的读音。", "缠": "chán 与 chá 韵母不同（多了 n），意思是缠绕。", "蝉": "chán 与 chá 韵母不同（多了 n），意思是蝉（昆虫）。", "扯": "chě（第三声）与 chá（第二声）声调不同，意思是拉、扯。", "差": "chà（第四声）与 chá（第二声）声调不同，意思是不好、欠缺。"}, "sentence_index": null, "correct_answer": "茶"}, "level_3": {"options": [{"text": "茶", "is_correct": true, "explanation": "“茶”指用开水泡的饮品，与“这壶……是用开水泡的”相合。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐不能用开水泡，与“开水泡的”不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用开水泡，与“开水泡的”不合。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“泡”只用于饮品或食物，不用于衣服。"}], "explanations": {"茶": "“茶”指用开水泡的饮品，与“这壶……是用开水泡的”相合。", "盐": "语义：盐不能用开水泡，与“开水泡的”不合。", "石头": "语义：石头不能用开水泡，与“开水泡的”不合。", "衣服": "搭配：“泡”只用于饮品或食物，不用于衣服。"}, "sentence_index": 6, "correct_answer": "茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭后喝一根茶，对身体好。", "explanation": "这里应该用〈杯〉。茶作饮品计量用杯、壶，不用“根”。"}, {"text": "我们班下午开了一个茶会。", "explanation": "这里的“茶”在“茶会”中指聚会，是另一义项，不是饮品。"}, {"text": "这个配方需要两茶匙糖。", "explanation": "这里的“茶”在“茶匙”中指小勺，是另一义项，不是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,