INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饮用茶水。", "primary_collocate": null, "pronunciation": "hē chá", "ipa": "xɤ˥ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶喜欢在下午喝茶，吃点心。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园的亭子里喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有胃病，不能空着肚子喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝茶以前，先要把茶杯洗干净。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喝茶的时候，从来不说话。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷的时候，喝茶可以让身体暖和。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家茶馆很安静，很多人来这里喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我到家里喝茶，谈谈学习的事。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作很累，回家后只想喝茶休息。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，我们在树下喝茶，聊天。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喝了茶", "label": "体标：了"}, {"form": "喝过茶", "label": "体标：过"}, {"form": "喝着茶", "label": "体标：着"}, {"form": "喝喝茶", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动宾结构，指喝茶这种饮料的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶指饮用茶水，与“吃点心”的悠闲语境相合。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜指夜里不睡觉，与“下午”的时间不合。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针是医疗行为，不是悠闲的活动，与“吃点心”的语境不合。"}, {"text": "撸串", "is_correct": false, "explanation": "语域：撸串是口语俚语，与句中平稳的语体不协调。"}], "explanations": {"喝茶": "正确。喝茶指饮用茶水，与“吃点心”的悠闲语境相合。", "熬夜": "语义：熬夜指夜里不睡觉，与“下午”的时间不合。", "打针": "语义：打针是医疗行为，不是悠闲的活动，与“吃点心”的语境不合。", "撸串": "语域：撸串是口语俚语，与句中平稳的语体不协调。"}, "sentence_index": 0, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠喝茶把作业做完了。", "explanation": "这里应该用〈写〉。喝茶只指饮用茶水，做作业的动作应说写，不能用喝茶。"}, {"text": "这块香皂是用来喝茶的。", "explanation": "这里应该用〈洗〉。香皂是用来洗脸的，不能说“用来喝茶”。"}, {"text": "爸爸喝茶喝醉了。", "explanation": "这里应该用〈喝酒〉。醉是酒的作用，茶不会让人醉，不能说“喝茶喝醉了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶指饮用茶水，与“很安静”的茶馆语境相合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是热闹的活动，与“很安静”的环境不合。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架与“很安静”直接矛盾。"}, {"text": "打球", "is_correct": false, "explanation": "语义：打球是运动，与“很安静”的茶馆语境不合。"}], "explanations": {"喝茶": "正确。喝茶指饮用茶水，与“很安静”的茶馆语境相合。", "跳舞": "语义：跳舞是热闹的活动，与“很安静”的环境不合。", "吵架": "语义：吵架与“很安静”直接矛盾。", "打球": "语义：打球是运动，与“很安静”的茶馆语境不合。"}, "sentence_index": 6, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用高压锅喝茶。", "explanation": "这里应该用〈煮〉。高压锅是用来煮饭的，不能用来喝茶。"}, {"text": "这杯白开水可以直接喝茶。", "explanation": "这里应该用〈饮用〉。这杯是白开水，不是茶，“喝茶”只用于茶。"}, {"text": "这盏台灯每天都在喝茶。", "explanation": "这里应该用〈照明〉。台灯是用来照明的，不能做喝茶的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝茶着，看报纸。", "corrected_sentence": "他喝着茶，看报纸。", "error_description": "体标错误：进行体“着”应紧跟动词，应说“喝着茶”，不能说“喝茶着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶喝茶喝很开心。", "corrected_sentence": "奶奶喝茶喝得很开心。", "error_description": "补语错误：表示程度的补语前要加“得”，应说“喝得很开心”，不能说“喝很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
