INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39807, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饮用茶水的行为。", "primary_collocate": null, "pronunciation": "hē chá", "ipa": "xɤ˥ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "喝茶时，人们要安静，心里想好事。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我爷爷每天早上都喜欢喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上喝茶会让我睡不着觉。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去茶馆喝茶，聊聊天。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边喝茶，一边看报纸。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人喝茶的习惯很普遍。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，妈妈请他们坐下喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说睡前不要喝茶，对睡眠不好。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在院子里喝茶，月亮很圆。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王不爱喝咖啡，只爱喝茶。", "target_word": "喝茶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喝了茶", "label": "体标：了"}, {"form": "喝过茶", "label": "体标：过"}, {"form": "喝着茶", "label": "体标：着"}, {"form": "喝喝茶", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动宾结构，指饮用茶水这一日常行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶是饮用茶水的行为，与“人们要安静，心里想好事”的语境相合。"}, {"text": "喧哗", "is_correct": false, "explanation": "语义：喧哗是大声吵闹，与“人们要安静”直接矛盾。"}, {"text": "打架", "is_correct": false, "explanation": "语义：打架是激烈的肢体冲突，与“要安静，心里想好事”的语境相反。"}, {"text": "撸串", "is_correct": false, "explanation": "语域：撸串是口语俚语，与句中平稳的语体及“安静、想好事”的语境不协调。"}], "explanations": {"喝茶": "正确。喝茶是饮用茶水的行为，与“人们要安静，心里想好事”的语境相合。", "喧哗": "语义：喧哗是大声吵闹，与“人们要安静”直接矛盾。", "打架": "语义：打架是激烈的肢体冲突，与“要安静，心里想好事”的语境相反。", "撸串": "语域：撸串是口语俚语，与句中平稳的语体及“安静、想好事”的语境不协调。"}, "sentence_index": 0, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛他靠喝茶得了冠军。", "explanation": "这里应该用〈训练〉。喝茶指饮用茶水，不能说靠喝茶取得比赛冠军，要靠训练。"}, {"text": "他喝茶喝醉了。", "explanation": "这里应该用〈喝酒〉。醉是酒的作用，茶不会让人醉，不能说“喝茶喝醉了”。"}, {"text": "这辆车是用来喝茶的。", "explanation": "这里应该用〈开〉。车是用来开的，不能说“用来喝茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝茶", "is_correct": true, "explanation": "正确。喝茶指饮用茶水，与“请他们坐下”之后的待客语境相合。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步需要站起来活动，与“请他们坐下”的待客场景相反。"}, {"text": "整蛊", "is_correct": false, "explanation": "语域：整蛊是网络俚语，指捉弄人，与待客的礼貌语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不能在坐下时进行，与句意不合。"}], "explanations": {"喝茶": "正确。喝茶指饮用茶水，与“请他们坐下”之后的待客语境相合。", "跑步": "语义：跑步需要站起来活动，与“请他们坐下”的待客场景相反。", "整蛊": "语域：整蛊是网络俚语，指捉弄人，与待客的礼貌语境不合。", "游泳": "语义：游泳不能在坐下时进行，与句意不合。"}, "sentence_index": 6, "correct_answer": "喝茶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块肥皂是用来喝茶的。", "explanation": "这里应该用〈洗〉。肥皂是用来洗手的，不能说“用来喝茶”。"}, {"text": "这杯水可以直接喝茶。", "explanation": "这里应该用〈饮用〉。这杯是水，不是茶，“喝茶”只用于茶。"}, {"text": "这台微波炉每天都在喝茶。", "explanation": "这里应该用〈加热〉。微波炉是用来加热饭菜的，不能做喝茶的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去过茶馆，也喝茶过。", "corrected_sentence": "我去过茶馆，也喝过茶。", "error_description": "体标错误：体标“过”应紧跟动词，应说“喝过茶”，不能说“喝茶过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天早上喝一个茶。", "corrected_sentence": "他每天早上喝一杯茶。", "error_description": "量词错误：茶通常用“杯”计量，不能说“一个茶”，应说“一杯茶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”指干净有条理，与“安静”的不出声义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“安静”的不出声义没有反义关系。"}, {"text": "严厉", "is_correct": false, "explanation": "“严厉”形容态度或要求严格，与“安静”的不出声义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。", "整洁": "“整洁”指干净有条理，与“安静”的不出声义没有反义关系。", "明亮": "“明亮”指光线充足，与“安静”的不出声义没有反义关系。", "严厉": "“严厉”形容态度或要求严格，与“安静”的不出声义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”形容动作或头脑敏捷，与“安静”的不出声义没有反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”指数量多或种类多，与“安静”的不出声义没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“安静”的不出声义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（不出声）构成反义，指声音杂乱。", "灵活": "“灵活”形容动作或头脑敏捷，与“安静”的不出声义没有反义关系。", "丰富": "“丰富”指数量多或种类多，与“安静”的不出声义没有反义关系。", "清楚": "“清楚”指明白、不模糊，与“安静”的不出声义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说话，不发出声音；常用于请人保持安静。", "primary_collocate": null, "pronunciation": "ān jìng", "ipa": "an˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友们，请安静，老师要讲故事了。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课了，大家安静一下。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影开始了，请大家保持安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里要安静，不能大声说话。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子说：“安静，别说话！”", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝在睡觉，你们都安静点儿。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里请安静，不要大声说话。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛要开始了，观众都安静下来。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请同学们安静，听我说。”", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能安静三分钟吗？别出声。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安靜", "label": "繁体"}, {"form": "安安静静", "label": "重叠"}], "register": "中性", "sense_fingerprint": "要求别人不说话、不出声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”要求别人不说话、不出声，与“老师要讲故事了”的情境相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与“老师要讲故事了”需要静听的情境相反。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧嚷，与“老师要讲故事”的情境不合。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“严肃”说态度庄重，不用来要求小朋友“请”出的那种不说话的状态。"}], "explanations": {"安静": "“安静”要求别人不说话、不出声，与“老师要讲故事了”的情境相合。", "吵闹": "语义：“吵闹”指声音杂乱，与“老师要讲故事了”需要静听的情境相反。", "热闹": "语义：“热闹”指场面喧嚷，与“老师要讲故事”的情境不合。", "严肃": "搭配：“严肃”说态度庄重，不用来要求小朋友“请”出的那种不说话的状态。"}, "sentence_index": 0, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病人的病情很安静，医生很放心。", "explanation": "这里应该用〈稳定〉。“安静”只形容声音或环境，说病情的状况要用“稳定”。"}, {"text": "这篇文章很安静，每个段落都很清楚。", "explanation": "这里应该用〈完整〉。“安静”指没有声音，形容文章的结构齐全要用“完整”。"}, {"text": "这组数字很安静，计算结果都对。", "explanation": "这里应该用〈准确〉。“安静”不用来形容数字，说数字精确要用“准确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”要求别人不大声说话，与“图书馆里请……，不要大声说话”相合。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”指生动好动，与图书馆要求不大声说话的意思相反。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”形容表演或内容，不能用“请”来要求别人。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止，不能用“请”来要求别人的状态。"}], "explanations": {"安静": "“安静”要求别人不大声说话，与“图书馆里请……，不要大声说话”相合。", "活泼": "语义：“活泼”指生动好动，与图书馆要求不大声说话的意思相反。", "精彩": "搭配：“精彩”形容表演或内容，不能用“请”来要求别人。", "大方": "搭配：“大方”形容人的举止，不能用“请”来要求别人的状态。"}, "sentence_index": 6, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子很安静，用了好几年都没坏。", "explanation": "这里应该用〈牢固〉。“安静”形容声音或环境，形容物品结实要用“牢固”。"}, {"text": "老师对学生管得很安静，从来不批评人。", "explanation": "这里应该用〈严格〉。“安静”指没有声音，形容管理的松紧要用“严格”。"}, {"text": "这家店的服务员态度很安静，让人感觉很冷。", "explanation": "这里应该用〈热情〉。“安静”指没有声音，形容待人的态度要用“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家安静了，我有话要说。", "corrected_sentence": "请大家安静，我有话要说。", "error_description": "“安静”用于祈使句“请……”时不加“了”，应说“请大家安静”，不能说“请大家安静了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他安静安静地坐在角落里。", "corrected_sentence": "他安安静静地坐在角落里。", "error_description": "“安静”重叠要说“安安静静”，不能说“安静安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（没有声音）构成反义，指声音杂乱。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑灵活，与“安静”的声音义没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污物，与“安静”的声音义没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”指物体坚固，与“安静”的声音义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（没有声音）构成反义，指声音杂乱。", "聪明": "“聪明”形容头脑灵活，与“安静”的声音义没有反义关系。", "干净": "“干净”指没有污物，与“安静”的声音义没有反义关系。", "结实": "“结实”指物体坚固，与“安静”的声音义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": true, "explanation": "“吵闹”与“安静”（没有声音）构成反义，指声音杂乱。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“安静”的声音义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“安静”的声音义没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”形容举止不拘谨，与“安静”的声音义没有反义关系。"}], "correct_answer": "吵闹", "explanations": {"吵闹": "“吵闹”与“安静”（没有声音）构成反义，指声音杂乱。", "高兴": "“高兴”形容心情愉快，与“安静”的声音义没有反义关系。", "明亮": "“明亮”指光线充足，与“安静”的声音义没有反义关系。", "大方": "“大方”形容举止不拘谨，与“安静”的声音义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有吵闹声；不出声；宁静。", "primary_collocate": null, "pronunciation": "ān jìng", "ipa": "an˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "喝茶时，人们要安静，心里想好事。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "图书馆里很安静，大家都在看书。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝睡了，请你安静一点儿。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上这个小区非常安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进教室，教室一下子安静了。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的环境很安静，适合聊天。", "target_word": "安静", "complexity_tier": "T3", "furigana": "zhè jiā cāntīng de huánjìng hěn ānjìng, shìhé liáotiān.", "sentence_source": "generated"}, {"text": "我喜欢住在安静的地方。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候，同学们都很安静。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请安静，会议马上开始。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找个安静的房间看书。", "target_word": "安静", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安安静静", "label": "重叠"}, {"form": "安靜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "环境或人没有声音，宁静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”指没有声音，与“喝茶时，心里想好事”的平和氛围相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指声音杂乱，与“心里想好事”的安闲氛围相反。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多用于描写环境或声音，不用来说“人们要”怎样。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面人多而喧嚷，与喝茶时安静想事的情境不合。"}], "explanations": {"安静": "“安静”指没有声音，与“喝茶时，心里想好事”的平和氛围相合。", "吵闹": "语义：“吵闹”指声音杂乱，与“心里想好事”的安闲氛围相反。", "嘈杂": "搭配：“嘈杂”多用于描写环境或声音，不用来说“人们要”怎样。", "热闹": "语义：“热闹”指场面人多而喧嚷，与喝茶时安静想事的情境不合。"}, "sentence_index": 0, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盘菜很安静，味道很好。", "explanation": "这里应该用〈鲜美〉。“安静”只指没有声音或宁静，不用来形容菜的味道。"}, {"text": "这份合同很安静，条款都很周密。", "explanation": "这里应该用〈严谨〉。“安静”不用来形容合同或条款，说条款严密要用“严谨”。"}, {"text": "这份报告很安静，内容很周全。", "explanation": "这里应该用〈全面〉。“安静”指没有声音或宁静，不用来形容报告的内容；说内容周全要用“全面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安静", "is_correct": true, "explanation": "“安静”修饰“地方”，指没有吵闹声，与“喜欢住在”的意思相合。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”指天气潮湿炎热，人一般不会“喜欢住在”闷热的地方。"}, {"text": "严厉", "is_correct": false, "explanation": "搭配：“严厉”多形容人的态度，不用来修饰“地方”。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指表面不光滑，与“喜欢住在”的意思不合。"}], "explanations": {"安静": "“安静”修饰“地方”，指没有吵闹声，与“喜欢住在”的意思相合。", "闷热": "语义：“闷热”指天气潮湿炎热，人一般不会“喜欢住在”闷热的地方。", "严厉": "搭配：“严厉”多形容人的态度，不用来修饰“地方”。", "粗糙": "语义：“粗糙”指表面不光滑，与“喜欢住在”的意思不合。"}, "sentence_index": 6, "correct_answer": "安静"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上的书很安静，没有一本乱放。", "explanation": "这里应该用〈整齐〉。“安静”指没有声音，形容书的摆放有序要用“整齐”。"}, {"text": "这家店的价格很安静，很划算。", "explanation": "这里应该用〈便宜〉。“安静”不用来形容价格，说价格低要用“便宜”。"}, {"text": "这张桌子很安静，用了好几年都没坏。", "explanation": "这里应该用〈牢固〉。“安静”形容声音或环境，形容物品结实要用“牢固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈安静的走进了房间。", "corrected_sentence": "妈妈安静地走进了房间。", "error_description": "“安静”修饰动词“走进”时要用“地”，应说“安静地走进”；说“安静的走进”误用了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把会场安静了。", "corrected_sentence": "我们把会场弄安静了。", "error_description": "“安静”作结果补语时，“把”字句要加动词，应说“把会场弄安静”；直接说“把会场安静”，结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
