INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39811, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基因组学是研究生物体全部基因的结构、功能及相互作用的学科。", "primary_collocate": null, "pronunciation": "jī yīn zǔ xué", "ipa": "tɕi˥ in˥ tsu˨˩ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "基因组学的研究范围是生物体的全部基因。", "target_word": "基因组学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基因组学正在改变我们用药的方式。", "target_word": "基因组学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基因组学研究生物体全部的基因。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习基因组学。", "target_word": "基因组学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "基因组学帮助科学家了解基因之间的关系。", "target_word": "基因组学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授是研究基因组学的专家。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基因组学需要用计算机分析大量数据。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基因组学让我们更了解人类的身体。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对基因组学很感兴趣，所以选了这门课。", "target_word": "基因组学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，基因组学发展得非常快。", "target_word": "基因组学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "药物基因组学", "label": "复合"}, {"form": "功能基因组学", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究生物体全部基因的结构、功能及相互作用的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基因组学", "is_correct": true, "explanation": "正确。“基因组学”的研究范围是生物体的全部基因，与句意相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学并不研究生物体的基因，句意不通。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，不研究生物体的基因，句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不研究生物体的基因，句中不成立。"}], "explanations": {"基因组学": "正确。“基因组学”的研究范围是生物体的全部基因，与句意相符。", "数学": "语义：数学并不研究生物体的基因，句意不通。", "天文学": "语义：天文学研究天体，不研究生物体的基因，句意不通。", "音乐": "语义：音乐不研究生物体的基因，句中不成立。"}, "sentence_index": 0, "correct_answer": "基因组学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "基因组学决定了孩子的眼睛是什么颜色。", "explanation": "这里应该用〈遗传〉。“基因组学”是研究基因的学科，本身不能决定性状；决定眼睛颜色等性状的是〈遗传〉这一过程。"}, {"text": "研究人员在人体里找到了新的基因组学。", "explanation": "这里应该用〈遗传单位〉。“基因组学”是学科名称，不是具体的遗传单位，不能在人体里“找到”；能被找到的是〈遗传单位〉。"}, {"text": "人类基因组学已经测序完成。", "explanation": "这里应该用〈全部遗传物质〉。“基因组学”是学科名称，不能被测序；测序的对象是一个生物体的全部遗传物质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基因组学", "is_correct": true, "explanation": "正确。“基因组学”是学科名称，作主语时可以说“需要用计算机分析大量数据”，句意通顺。"}, {"text": "茶叶", "is_correct": false, "explanation": "语义：“茶叶”是植物制品，不能作为需要被计算机分析数据的对象。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，与“用计算机分析大量数据”无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“分析大量数据”的主体应是研究或系统，“冰箱”不能与之搭配。"}], "explanations": {"基因组学": "正确。“基因组学”是学科名称，作主语时可以说“需要用计算机分析大量数据”，句意通顺。", "茶叶": "语义：“茶叶”是植物制品，不能作为需要被计算机分析数据的对象。", "沙发": "语义：“沙发”是家具，与“用计算机分析大量数据”无关。", "冰箱": "搭配：“分析大量数据”的主体应是研究或系统，“冰箱”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "基因组学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人的基因组学主要储存在细胞核里。", "explanation": "这里应该用〈遗传物质〉。“基因组学”是研究基因的学科，不是储存遗传信息的物质，不能“储存在细胞核里”。"}, {"text": "基因组学是由一个基因突变引起的。", "explanation": "这里应该用〈遗传病〉。“基因组学”是学科，不是疾病，不能说由基因突变引起；由基因突变引起的是〈遗传病〉。"}, {"text": "我每天早上都会吃基因组学。", "explanation": "这里应该用〈粥〉。“基因组学”是学科，不是食物，不能“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的哥哥正在学习一条基因组学。", "corrected_sentence": "我的哥哥正在学习一门基因组学。", "error_description": "量词错误：“基因组学”作学科名称，量词应用“门”，不能用“条”（“条”用于细长之物）。应说：“我的哥哥正在学习一门基因组学。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究基因组学们的人很多。", "corrected_sentence": "研究基因组学的人很多。", "error_description": "后缀错误：“们”只用于指人的名词，学科名词“基因组学”后不能加“们”。应说：“研究基因组学的人很多。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
