INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "给人看病的、帮助人恢复健康的人。", "primary_collocate": null, "pronunciation": "yī shēng", "ipa": "i˥ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "医生在医院里工作。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我头疼，想去找医生。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说我需要多睡觉。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他哥哥是一位好医生。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生给奶奶检查了身体。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个医生对小朋友很好。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我长大以后想做医生。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生每天要看很多病人。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生告诉妈妈不用担心。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院有二十多位医生。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "医生们", "label": "复数"}], "register": "中性", "sense_fingerprint": "给人看病、帮助人恢复健康的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医生", "is_correct": true, "explanation": "正确。“医生”是在医院工作的人，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能在医院里工作，句意不通。"}, {"text": "老虎", "is_correct": false, "explanation": "配价：“工作”的主语须是人，“老虎”不能充当。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不是在医院里工作的人或职业，句意不通。"}], "explanations": {"医生": "正确。“医生”是在医院工作的人，与句意相符。", "石头": "语义：石头不能在医院里工作，句意不通。", "老虎": "配价：“工作”的主语须是人，“老虎”不能充当。", "足球": "语义：足球不是在医院里工作的人或职业，句意不通。"}, "sentence_index": 0, "correct_answer": "医生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他哥哥在好医生工作。", "explanation": "这里应该用〈医院〉。“医生”指人，不是场所，不能说“在好……工作”。"}, {"text": "他哥哥每天穿着医生去上班。", "explanation": "这里应该用〈白大褂〉。“医生”指人，不是衣服，不能“穿”。"}, {"text": "他哥哥学习了三年医生。", "explanation": "这里应该用〈医学〉。“学习”的对象应是学科，“医生”指人，不能学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医生", "is_correct": true, "explanation": "正确。“想做医生”是常用说法，指将来从事医生职业。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“做空气”不是可以说的职业，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是职业，“想做冰箱”与句意不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是职业，句中语义不通。"}], "explanations": {"医生": "正确。“想做医生”是常用说法，指将来从事医生职业。", "空气": "搭配：“做空气”不是可以说的职业，句意不通。", "冰箱": "语义：“冰箱”不是职业，“想做冰箱”与句意不符。", "窗户": "语义：“窗户”不是职业，句中语义不通。"}, "sentence_index": 6, "correct_answer": "医生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得了很重的医生。", "explanation": "这里应该用〈病〉。“得”后接的是疾病，“医生”不能被“得”。"}, {"text": "我每天吃三顿医生。", "explanation": "这里应该用〈饭〉。“医生”指人，不是食物，不能“吃”。"}, {"text": "他的哥哥在医生里工作。", "explanation": "这里应该用〈工厂〉。“医生”指人，不是场所，不能说“在……里工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈找了一只好医生。", "corrected_sentence": "我妈妈找了一位好医生。", "error_description": "量词错误：“医生”指人，量词应用“位”，不能用“只”。应说：“我妈妈找了一位好医生。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年找过一只医生。", "corrected_sentence": "我去年找过一位医生。", "error_description": "量词错误：“医生”指人，量词应用“位”，不能用“只”。应说：“我去年找过一位医生。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
