INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "掌握医药知识、以治病为职业的人。", "primary_collocate": null, "pronunciation": "yī shēng", "ipa": "i˥ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "药物基因组学帮助医生更好地选择药物治疗。", "target_word": "医生", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "通过了解一个人的基因，医生可以为他们提供更个性化的医疗方案。", "target_word": "医生", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "医生每天都很忙。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的姐姐是一名医生。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生让他多喝水，多休息。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就想当医生。", "target_word": "医生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "生病了就应该去看医生。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位医生对病人非常耐心。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给孩子开了一些药。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在医院当医生，晚上常常加班。", "target_word": "医生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "医生们", "label": "复数"}], "register": "中性", "sense_fingerprint": "掌握医药知识、以治病为职业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医生", "is_correct": true, "explanation": "正确。“医生”是给人看病、能够为病人选择药物治疗的人，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“选择药物治疗”，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是能为病人选择药物的主体。"}, {"text": "河流", "is_correct": false, "explanation": "配价：“选择”的主体须是有意识的人，“河流”不能充当。"}], "explanations": {"医生": "正确。“医生”是给人看病、能够为病人选择药物治疗的人，与句意相符。", "石头": "语义：石头不能“选择药物治疗”，句意不通。", "汽车": "语义：汽车不是能为病人选择药物的主体。", "河流": "配价：“选择”的主体须是有意识的人，“河流”不能充当。"}, "sentence_index": 0, "correct_answer": "医生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给孩子买了一些医生。", "explanation": "这里应该用〈药〉。“医生”指人，不是商品，不能“买”；“买”的应是〈药〉。"}, {"text": "他每天骑着医生去上班。", "explanation": "这里应该用〈自行车〉。“医生”指人，不是交通工具，不能“骑”。"}, {"text": "他在大学学习医生。", "explanation": "这里应该用〈医学〉。“学习”的对象应是学科，“医生”指人，不能学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医生", "is_correct": true, "explanation": "正确。“去看医生”是固定说法，指生病时就诊，与句意相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：生病时去看电影不能治病，与句意相反。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“看水果”不是就诊的意思，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“看”后接的对象应是能就诊的人，“窗户”不能与之搭配。"}], "explanations": {"医生": "正确。“去看医生”是固定说法，指生病时就诊，与句意相符。", "电影": "语义：生病时去看电影不能治病，与句意相反。", "水果": "语义：“看水果”不是就诊的意思，句意不通。", "窗户": "搭配：“看”后接的对象应是能就诊的人，“窗户”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "医生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸在医生工作。", "explanation": "这里应该用〈诊所〉。“医生”指人，不是工作场所，不能说“在……工作”。"}, {"text": "他每天早上吃医生。", "explanation": "这里应该用〈早饭〉。“医生”指人，不是食物，不能“吃”。"}, {"text": "他用医生擦桌子。", "explanation": "这里应该用〈抹布〉。“医生”指人，不能当工具使用，擦桌子应用〈抹布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三位医生们每天都很忙。", "corrected_sentence": "这三位医生每天都很忙。", "error_description": "后缀错误：有“这三位”这类数量短语修饰时，“医生”后不能加“们”。应说：“这三位医生每天都很忙。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年过看医生。", "corrected_sentence": "他去年看过医生。", "error_description": "体标错误：“过”应紧跟动词，应说“看过医生”，不能放在动词“看”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
