INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遗传学是研究爸爸妈妈怎么把特点传给宝宝的学问。", "primary_collocate": null, "pronunciation": "yí chuán xué", "ipa": "i˧˥ ʈʂʰuan˧˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "遗传学告诉我们宝宝为什么像爸爸。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学研究特点怎么传给孩子。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解遗传学。", "target_word": "遗传学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学了遗传学，我知道眼睛颜色会遗传。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学可以解释为什么孩子像妈妈。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟学习遗传学，想知道特点怎么传下来。", "target_word": "遗传学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢遗传学，因为很有意思。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遗传学课上，老师讲了豌豆的故事。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书用简单的话介绍遗传学。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈的特点，遗传学能给出答案。", "target_word": "遗传学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子遗传学", "label": "复合"}, {"form": "医学遗传学", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究父母特点怎样传给孩子的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗传学", "is_correct": true, "explanation": "“遗传学”是学科，可以作“告诉”的主语，说明宝宝像爸爸的原因，与句意相符。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，无法说明宝宝为什么像爸爸。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史研究过去的事件，与宝宝的外貌遗传无关。"}, {"text": "地质学", "is_correct": false, "explanation": "搭配：地质学一般不用来解释孩子像父母的原因，搭配不当。"}], "explanations": {"遗传学": "“遗传学”是学科，可以作“告诉”的主语，说明宝宝像爸爸的原因，与句意相符。", "天文学": "语义：天文学研究天体，无法说明宝宝为什么像爸爸。", "历史": "语义：历史研究过去的事件，与宝宝的外貌遗传无关。", "地质学": "搭配：地质学一般不用来解释孩子像父母的原因，搭配不当。"}, "sentence_index": 0, "correct_answer": "遗传学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我学了一本遗传学，知道眼睛颜色会遗传。", "explanation": "这里应该用〈门〉。遗传学是学科，量词用“门”；“本”用于书籍，不能修饰学科。"}, {"text": "那位遗传学很温柔，大家都喜欢她。", "explanation": "这里不能指人。遗传学是学科名称，指人要说“遗传学家”。"}, {"text": "我家里有人得了遗传学，所以我一直很担心。", "explanation": "这里应该用〈遗传病〉。遗传学是学科，不能指所患的病；说患病要用“遗传病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗传学", "is_correct": true, "explanation": "“遗传学”是学科，可以作“喜欢”的对象，并与“很有意思”相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是人们喜欢的对象，“她喜欢垃圾，因为很有意思”语义不通。"}, {"text": "下水道", "is_correct": false, "explanation": "语义：下水道不是令人喜欢的对象，与“很有意思”矛盾。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘令人讨厌，不能作“喜欢”的对象。"}], "explanations": {"遗传学": "“遗传学”是学科，可以作“喜欢”的对象，并与“很有意思”相符。", "垃圾": "语义：垃圾不是人们喜欢的对象，“她喜欢垃圾，因为很有意思”语义不通。", "下水道": "语义：下水道不是令人喜欢的对象，与“很有意思”矛盾。", "灰尘": "语义：灰尘令人讨厌，不能作“喜欢”的对象。"}, "sentence_index": 6, "correct_answer": "遗传学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些特点是遗传学造成的，她很清楚。", "explanation": "这里应该用〈遗传〉。遗传学指学科，表示特点传下来的现象要用“遗传”，学科不能造成特点。"}, {"text": "老师把遗传学塞进了书包里。", "explanation": "这里不能把学科当实物。遗传学是抽象的学科，不能塞进书包。"}, {"text": "这种病有很强的遗传学，家族里好几代人都得过。", "explanation": "这里应该用〈遗传性〉。“遗传性”指疾病能传给后代的性质，“遗传学”是学科，不能用来形容疾病的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈遗传学很了解。", "corrected_sentence": "妈妈对遗传学很了解。", "error_description": "错误：宾语“遗传学”不能直接放在状语“很”之前。正确形式是“妈妈对遗传学很了解”（或“妈妈很了解遗传学”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的哥哥正在学习过遗传学。", "corrected_sentence": "我的哥哥正在学习遗传学。", "error_description": "错误：“正在”表示动作进行，不能与表示经历的“过”同用。正确形式是“正在学习遗传学”，应去掉“过”，说“我的哥哥正在学习遗传学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
