INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西适合每个人自己的需要", "primary_collocate": null, "pronunciation": "gè xìng huà", "ipa": "ɡɤ˥˩ ɕiŋ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这个软件可以个性化你的主页。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把产品个性化，让每个人都满意。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以个性化手机的桌面。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在个性化这套学习课程。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该个性化教学，照顾每个学生。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以个性化设置，选择自己喜欢的颜色。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店能个性化蛋糕，你想写什么字都行。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的房间个性化了一下。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站会根据你的爱好个性化首页内容。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂开始个性化生产，一人一个样。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個性化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：把东西改成适合每个人自己需要的样子，如个性化教学、个性化首页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个性化", "is_correct": true, "explanation": "“个性化”作动词，表示使主页适合用户自己的需要，与句意相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”只能用于植物，不能用于“主页”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”是做饭，与软件处理主页无关，句子不成立。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”用于纸张或书籍，不能用于“主页”。"}], "explanations": {"个性化": "“个性化”作动词，表示使主页适合用户自己的需要，与句意相符。", "种植": "搭配：“种植”只能用于植物，不能用于“主页”。", "烹饪": "语义：“烹饪”是做饭，与软件处理主页无关，句子不成立。", "装订": "搭配：“装订”用于纸张或书籍，不能用于“主页”。"}, "sentence_index": 0, "correct_answer": "个性化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们正在个性化这个孩子的身高。", "explanation": "这里应该用〈测量〉。“个性化”指按每个人的需要调整事物，身高是天生的，无法调整；测量身高要用“测量”。"}, {"text": "这套学习课程正在个性化他们。", "explanation": "这里应该用〈培养〉。“个性化”的对象是课程、产品等事物，不能使人个性化；培养人要用“培养”。"}, {"text": "他们正在个性化一年的时间。", "explanation": "这里应该用〈安排〉。“个性化”指按需要调整事物，“一年的时间”要说“安排”，不能说“个性化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个性化", "is_correct": true, "explanation": "“个性化”作动词，表示为顾客定制蛋糕，与“你想写什么字都行”相符。"}, {"text": "缝纫", "is_correct": false, "explanation": "搭配：“缝纫”用于布料和衣物，不能用于蛋糕。"}, {"text": "装裱", "is_correct": false, "explanation": "语义：“装裱”是给字画加框，与蛋糕无关，句子不成立。"}, {"text": "焊接", "is_correct": false, "explanation": "搭配：“焊接”用于金属，不能用于蛋糕。"}], "explanations": {"个性化": "“个性化”作动词，表示为顾客定制蛋糕，与“你想写什么字都行”相符。", "缝纫": "搭配：“缝纫”用于布料和衣物，不能用于蛋糕。", "装裱": "语义：“装裱”是给字画加框，与蛋糕无关，句子不成立。", "焊接": "搭配：“焊接”用于金属，不能用于蛋糕。"}, "sentence_index": 6, "correct_answer": "个性化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂开始个性化生产，一批产品都一模一样。", "explanation": "这里应该用〈批量〉。“个性化”强调按每人需要不同，与“一批产品都一模一样”相矛盾；大批量生产要用“批量”。"}, {"text": "工厂开始个性化天空，一人一个样。", "explanation": "这里误用了词义：此处“个性化”被当作“使……独特”，而天空是自然现象，不能按每人需要定制。"}, {"text": "工厂开始个性化生产，所有产品的颜色、尺寸全部相同。", "explanation": "这里应该用〈标准化〉。“个性化”强调按每人需要不同，与“颜色、尺寸全部相同”相矛盾；标准化生产才是统一规格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把主页个性化很好看。", "corrected_sentence": "他把主页个性化得很好看。", "error_description": "错误：缺少补语标记“得”。正确形式是“个性化得很好看”，应说“他把主页个性化得很好看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员正在为顾客个性化过蛋糕。", "corrected_sentence": "店员正在为顾客个性化蛋糕。", "error_description": "错误：“正在”表示动作正在进行，不能与“过”同用，应去掉“过”。正确形式是“正在为顾客个性化蛋糕”，应说“店员正在为顾客个性化蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
