INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39817, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "根据个人特点或需求进行定制，使其符合特定个体的特征", "primary_collocate": null, "pronunciation": "gè xìng huà", "ipa": "ɡɤ˥˩ ɕiŋ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "通过了解一个人的基因，医生可以为他们提供更个性化的医疗方案。", "target_word": "个性化", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家店的服务很个性化，顾客都很满意。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要一份个性化的学习计划。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能给你推荐个性化的音乐。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢个性化的手机壳。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的房间设计得非常个性化。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为每个学生做了个性化的练习。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的礼物更个性化，朋友一定喜欢。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个性化的服务让客人觉得很舒服。", "target_word": "个性化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套家具是根据我家的房间尺寸个性化定制的。", "target_word": "个性化", "complexity_tier": "T3", "furigana": "zhè tào jiā jù shì gēn jù wǒ jiā de fáng jiān chǐ cùn gè xìng huà dìng zhì de", "sentence_source": "generated"}], "morphological_forms": [{"form": "個性化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：符合某个人的特点或需求的、专门定制的，如个性化的服务、个性化的方案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个性化", "is_correct": true, "explanation": "“个性化”修饰医疗方案，表示按个人情况定制，与“了解一个人的基因”相符。"}, {"text": "标准化", "is_correct": false, "explanation": "语义：“标准化”指统一规格，与“了解一个人的基因后为他们提供”的定制相矛盾。"}, {"text": "大众化", "is_correct": false, "explanation": "语义：“大众化”面向大多数人，与“为他们提供”的个人方案相矛盾。"}, {"text": "量产", "is_correct": false, "explanation": "搭配：“量产”多用于产品，不能修饰“医疗方案”。"}], "explanations": {"个性化": "“个性化”修饰医疗方案，表示按个人情况定制，与“了解一个人的基因”相符。", "标准化": "语义：“标准化”指统一规格，与“了解一个人的基因后为他们提供”的定制相矛盾。", "大众化": "语义：“大众化”面向大多数人，与“为他们提供”的个人方案相矛盾。", "量产": "搭配：“量产”多用于产品，不能修饰“医疗方案”。"}, "sentence_index": 0, "correct_answer": "个性化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂个性化生产同样的产品。", "explanation": "这里应该用〈批量〉。个性化强调按每人需要定制，与“同样的产品”相矛盾；大批量生产同款产品要用“批量”。"}, {"text": "这份通知很个性化，所有人收到的内容都一样。", "explanation": "这里误用了词义。“个性化”指按每人需要定制，与“所有人收到的内容都一样”相矛盾；这里应该用〈统一〉。"}, {"text": "这片海很个性化，每年都有很多人来。", "explanation": "这里误用了词义。“个性化”指按个人需要定制，这里却当作“独具特色”来用，而海是自然景观，不能按个人需要定制；这里应该用〈美丽〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个性化", "is_correct": true, "explanation": "“个性化”修饰练习，表示针对每个学生的不同需要，与“为每个学生做”相符。"}, {"text": "集体的", "is_correct": false, "explanation": "语义：“集体的练习”与“为每个学生”相矛盾，练习是针对个人的。"}, {"text": "公式化的", "is_correct": false, "explanation": "语义：“公式化”指千篇一律，与“为每个学生做”的针对性相矛盾。"}, {"text": "笼统的", "is_correct": false, "explanation": "搭配：“笼统的练习”搭配不当，练习一般是具体的，与“为每个学生”不符。"}], "explanations": {"个性化": "“个性化”修饰练习，表示针对每个学生的不同需要，与“为每个学生做”相符。", "集体的": "语义：“集体的练习”与“为每个学生”相矛盾，练习是针对个人的。", "公式化的": "语义：“公式化”指千篇一律，与“为每个学生做”的针对性相矛盾。", "笼统的": "搭配：“笼统的练习”搭配不当，练习一般是具体的，与“为每个学生”不符。"}, "sentence_index": 6, "correct_answer": "个性化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山很个性化，每年都有很多人来。", "explanation": "这里误用了词义。此处“个性化”被当作“独具特色”来用，但山是自然景观，不能按个人需要定制；这里应该用〈雄伟〉。"}, {"text": "这几篇作文千篇一律，每篇都很个性化。", "explanation": "这里误用了词义：此处“个性化”被当作“各有特色”，但“千篇一律”说明各篇完全相同，二者相矛盾。"}, {"text": "他很个性化地长高了一厘米。", "explanation": "这里误用了词义。“个性化”指按个人需要定制，身高增长是自然过程，无法个性化；这里应该用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份礼物比那份很个性化。", "corrected_sentence": "这份礼物比那份更个性化。", "error_description": "错误：“比”字句中不能与程度副词“很”同用。正确形式是“比……更个性化”，应说“这份礼物比那份更个性化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们选了一款个性化地手机壳。", "corrected_sentence": "我们选了一款个性化的手机壳。", "error_description": "错误：修饰名词“手机壳”时应用“的”，不能用“地”。正确形式是“个性化的手机壳”，应说“我们选了一款个性化的手机壳。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
