INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指为了保持或恢复健康而进行的各种活动，比如看病、吃药、做手术等。", "primary_collocate": null, "pronunciation": "yī liáo", "ipa": "i˥ ljɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "通过了解一个人的基因，医生可以为他提供更个性化的医疗方案。", "target_word": "医疗", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这家医院的医疗条件很好。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的医疗服务越来越方便了。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看病需要很多医疗费用。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家提高了医疗水平。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了医疗保险，生病时不用担心。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗队到山区给村民看病。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的医疗设备很新。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗技术的进步让很多病人活了下来。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在国外生病，医疗很贵。", "target_word": "医疗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醫療", "label": "繁体"}, {"form": "医疗保险", "label": "复合"}, {"form": "医疗队", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：为保持或恢复健康而进行的看病、吃药、手术等活动，如医疗条件、医疗保险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗指看病治病的活动，此处修饰“方案”，符合句意。"}, {"text": "财务", "is_correct": false, "explanation": "语义：财务指财产和账目，与基因、医生无关，句子讲的是健康方案。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指房屋布置，与“基因”“医生”的健康内容不相关。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影与基因、医生和健康无关，不能作为健康方案的内容。"}], "explanations": {"医疗": "医疗指看病治病的活动，此处修饰“方案”，符合句意。", "财务": "语义：财务指财产和账目，与基因、医生无关，句子讲的是健康方案。", "装修": "语义：装修指房屋布置，与“基因”“医生”的健康内容不相关。", "电影": "语义：电影与基因、医生和健康无关，不能作为健康方案的内容。"}, "sentence_index": 0, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是医疗，毕业后当了医生。", "explanation": "这里应该用〈医学〉。医疗指看病治病的活动，学科名称要用医学。"}, {"text": "药店里卖各种医疗，价格都不贵。", "explanation": "这里应该用〈药品〉。医疗是治病的活动，不能像商品一样摆在药店里出售。"}, {"text": "医疗给我打了一针，我的病好多了。", "explanation": "这里应该用〈护士〉。医疗是治病的活动，不能给病人打针，打针的是护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医疗", "is_correct": true, "explanation": "医疗队指专门去看病治病的队伍，与“看病”的内容一致。"}, {"text": "消防", "is_correct": false, "explanation": "语义：消防队负责灭火救援，不会去山区给村民看病。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球队是体育团体，不会去山区给村民看病。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传队”指做宣传的队伍，不说去给村民看病。"}], "explanations": {"医疗": "医疗队指专门去看病治病的队伍，与“看病”的内容一致。", "消防": "语义：消防队负责灭火救援，不会去山区给村民看病。", "篮球": "语义：篮球队是体育团体，不会去山区给村民看病。", "宣传": "搭配：“宣传队”指做宣传的队伍，不说去给村民看病。"}, "sentence_index": 6, "correct_answer": "医疗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给病人做了一台医疗。", "explanation": "量词误用：“台”用于机器，医疗指看病治病的活动，应说“一次医疗”。"}, {"text": "医院给我做了一把医疗。", "explanation": "量词误用：“把”用于有柄的器具，医疗不是器具，应说“一次医疗”。"}, {"text": "我昨天接受了一只医疗。", "explanation": "量词误用：“只”用于动物等，医疗是活动，应说“一次医疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他接受了一个医疗，身体恢复得很快。", "corrected_sentence": "他接受了一次医疗，身体恢复得很快。", "error_description": "量词错误：“医疗”指一次治疗活动，计数应用“次”，正确说“一次医疗”，不能说“一个医疗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人看病地医疗费用很高。", "corrected_sentence": "老人看病的医疗费用很高。", "error_description": "错误：修饰名词“费用”时应用“的”，不能用“地”（“地”用于副词）。正确形式是“看病的医疗费用”，应说“老人看病的医疗费用很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "效果就是做一件事得到的结果。", "primary_collocate": null, "pronunciation": "xiào guǒ", "ipa": "ɕjɑʊ˥˩ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我复习了一周，效果真不错。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没有什么效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，可是效果不太明显。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想看看这次练习的效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的努力终于有了效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法的效果比那种好。", "target_word": "效果", "complexity_tier": "T3", "furigana": "zhè zhǒng fāngfǎ de xiàoguǒ bǐ nà zhǒng hǎo", "sentence_source": "generated"}, {"text": "孩子们学得很认真，效果让大家高兴。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了很多宣传，但效果一般。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥要坚持，才会有效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一个月，我看到了效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种效果", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：做一件事之后得到的结果，如学习效果、效果明显", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "效果", "is_correct": true, "explanation": "效果指复习带来的结果，与“复习了一周”的句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：复习不会带来体重的变化，“体重真不错”与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：复习的结果不是颜色，不能说“颜色真不错”。"}, {"text": "力气", "is_correct": false, "explanation": "语义：复习的结果是“效果”，“力气”不是复习能带来的结果，句子讲的是学习成效。"}], "explanations": {"效果": "效果指复习带来的结果，与“复习了一周”的句意相符。", "体重": "语义：复习不会带来体重的变化，“体重真不错”与句意不符。", "颜色": "语义：复习的结果不是颜色，不能说“颜色真不错”。", "力气": "语义：复习的结果是“效果”，“力气”不是复习能带来的结果，句子讲的是学习成效。"}, "sentence_index": 0, "correct_answer": "效果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是老师最好的效果。", "explanation": "这里应该用〈学生〉。效果指做事得到的结果，不能指人，说老师的学生要用学生。"}, {"text": "老师批改了我的效果。", "explanation": "这里应该用〈作业〉。效果是结果，不能被批改，批改的是作业。"}, {"text": "老师讲了这篇效果。", "explanation": "这里应该用〈课文〉。效果不是可以讲授的内容，讲的是课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效果", "is_correct": true, "explanation": "效果指学习带来的结果，作主语可以让大家高兴，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因学习认真而让大家高兴，句子讲的是学习的结果。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不是学习的结果，与“学得很认真”不相关。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”不能作“让大家高兴”的主语，与句子搭配不当。"}], "explanations": {"效果": "效果指学习带来的结果，作主语可以让大家高兴，符合句意。", "年龄": "语义：年龄不会因学习认真而让大家高兴，句子讲的是学习的结果。", "身高": "语义：身高不是学习的结果，与“学得很认真”不相关。", "面积": "搭配：“面积”不能作“让大家高兴”的主语，与句子搭配不当。"}, "sentence_index": 6, "correct_answer": "效果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过了一个月，我看到了一颗效果。", "explanation": "量词误用：“颗”用于粒状的小东西，效果不能用“颗”，应说“一种效果”。"}, {"text": "过了一个月，我看到了一张效果。", "explanation": "量词误用：“张”用于平面的东西，效果不能用“张”，应说“一种效果”。"}, {"text": "过了一个月，我看到了一支效果。", "explanation": "量词误用：“支”用于棍状物，效果不能用“支”，应说“一种效果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法很快就有了一只效果。", "corrected_sentence": "这个方法很快就有了一种效果。", "error_description": "量词错误：“效果”前应用“种”，“只”只用于动物等，不能说“一只效果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一把很好的学习效果。", "corrected_sentence": "他找到了很好的学习效果。", "error_description": "量词错误：“效果”前不应加“把”，“把”用于有柄的器具，这里直接说“很好的学习效果”，不用量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "效果指某种行为或原因带来的结果或作用。", "primary_collocate": null, "pronunciation": "xiào guǒ", "ipa": "ɕjɑʊ˥˩ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这有助于提高药物效果，减少副作用。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种药的效果很好，一天就退烧了。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动三个月后，效果慢慢出来了。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了很多方法，但是效果不好。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告的效果让老板很满意。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语要天天练，这样效果才好。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以后没有马上看到效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的教学方法取得了很好的效果。", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这样做会有什么效果？", "target_word": "效果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了取得好效果，请按时吃药。", "target_word": "效果", "complexity_tier": "T3", "furigana": "wèile qǔdé hǎo xiàoguǒ, qǐng ànshí chīyào", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种效果", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：某种行为或原因带来的结果或作用，如药物效果、效果很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063c992-a432-44b6-a204-80d92cf62963') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "效果", "is_correct": true, "explanation": "效果指药物产生的作用，与“提高”搭配，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“药物体重”不成词，“药物”不能修饰“体重”，句子讲的是药物的作用。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观，不是药物的作用，与“减少副作用”无关。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“提高人数”可以说，但“药物人数”不通，不能作“药物”的修饰对象。"}], "explanations": {"效果": "效果指药物产生的作用，与“提高”搭配，符合句意。", "体重": "搭配：“药物体重”不成词，“药物”不能修饰“体重”，句子讲的是药物的作用。", "颜色": "语义：颜色是外观，不是药物的作用，与“减少副作用”无关。", "人数": "搭配：“提高人数”可以说，但“药物人数”不通，不能作“药物”的修饰对象。"}, "sentence_index": 0, "correct_answer": "效果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我最好的效果，我们一起长大。", "explanation": "这里应该用〈朋友〉。效果指行为的作用或结果，不能用来指人，表示人际关系要说朋友。"}, {"text": "我想再吃一份这种效果，味道很好。", "explanation": "这里应该用〈菜〉。效果是行为的结果，不能拿来吃，要说菜。"}, {"text": "我的效果增加了三公斤。", "explanation": "这里应该用〈体重〉。效果指作用或结果，不能用来计量身体的重量，要说体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效果", "is_correct": true, "explanation": "效果指吃药后产生的作用，是“看到”的对象，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：药的味道是用舌头尝到的，不是吃药后可以“看到”的结果。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听到的，不是吃药后可以“看到”的结果。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“看到名字”不能指吃药后的变化，与“没有马上”的句意不搭。"}], "explanations": {"效果": "效果指吃药后产生的作用，是“看到”的对象，符合句意。", "味道": "语义：药的味道是用舌头尝到的，不是吃药后可以“看到”的结果。", "声音": "语义：声音是听到的，不是吃药后可以“看到”的结果。", "名字": "搭配：“看到名字”不能指吃药后的变化，与“没有马上”的句意不搭。"}, "sentence_index": 6, "correct_answer": "效果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种新药取得了一台效果。", "explanation": "量词误用：“台”用于机器，效果不是器具，应说“一种效果”。"}, {"text": "他的努力取得了一把效果。", "explanation": "量词误用：“把”用于有柄的物品，效果不能这样计数，应说“一种效果”。"}, {"text": "这次改革取得了一只效果。", "explanation": "量词误用：“只”用于动物等，效果不能用“只”，应说“一种效果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次训练取得了一本明显的效果。", "corrected_sentence": "这次训练取得了一种明显的效果。", "error_description": "量词错误：“效果”前应用“种”，“本”用于书籍，不能说“一本效果”，正确说“一种明显的效果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每天坚持锻炼，的效果会更好。", "corrected_sentence": "每天坚持锻炼，效果会更好。", "error_description": "助词错误：“效果”作主语时前面不能加“的”，“的”不能放在主语前；应说“每天坚持锻炼，效果会更好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241c6bee-6377-4662-9cf1-dbe7d3ab1b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
