INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39822, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用药就是吃或使用药。", "primary_collocate": null, "pronunciation": "yòng yào", "ipa": "jʊŋ˥˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他生病了，需要用药。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用药前请先问医生。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子用药要看年龄和体重。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天提醒爷爷按时用药。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对用药很小心，每次都看说明书。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生教我怎么正确用药。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用药后如果头晕，要马上告诉医生。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把用药的时间写在了本子上。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了用药，所以今天还是不舒服。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后半小时用药，效果比较好。", "target_word": "用药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用过药", "label": "体标"}, {"form": "用药量", "label": "复合"}, {"form": "合理用药", "label": "复合"}], "register": "中性", "sense_fingerprint": "用药：吃药或使用药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b355173-4ded-4ba2-b8ef-c4046b577508') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39822, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确答案。用药（yòng yào）指吃药或使用药物。"}, {"text": "送药", "is_correct": false, "explanation": "声母不同：sòng 与 yòng 只有声母 s 和 y 不同，意思是把药送去。"}, {"text": "用到", "is_correct": false, "explanation": "声母不同：dào 与 yào 只有声母 d 和 y 不同，意思是使用到。"}, {"text": "又要", "is_correct": false, "explanation": "韵尾不同：yòu 与 yòng 只有韵尾 u 和 ng 不同，意思是“又要（做某事）”。"}, {"text": "用料", "is_correct": false, "explanation": "声母不同：liào 与 yào 只有声母 l 和 y 不同，意思是使用材料。"}], "explanations": {"用药": "正确答案。用药（yòng yào）指吃药或使用药物。", "送药": "声母不同：sòng 与 yòng 只有声母 s 和 y 不同，意思是把药送去。", "用到": "声母不同：dào 与 yào 只有声母 d 和 y 不同，意思是使用到。", "又要": "韵尾不同：yòu 与 yòng 只有韵尾 u 和 ng 不同，意思是“又要（做某事）”。", "用料": "声母不同：liào 与 yào 只有声母 l 和 y 不同，意思是使用材料。"}, "sentence_index": null, "correct_answer": "用药"}, "level_3": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确：“他生病了，需要用药”中，「用药」表示吃药或使用药物，符合语境。"}, {"text": "报名", "is_correct": false, "explanation": "语义：生病与报名无关，“生病了，需要报名”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：生病的人需要治疗，“需要结婚”与语境无关。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“需要”后面不能接自然现象“下雨”来应对生病。"}], "explanations": {"用药": "正确：“他生病了，需要用药”中，「用药」表示吃药或使用药物，符合语境。", "报名": "语义：生病与报名无关，“生病了，需要报名”说不通。", "结婚": "语义：生病的人需要治疗，“需要结婚”与语境无关。", "下雨": "搭配：“需要”后面不能接自然现象“下雨”来应对生病。"}, "sentence_index": 0, "correct_answer": "用药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去药店用药，店员马上给我拿了药。", "explanation": "这里应该用〈抓药〉。去药店取药要说抓药，用药指使用药物。"}, {"text": "他去医院用药，医生让他观察几天。", "explanation": "这里应该用〈住院〉。去医院接受观察要说住院，用药只表示使用药物。"}, {"text": "我每天早上用药刷牙。", "explanation": "这里应该用〈洗漱〉。用药只指吃或使用药物，早上刷牙、洗脸要说洗漱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用药", "is_correct": true, "explanation": "正确：「用药后」指吃药之后的时间，与后面“头晕”的提醒相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生后如果头晕，要马上告诉医生”指向新生儿，与原句的语境不符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚与头晕、告诉医生的提醒之间没有关系。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记后头晕”没有与提醒就医相关的合理搭配。"}], "explanations": {"用药": "正确：「用药后」指吃药之后的时间，与后面“头晕”的提醒相符。", "出生": "语义：“出生后如果头晕，要马上告诉医生”指向新生儿，与原句的语境不符。", "结婚": "语义：结婚与头晕、告诉医生的提醒之间没有关系。", "登记": "搭配：“登记后头晕”没有与提醒就医相关的合理搭配。"}, "sentence_index": 6, "correct_answer": "用药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房用药，给我们做了很多菜。", "explanation": "这里应该用〈做饭〉。用药指使用药物，在厨房做菜要说做饭。"}, {"text": "我的自行车坏了，要拿去用药。", "explanation": "这里应该用〈修车〉。用药只指使用药物，自行车坏了要说修车。"}, {"text": "他每天在书店用药，很喜欢看书。", "explanation": "这里应该用〈阅读〉。用药只指吃或使用药物，在书店读书要说阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都要学会正确用药过。", "corrected_sentence": "我们都要学会正确用药。", "error_description": "多余的“过”：“过”不能紧跟宾语“药”，句末的“过”应去掉，说“学会正确用药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前用过很多次药过，效果都不好。", "corrected_sentence": "他以前用过很多次药，效果都不好。", "error_description": "多余的“过”：“用过”已表达经历，宾语“药”之后不能再接“过”，去掉“药”后的“过”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
