INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木马是一种玩具，小朋友可以骑在上面玩。", "primary_collocate": null, "pronunciation": "mù mǎ", "ipa": "mu˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "小弟弟爱坐在木马上玩。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里卖各种各样的木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在木马上摇来摇去。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个木马是用木头做的，很结实。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女儿过生日，我送她一个木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幼儿园里有两个大木马。", "target_word": "木马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友排着队等着骑木马。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把木马搬到了院子里。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木马的背上画着漂亮的花。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子骑木马的时候，妈妈在旁边看着。", "target_word": "木马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个木马", "label": "量词"}, {"form": "旋转木马", "label": "复合"}, {"form": "木馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小朋友可以骑在上面玩的玩具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2add0e14-7aad-4c53-8a62-eca53035b254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木马", "is_correct": true, "explanation": "木马是玩具，可以坐在上面玩，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水体，不能坐在上面玩。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不能让人坐在上面。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“坐”需要有支撑的实体，不说“坐在空气上”。"}], "explanations": {"木马": "木马是玩具，可以坐在上面玩，符合句意。", "河流": "语义：河流是水体，不能坐在上面玩。", "名字": "语义：名字是抽象的称呼，不能让人坐在上面。", "空气": "搭配：“坐”需要有支撑的实体，不说“坐在空气上”。"}, "sentence_index": 0, "correct_answer": "木马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推着木马去市场买菜，东西装了一车。", "explanation": "这里应该用〈小车〉。木马是供孩子骑坐的玩具，不能推着运东西。"}, {"text": "他把水倒进木马里，水很快就满了。", "explanation": "这里应该用〈木桶〉。木桶用来盛水，木马是玩具，不能装水。"}, {"text": "他穿着木马去上学。", "explanation": "这里应该用〈鞋子〉。“穿”用于鞋袜、衣服等，木马是供儿童骑坐的玩具，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
